INSERT INTO `institution_program` (`id`, `institution_id`, `program_id`, `level_id`, `name`, `description`, `remarks`, `program_mode_id`, `duration`, `tuition_fee`, `utme_cutoff`, `requirements`, `direct_entry`, `o_level`, `utme_subjects`, `accreditation_body_id`, `accreditation_status_id`, `is_distinguished`, `accreditation_grant_date`, `accreditation_expiry_date`, `created_at`, `updated_at`) VALUES
(1, 'aap', 'mass-communication', 2, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language and Mathematics and any three (3) other subjects from: History, Literature in English, Economics/Commerce, Fine Arts, Government, Biology Physics, Chemistry Basic Electricity Geography, Typewriting, Commerce/Principles of Accounting.', 'Any three (3) subjects from Arts/Social Science/Physical Science.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2, 'aap', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(3, 'aap', 'banking-and-finance', 2, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and any two (2) of Economics, Geography, History, Government, Commerce or Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(4, 'aap', 'business-administration-and-management', 2, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(5, 'aap', 'science-laboratory-technology', 2, 'Science Laboratory Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and two (2) of Physics, Biology/Agricultural Science/Health Science, Chemistry, and two (2) other subjects from Technical Drawing, Metal or Wood Work, Basic Electricity, Geography, Further Mathematics, and Fine Arts. \'O\' Level credit pass in each of the three (3) Basic Science subjects - Biology, Chemistry, Physics and a \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Mathematics, Biology/Agricultural Science or Physics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(6, 'aap', 'statistics', 2, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Basic Science and any three (3) of the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics are compulsory.', 'Any of the three (3): 1. Economics/ Commerce 2. History/Government 3. CRS/IS 4. Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(7, 'aap', 'urban-and-regional-planning', 2, 'Urban and Regional Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Geography and three (3) other subjects from: English Language, Economics/Commerce, Fine Art/Technical Drawing, Further Mathematics, Chemistry, Physics, Biology/Agricultural Science, History/Government Business Methods/Bookkeeping and Principles of Accounting One of the three (3) subjects must be a basic science subject. At least a credit pass in English Language is compulsory.', 'Geography and two (2) other subjects from course requirement.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(8, 'aap', 'computer-science', 2, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, a basic science and three (3) other subjects chosen from the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics is compulsory.', 'Mathematics and any two (2) of Geography, Physics, Economics or Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(9, 'aap', 'computer-engineering-technology', 2, 'Computer Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering a pass in Biology is required. \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics and Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(10, 'aap', 'electrical-electronics-engineering-technology', 2, 'Electrical / Electronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(16, 'aau', 'law', 1, 'Law', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes in Arts or Social Science subjects. (ii) NCE/ND/First Degree (Second Class Lower).', 'Five (5)\'O\' Level credit passes to include English Language, Literature in English and Mathematics.', 'Any three (3) Arts or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17, 'aau', 'accounting', 1, 'Accounting', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(18, 'aau', 'business-administration', 1, 'Business Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(19, 'aau', 'building', 1, 'Building', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes in Mathematics, Physics and Chemistry.', 'Five (5) SSC credit passes in Mathematics, English Language, Physics, Chemistry and any one of Geography, Economics, Arts and Technical drawing. For holders of NTC, the other relevant subjects could be Intro. to Building Construction, Bricklaying, Concreting, Walls, Floors and Ceiling Finishing, Building/Engineering Drawing, Joinery, Carpentry, Gas, Steam Work and Bronze Welding, Cold / Hot Water Supply, Sanitation and Drainage.', 'Mathematics, Physics and Chemistry', 1, NULL, 0, NULL, NULL, NULL, NULL),
(20, 'aau', 'anatomy', 1, 'Anatomy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Biology, Chemistry and Physics in addition to the UTME requirements.', 'Five (5) SSC credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21, 'aau', 'public-administration', 1, 'Public Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22, 'aau', 'agriculture', 1, 'Agriculture', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and one from Biology/Botany/Zoology/Agricultural Science, Economics, Physics, Geography and Geology/Mathematics (Pure & Applied).', 'Five (5) SSC credit passes to include English Language, Biology/Agricultural Science, Chemistry and any one of Mathematics, Physics, Geography and Economics.', 'Chemistry, Biology/Agriculture and any one of Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(23, 'aau', 'civil-engineering', 1, 'Civil Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes in Physics and Mathematics. (ii) ND/HND upper credit at appropriate levels.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics, English Language and one Science subject', 'Physics, Chemistry and Mathematics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(24, 'aau', 'human-nutrition-and-dietetics', 1, 'Human Nutrition and Dietetics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry, Biology and Physics plus the UTME requirement.', 'Five (5) SSC credit passes in English Language, Physics, Chemistry, Biology and Mathematics.', 'Chemistry, Biology and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(25, 'aau', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes in Economics and any one of Mathematics, Statistics, Geography, Physics, Chemistry, Agricultural Science, Accounting, Business Management, History and Government.', 'Five (5)SSC credit passes in English Language, Mathematics, Economics and any two (2) of Arts or Social Science subjects.', 'Economics, Mathematics and any of Government, History, Geography, Literature in English, French and Christian Religious Studies/Islamic Studies.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(26, 'aau', 'medical-laboratory-science', 1, 'Medical Laboratory Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes to include Physics, Chemistry and Biology or Zoology', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology', 'Physics, Chemistry and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(27, 'aau', 'nursing-nursing-science', 1, 'Nursing / Nursing Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes in any two (2) of Physics, Chemistry, Biology and Mathematics (ii) ND Upper Credit in Prosthesis and Orthopaedic Technology. (i) Two (2) \'A\' Level passes in Biology/ Zoology, Chemistry and Physics plus three (3) other \'O\' Level credit passes in Mathematics, Physics and English Language. (ii) NRN or its approved equivalent plus five (5) \'O\' Level credit passes in English Language and four (4) Science subjects chosen from Mathematics, Physics, Chemistry, Biology, Human Anatomy, Physiology and Hygiene, Health Science, Further Mathematics and General Science.', 'Five (5) SSC credit passes including English Language, Physics, Mathematics, Chemistry and Biology.', 'Chemistry, Biology and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(28, 'aau', 'vocational-and-technical-education', 1, 'Vocational and Technical Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE merit in Technical Education. (ii) ND in Mechanical/Electrical or Electronics Engineering.', 'Five (5) SSC credit passes in NTC, City and Guilds Part I or WAEC Technical and Federal Craft Training Certificate including English Language, Mathematics, Technical Drawing, Physics, subject of specialization.', 'Subjects of specialization and Mathematics or Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(29, 'aau', 'education-and-chemistry', 1, 'Education and Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level/NCE passes including Chemistry and one (1) other Science subject.', 'Five (5) SSC credits in Mathematics, Chemistry, English Language and two (2) of Physics, Biology and Agricultural Science.', 'Chemistry and two (2) other subjects chosen from Physics, Biology and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(30, 'aau', 'medicine-and-surgery', 1, 'Medicine and Surgery', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes in Physics, Chemistry and Biology or Zoology in addition to the UTME requirements. (ii) BSC, BOS, etc in relevant programme.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology.', 'Physics, Chemistry and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(31, 'aau', 'physiology', 1, 'Physiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Chemistry, Physics and Biology/Zoology.', 'Five (5) SSC credit passes in English Language, Maths, Physics, Chemistry and Biology.', 'Physics, Chemistry and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(32, 'aau', 'geography-and-regional-planning', 1, 'Geography and Regional Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes including Geography.', 'Five (5)SSC credit passes to include English language, Mathematics and Geography.', 'Geography and any Arts or Social Sciences subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(33, 'aau', 'biochemistry', 1, 'Biochemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Chemistry, Mathematics, Physics and Biology. NCE/ND/HND in related programmes plus the UTME requirements.', 'Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Physics and Biology.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(34, 'aau', 'agricultural-economics-and-extension', 1, 'Agricultural Economics and Extension', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and one of Zoology/Botany/Agricultural Science/Biology, Geography, Mathematics, Physics, Geology, Economics and Health Science.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology/Agricultural Science and one of Geography, Physics and Economics.', 'Chemistry, Biology/ Agricultural Science plus Mathematics or Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(35, 'aau', 'education-and-biology', 1, 'Education and Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NCE/\'A\' Level passes in Biology and one (1) other Science subject.', 'Five (5) SSC credit passes in English Language, Biology, Chemistry, Mathematics and one (1) other subject.', 'Biology and two (2) other subjects from Chemistry, Mathematics and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
