(39, 'aau', 'english-language', 1, 'English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes to include Literature in English and one other Arts subject.', 'Five (5) SSC credit passes to include Literature in English, English Language and three other Arts or Social Science subjects.', 'Literature in English, one other Arts subject and another Arts or Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(40, 'aau', 'education-and-french', 1, 'Education and French', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit in French and one(1) other Arts subject.', 'Five (5) SSC credit passes to include English Language and French.', 'French plus two (2) other Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
