(44, 'aau', 'education-and-history', 1, 'Education and History', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) NCE merit/\'A\' Level passes in History and one (1) other relevant Arts subject.', 'Five (5) SSC credit passes in English Language, History and three (3) relevant Arts subjects.', 'History and any other two (2) subjects chosen from Christian Religious Studies / Islamic Studies, Literature in English, French, Yoruba, Geography/Physics, Economics, Government and Hausa.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(45, 'aau', 'education-and-physics', 1, 'Education and Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Physics and Mathematics. (ii) NCE credit/merit in relevant subjects.', 'Five (5) \'O\' Level credits passes to include English Language, Physics, Mathematics and two (2) other Science subjects or NTC/NBC.', 'Physics, Mathematics or Chemistry plus one (1) other subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(46, 'aau', 'industrial-mathematics', 1, 'Industrial Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes from Mathematics, Physics, Economics or Chemistry. (ii) NCE merit in relevant subjects.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics and two (2) other Science subjects.', 'Mathematics and any two (2) of Physics, Chemistry, Economics, Biology and Agricultural Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(47, 'aau', 'physical-and-health-education', 1, 'Physical and Health Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in any of Biology, Chemistry, Physics and Mathematics. (ii) NCE merit in Physical Education and credit in Arithmetical process or Mathematics. (iii) Diploma in Health Education, Environmental Sanitation, Physical Education, Social work, Health Administration with overall grades of merit plus three (3) \'O\' Level credit passes/TC II merit which should include English Language. (iv) NCE in Biology, Health Education, and Integrated Science with a pass grade plus two (2) \'O\' Level credit passes/TC II merit passes. (v) Registered Nurse plus five (5) \'O\' Level credit passes to include English Language.', 'i) Five (5) SSC credit passes/TC II merit passes including English Language, Biology or its equivalent. ii) Five (5) SSC credit passes/TC II merit passes to include English Language and Mathematics.', 'Biology and any two (2) relevant subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(48, 'aau', 'history-and-international-studies', 1, 'History and International Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'credit) in History/ Government and any other related subject.', 'Language, Geography, Government/History.', 'subjects from the Arts and Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
