(179, 'aaua', 'linguistics-yoruba', 1, 'Linguistics / Yoruba', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes or NCE to include any Language, preferably an African Language.', 'Five (5) SSC credit passes including English Language.', 'Any Language and two (2) other subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(180, 'aaua', 'technical-education', 1, 'Technical Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE merit in two (2) relevant Science subjects plus the UTME requirements. (ii) Two \'A\' Level passes in Physics, Mathematics and Chemistry.', 'Five (5) \'O\' Level credit passes in relevant subjects which must include English Language and Mathematics or NTC/NBC.', 'Physics, Mathematics, Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(181, 'aaua', 'philosophy', 1, 'Philosophy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Any two (2) \'A\' Level passes.', 'Five (5) SSC credit passes to include English Language and four (4) other relevant subjects.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(182, 'aaua', 'philosophy-and-religious-studies', 1, 'Philosophy and Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Any two (2) \'A\' Level passes.', 'Five (5) SSC credit passes to include English Language and four (4) other relevant subjects.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(183, 'aaua', 'religions-and-african-culture', 1, 'Religions and African Culture', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Any two (2) \'A\' Level passes.', 'Five (5) SSC credit passes to include English Language and four (4) other relevant subjects.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(184, 'aaua', 'religious-studies', 1, 'Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level subjects to include Religious Studies (CRS/IRS).', 'Five (5) SSC credit passes to include English Language and CRS/IRS.', 'CRS/IRS and any other two (2) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(185, 'aaua', 'environmental-biology-and-fisheries', 1, 'Environmental Biology and Fisheries', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes or NCE in Biology, Zoology or Botany and one other Science subject', 'Five (5) SSC credit passes in English Language, Mathematics, Biology and two (2) other Science subject.', 'Biology and any two (2) of Physics, Chemistry and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(186, 'aaua', 'mathematics', 1, 'Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, ') Two (2) \'A\' Level passes in Mathematics and any other science subject. (ii) NCE merit in Mathematics and one (1) of Physics, Chemistry or Economics', 'Five (5) SSC credit passes including English Language, Mathematics and Physics or Chemistry.', 'Mathematics and any two (2) of Physics, Chemistry and Economics or Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(187, 'aaua', 'geophysics', 1, 'Geophysics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes in Chemistry and Physics or Mathematics.', 'Five (5) SSC credit passes including English Language, Mathematics, Physics and Chemistry/Biology.', 'English, Physics, Chemistry, and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(188, 'aaua', 'yoruba', 1, 'Yoruba', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes to include Yoruba or Literature in English.', 'Five (5) SSC credit passes to include Yoruba and English Language.', 'Yoruba and two (2) other subjects in Arts or Social Sciences', 1, NULL, 0, NULL, NULL, NULL, NULL),
(189, 'aaua', 'microbiology', 1, 'Microbiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and any one (1) from Biology, Zoology or Botany.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology and Physics.', 'Biology, Chemistry and either Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(190, 'aaua', 'mass-communication', 1, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Arts or Social Science subjects.', 'Five (5) SSC credit passes in English Language and four (4) other subjects in Arts or Social Sciences.', 'Any three (3) from Arts or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(191, 'aaua', 'forestry-and-wildlife-management', 1, 'Forestry and Wildlife Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and Biology or Agric Science or Zoology or Botany', 'Five (5) SSC credit passes in English, Chemistry, Mathematics, Biology and one of Physics, Economics, Further Mathematics and Statistics.', 'Chemistry, Biology/Agriculture and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(192, 'aaua', 'computer-science', 1, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, ') Two (2) \'A\' Level passes in science subjects including Mathematics (ii) NCE merit in Mathematics and one (1) other Science or Social Science subject.', 'Five (5) SSC credit passes to include English Language, Mathematics, Physics and two (2) Chemistry, Biology/Agriculture, Statistics, Additional Mathematics and Computer Studies.', 'English Language, Mathematics, Physics and one (1) of Chemistry, Biology, Agricultural Science, Economics, Geography and Computer Studies.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(193, 'aaua', 'teacher-education-science', 1, 'Teacher Education Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant teaching subjects including Literature in English. (ii) NCE credit or merit in two(2)relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language and Literature in English plus three (3) other Arts or Social Science subjects.', 'Literature in English and one (1) Art and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(194, 'aaua', 'education-and-english-language', 1, 'Education and English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant teaching subjects including Literature in English. (ii) NCE credit or merit in two(2)relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language and Literature in English plus three (3) other Arts or Social Science subjects.', 'Literature in English and one (1) Art and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(195, 'aaua', 'political-science', 1, 'Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Government or History plus two (2) other Social Science/Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(196, 'aaua', 'education-and-religious-studies', 1, 'Education and Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit in Religious Studies and one (1) other Arts subject.', 'Five (5) \'O\' Level credit passes or TC II merit in five (5) subjects including English Language, Religious Studies and three (3) other Arts subjects.', 'Two (2) Arts subject including Religious studies and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(197, 'aaua', 'psychology', 1, 'Psychology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Candidates must possess a Diploma in Psychology from any Institution recognized by the Senate of this University or Registered Nurses (RN) who would be required to take and pass designated courses at the 100 level.', '\'Five (5) \'O\' credit passes in English Language, Mathematics, Biology and any other two (2) subjects from Science, Social Sciences and /or Arts.', 'English and any three (3) subjects from Sciences or Social Sciences,', 1, NULL, 0, NULL, NULL, NULL, NULL),
(198, 'aaua', 'industrial-and-labour-relations', 1, 'Industrial and Labour Relations', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Two (2) \'A\' Level passes chosen from Economics, Accounting, Government, Geography and Statistics. ii) NCE in related programme.', 'Five (5) SSC credit passes to include English Language and Mathematics.', 'Mathematics, Economics plus one other relevant subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(199, 'aaua', 'sociology', 1, 'Sociology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Three (3) Social Science or Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(202, 'aaua', 'educational-management', 1, 'Educational Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Same as in Educational Psychology, Guidance and Counseling.', 'Same as in Educational Psychology, Guidance and Counseling.', 'Economics, Mathematics and one (1) other Social Science/Arts subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(203, 'aaua', 'early-childhood-education', 1, 'Early Childhood Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from relevant subjects.', 'Five (5) \'O\' Level credit passes including English Language.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(204, 'aaua', 'guidance-and-counselling', 1, 'Guidance and Counselling', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes or NCE in two (2) subjects plus the UTME requirements.', 'Five (5) \'O\' Level NTC/NBC credit passes or TC II merit including English Language with \'O\' Level pass in Mathematics.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(205, 'aaua', 'adult-education', 1, 'Adult Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes. (ii) NCE merit in two (2) subjects.', 'Five (5) \'O\' Level credit passes including English Language, Mathematics and three (3) of Literature in English, History, French, Yoruba, Igbo, Hausa, Christian Religious Studies, Islamic Studies, Geography/Physic, Economics and Government or TC II with pass in English Language and four (4) other subjects.', 'Government/History, one (1) Social Science subject and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(206, 'aaua', 'education-and-social-studies', 1, 'Education and Social Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE Social Studies from recognized Colleges. (ii) Two (2) \'A\' Level passes in relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language, Mathematics and any other three (3) subject from the following; Arts and Social Science subjects: Geography, Economics, Government/History, Civic Education, CRS/IRS, Literature in English, Accounting, Commerce and Yoruba', 'English Language and Any three (3) Subject from Social Science/ Arts.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(207, 'aaua', 'education-and-political-science', 1, 'Education and Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant subjects chosen from Government or History, Economics and Geography/Physics.(ii) NCE merit in Government/History, Economics and Geography/Physics.', 'Five (5) \'O\' Level credit passes or equivalent to include English Language, Government/History and three (3) other subjects.', 'Government or History plus two (2) other Arts or Social Sciences subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(208, 'aaua', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Economics and one (1) other relevant subject.(ii) NCE merit/credit in Economics and one (1) other subject.', 'Five (5) \'O\' Level credit passes in English Language, Mathematics, Economics and any other two (2) subjects from the following; Accounting, Commerce Business Method, Government, Book Keeping and Civic Education', 'Economics, English Language, Mathematics and one (1) Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(270, 'abiapoly', 'mechanical-engineering-technology', 2, 'Mechanical Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any one (1) subject from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required.', 'Mathematics, Chemistry and Physics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(271, 'abiapoly', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(272, 'abiapoly', 'architectural-technology', 2, 'Architectural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics, English Language and any two (2) subjects from the following: Biology, Fine Art, Chemistry, History English Language, Geography, Further Mathematics Economics/Commerce, Religious Knowledge, Technical Drawing, Business Method. \'O\' Level pass in Fine Art or Technical Drawing will be an advantage.', 'Mathematics and any two (2) of Physics, Chemistry and Technical Drawing.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(273, 'abiapoly', 'banking-and-finance', 2, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and any two (2) of Economics, Geography, History, Government, Commerce or Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(274, 'abiapoly', 'building-technology', 2, 'Building Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following: Economics/Commerce, Technical Drawing/Fine Art, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, And at least a credit pass in English Language is Compulsory. A pass in Art or Technical Drawing will be an advantage.', 'Mathematics, Physics and Chemistry or Fine Arts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(275, 'abiapoly', 'public-administration', 2, 'Public Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in English Language not Literature in English and Mathematics and any three (3) subjects of the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography, Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Government, History and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(276, 'abiapoly', 'business-administration-and-management', 2, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(277, 'abiapoly', 'quantity-surveying', 2, 'Quantity Surveying', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following Economics/Commerce, Technical Drawing/Fine Arts, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, and \'O\' Level credit pass in English Language is Compulsory. \'O\' Level pass in Art or Technical Drawing is required.', 'Any three (3) of Physics, Mathematics, Geography, Economics, Biology/Agricultural Science', 2, NULL, 0, NULL, NULL, NULL, NULL),
(278, 'abiapoly', 'science-laboratory-technology', 2, 'Science Laboratory Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and two (2) of Physics, Biology/Agricultural Science/Health Science, Chemistry, and two (2) other subjects from Technical Drawing, Metal or Wood Work, Basic Electricity, Geography, Further Mathematics, and Fine Arts. \'O\' Level credit pass in each of the three (3) Basic Science subjects - Biology, Chemistry, Physics and a \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Mathematics, Biology/Agricultural Science or Physics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(279, 'abiapoly', 'office-technology-and-management', 2, 'Office Technology and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) of the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English, Geography, Office Practice, Biology/Agricultural Science, Chemistry, Physics, History/Government, Typewriting, Shorthand', 'Any three (3) of: 1. Mathematics 2. Economics 3. Commerce 4. History/Govt. 5. Geography 6. CRS/IS 7. Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(280, 'abiapoly', 'statistics', 2, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Basic Science and any three (3) of the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics are compulsory.', 'Any of the three (3): 1. Economics/ Commerce 2. History/Government 3. CRS/IS 4. Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(281, 'abiapoly', 'urban-and-regional-planning', 2, 'Urban and Regional Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Geography and three (3) other subjects from: English Language, Economics/Commerce, Fine Art/Technical Drawing, Further Mathematics, Chemistry, Physics, Biology/Agricultural Science, History/Government Business Methods/Bookkeeping and Principles of Accounting One of the three (3) subjects must be a basic science subject. At least a credit pass in English Language is compulsory.', 'Geography and two (2) other subjects from course requirement.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(282, 'abiapoly', 'surveying-and-geoinformatics', 2, 'Surveying and Geoinformatics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any other three (3) subjects from the following: Further Mathematics, Chemistry; Technical Drawing/Fine Art, Geography, Economics/Commerce, Biology/Agricultural Science, English Language, Basic Electricity At least \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Chemistry/Agricultural Science, Biology, Economics and Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(283, 'abiapoly', 'civil-engineering-technology', 2, 'Civil Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering a pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics and Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(284, 'abiapoly', 'computer-science', 2, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, a basic science and three (3) other subjects chosen from the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics is compulsory.', 'Mathematics and any two (2) of Geography, Physics, Economics or Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(285, 'abiapoly', 'computer-engineering-technology', 2, 'Computer Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering a pass in Biology is required. \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics and Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(286, 'abiapoly', 'electrical-electronics-engineering-technology', 2, 'Electrical / Electronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(287, 'abiapoly', 'estate-management-and-valuation', 2, 'Estate Management and Valuation', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, English Language, a basic science subject and any two (2) from the following: Geography, Economics/Commerce, Physics, Biology, Chemistry, Technical Drawing, Fine Art, Woodwork, Literature, Metal Work, Principles of Accounts and Book Keeping Government', 'Mathematics and any two (2) of Economics, Arts, Physics, Chemistry, Biology', 2, NULL, 0, NULL, NULL, NULL, NULL),
(288, 'abiapoly', 'food-technology', 2, 'Food Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Chemistry and Biology/Agricultural Science/Health Science and any two (2) of the following: Physics, Technical Drawing, Economics/Commerce, English Language, Additional/Further Mathematics, Home Economics, Food and Nutrition, Geography, Physics and English Language.', 'Biology/Agricultural Science and any two (2) of the following: Physics, Chemistry, Mathematics and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(301, 'absu', 'accounting', 1, 'Accounting', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Economics, Accounting, Business Management, Government and Geography.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and any other two (2) other subjects. For NBC holders, the other two (2) relevant subjects could be from any of Principles of Accounts, Commerce, Office Practice and Secretarial Duties.?', 'Mathematics, Economics plus any Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(302, 'absu', 'banking-and-finance', 1, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Accounting, Economics, Management, Mathematics, Geography and Statistics.', 'Five (5) SSC credit passes to include: English Language, Mathematics and any other subjects. For NBC, the other two (2) relevant subjects could be from any of the following; Accounting, Principles of Accounts, Commerce, Office Practice and Economics.', 'Mathematics, Economics, plus any one (1) of Government and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(303, 'absu', 'management', 1, 'Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Economics, Accounts, Business Management, Government, Geography or Statistics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics, plus any two (2) of Accounting, Business Methods, Commerce, Government, Geography, and Statistics.', 'Mathematics, Economics and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(304, 'absu', 'business-administration', 1, 'Business Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Economics, Accounts, Business Management, Government, Geography or Statistics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics, plus any two (2) of Accounting, Business Methods, Commerce, Government, Geography, and Statistics.', 'Mathematics, Economics and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(305, 'absu', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Economics and any one (1) of Mathematics, Statistics, Geography, Physics, Chemistry, Agricultural Science, Accounting, Business Management, History and Government.', 'Five (5) SSC credit passes in English Language, Mathematics, Economics and any two (2) of Arts or Social Science subjects.', 'Economics, Mathematics and any of Government, History, Geography, Literature in English, French and CRS/IS.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(306, 'absu', 'law', 1, 'Law', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes in Arts or Social Science subjects. (ii) NCE/ND/First Degree (Second Class Lower).', 'Five (5)\'O\' Level credit passes to include English Language, Literature in English and Mathematics.', 'Any three (3) Arts or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(307, 'absu', 'building-technology', 1, 'Building Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes in Mathematics, Physics and Chemistry.', 'Five (5) SSC credit passes in Mathematics, English Language, Physics, Chemistry and any one of Geography, Economics, Arts and Technical drawing. For holders of NTC, the other relevant subjects could be Intro. to Building Construction, Bricklaying, Concreting, Walls, Floors and Ceiling Finishing, Building/Engineering Drawing, Joinery, Carpentry, Gas, Steam Work and Bronze Welding, Cold / Hot Water Supply, Sanitation and Drainage.', 'Mathematics, Physics and Chemistry', 1, NULL, 0, NULL, NULL, NULL, NULL),
(308, 'absu', 'anatomy', 1, 'Anatomy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Biology, Chemistry and Physics in addition to the UTME requirements.', 'Five (5) SSC credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(309, 'absu', 'civil-engineering', 1, 'Civil Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes in Physics and Mathematics. (ii) ND/HND upper credit at appropriate levels.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics, English Language and one Science subject', 'Physics, Chemistry and Mathematics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(310, 'absu', 'educational-management-and-planning', 1, 'Educational Management and Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2)\'A\' Level passes from Literature in English, History, Christian Religious Studies/Islamic Studies, Hausa, Yoruba and Igbo with \'O\' Level pass in Mathematics. (ii) NCE merit in the subjects listed above.', '(i) Five (5)\'O\' Level credit passes to include English Language, Mathematics and Economics. (ii) Five (5) TC II merit including English Language and Mathematics.', 'Any three (3) of Literature In English, History, French, Geography/Physics, Economics and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(311, 'absu', 'medical-laboratory-science', 1, 'Medical Laboratory Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes to include Physics, Chemistry and Biology or Zoology', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology', 'Physics, Chemistry and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
