(1357, 'akamkpa', 'history-social-studies', 3, 'History / Social Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, History and any two (2) of Geography, Government, Economics and Christian Religious Studies/Islamic Studies.', 'History and any one (1) Arts and one (1) Social Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(1358, 'akamkpa', 'home-economics', 3, 'Home Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics and any three (3) of the followings: 1. Agricultural Science 2. Biology 3. Chemistry 4. General Science 5. Health Science 6. Home Management/ 7. Hotel and Catering 8. Food and Nutrition 9. Integrated Science 10. Physical and Health Education/Physical Education 11. Physics 12. Economics 13. General Metal Work 14. Building/Engineering Drawing 15. Men/Ladies Garment Construction and Finishing 16. Men/Ladies Textile Design 17. Spinning 18. Weaving 19. Surface Design and Printing 20. Bleaching, Dyeing and Finishing 21. Basic Electricity GROUP A: Home Economics, Home Management, Cookery, Needle Work and Dress Making, Clothing and Textile, Food and Nutrition, Hotel Management and Catering. GROUP B: Biology, Chemistry, Physics, Integrated Science, Health Science, Agricultural Science, Mathematics/Arithmetic Process/Basic Mathematics, Economics, Physical and Health Education.', 'Any three (3) of Chemistry, Agricultural Science, Home Economics, Economics and Mathematics.', 3, NULL, 0, NULL, NULL, NULL, NULL),
