(2801, 'atibauni', 'banking-and-finance', 1, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2)\'A\' Level passes in Accounting or Economics and one other subject. (ii) NCE merit in relevant subjects. (iii) ND credit. (iv) Foundation International exam such as ICAN, ACCA, ICMA, GPFA.', 'Five (5)SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, one Social Science subject and any other subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(2802, 'atibauni', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes in Economics and any one of Mathematics, Statistics, Geography, Physics, Chemistry, Agricultural Science, Accounting, Business Management, History and Government.', 'Five (5)SSC credit passes in English Language, Mathematics, Economics and any two (2) of Arts or Social Science subjects.', 'Economics, Mathematics and any of Government, History, Geography, Literature in English, French and Christian Religious Studies/Islamic Studies.', 1, NULL, 0, NULL, NULL, NULL, NULL),
