(2804, 'atibauni', 'nursing-nursing-science', 1, 'Nursing / Nursing Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes in any two (2) of Physics, Chemistry, Biology and Mathematics (ii) ND Upper Credit in Prosthesis and Orthopaedic Technology. (i) Two (2) \'A\' Level passes in Biology/ Zoology, Chemistry and Physics plus three (3) other \'O\' Level credit passes in Mathematics, Physics and English Language. (ii) NRN or its approved equivalent plus five (5) \'O\' Level credit passes in English Language and four (4) Science subjects chosen from Mathematics, Physics, Chemistry, Biology, Human Anatomy, Physiology and Hygiene, Health Science, Further Mathematics and General Science.', 'Five (5) SSC credit passes including English Language, Physics, Mathematics, Chemistry and Biology.', 'Chemistry, Biology and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(2805, 'atibauni', 'criminology-and-security-studies', 1, 'Criminology and Security Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes in Economics and any one of Mathematics, Statistics, Geography, Physics, Chemistry, Agricultural Science, Accounting, Business Management, History and Government.', 'Five (5)SSC credit passes in English Language, Mathematics, Economics and any two (2) of Arts or Social Science subjects.', 'Economics, Mathematics and any of Government, History, Geography, Literature in English, French and Christian Religious Studies/Islamic Studies.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(2806, 'atibauni', 'biochemistry', 1, 'Biochemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Chemistry, Mathematics, Physics and Biology. NCE/ND/HND in related programmes plus the UTME requirements.', 'Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Physics and Biology.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(2807, 'atibauni', 'physics', 1, 'Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NCE/Two (2) \'A\' Level passes in Physics and Mathematics or Chemistry.', 'Five (5) SSC credit passes in English Language, Physics, Chemistry, Mathematics and any other Science subject from Further Mathematics and Biology or Agricultural Science.', 'Physics, Mathematics and Chemistry or Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
