(2815, 'atibauni', 'biology', 1, 'Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Two (2) \'A\' Level passes from Chemistry, Biology, Botany/Zoology. (ii) NCE merit accepted.', 'Five (5) SSC credit passes to include English Language, Biology, Chemistry and Mathematics/Physics.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(2830, 'auchipoly', 'hospitality-management', 2, 'Hospitality Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science and two (2) of Physics, Chemistry, Mathematics and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2831, 'auchipoly', 'ceramics-technology', 2, 'Ceramics Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science/Mathematics, Physics and Chemistry and two (2) others from Biology/Agricultural Science, Woodwork, Metalwork, Technical/Engineering Drawing, Fine Art, Economics Basic Electricity, Geography Further Mathematics plus \'O\' Level pass in English Language.', 'Mathematics, Physics, Fine Arts or Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2832, 'auchipoly', 'mass-communication', 2, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language and Mathematics and any three (3) other subjects from: History, Literature in English, Economics/Commerce, Fine Arts, Government, Biology Physics, Chemistry Basic Electricity Geography, Typewriting, Commerce/Principles of Accounting.', 'Any three (3) subjects from Arts/Social Science/Physical Science.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2833, 'auchipoly', 'mechanical-engineering-technology', 2, 'Mechanical Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any one (1) subject from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required.', 'Mathematics, Chemistry and Physics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2834, 'auchipoly', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2835, 'auchipoly', 'agricultural-technology', 2, 'Agricultural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. At least \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science, Chemistry and any other Science subject', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2836, 'auchipoly', 'agricultural-engineering-technology', 2, 'Agricultural Engineering / Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, English Language, Physics and any two (2) of the following: Biology/Agricultural Science Chemistry Technical Drawing Basic Electronics/Basic Electricity Auto Mechanics Metal Work Further Mathematics Food and Nutrition Geography', 'Mathematics and Physics/Technical Drawing, Chemistry or any two (2) Science subjects.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2837, 'auchipoly', 'agricultural-and-bioenvironmental-engineering-technology', 2, 'Agricultural and Bioenvironmental Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, English Language, Physics and any two (2) of the following: Biology/Agricultural Science Chemistry Technical Drawing Basic Electronics/Basic Electricity Auto Mechanics Metal Work Further Mathematics Food and Nutrition Geography', 'Mathematics and Physics/Technical Drawing, Chemistry or any two (2) Science subjects.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2838, 'auchipoly', 'architectural-technology', 2, 'Architectural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics, English Language and any two (2) subjects from the following: Biology, Fine Art, Chemistry, History English Language, Geography, Further Mathematics Economics/Commerce, Religious Knowledge, Technical Drawing, Business Method. \'O\' Level pass in Fine Art or Technical Drawing will be an advantage.', 'Mathematics and any two (2) of Physics, Chemistry and Technical Drawing.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2839, 'auchipoly', 'arts-and-industrial-design', 2, 'Arts and Industrial Design', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Fine Art Mathematics and any two (2) of the following: History/Government Chemistry/Physical Science, Biology/Agricultural Science, Literature in English, Clothing and Textiles, Religious Knowledge, Economics/Commerce Geography, Home Economics', 'Fine Art and any two (2) of History, Chemistry, Mathematics, Biology and a Nigerian Language.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2840, 'auchipoly', 'banking-and-finance', 2, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and any two (2) of Economics, Geography, History, Government, Commerce or Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2841, 'auchipoly', 'mineral-and-petroleum-resources-engineering-technology', 2, 'Mineral and Petroleum Resources Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any one (1) subject from Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce.', 'Mathematics, Physics, Chemistry or Technical Drawing.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2842, 'auchipoly', 'building-technology', 2, 'Building Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following: Economics/Commerce, Technical Drawing/Fine Art, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, And at least a credit pass in English Language is Compulsory. A pass in Art or Technical Drawing will be an advantage.', 'Mathematics, Physics and Chemistry or Fine Arts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
