(2847, 'auchipoly', 'polymer-technology', 2, 'Polymer Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and two (2) of the following: Economics, Technical Drawing/Art, Further Mathematics, Biology/Agricultural Science, Metal Work, Woodwork, \'O\' Level credit passes in English Language and Biology are compulsory.', 'Chemistry, Physics and Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2848, 'auchipoly', 'office-technology-and-management', 2, 'Office Technology and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) of the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English, Geography, Office Practice, Biology/Agricultural Science, Chemistry, Physics, History/Government, Typewriting, Shorthand', 'Any three (3) of: 1. Mathematics 2. Economics 3. Commerce 4. History/Govt. 5. Geography 6. CRS/IS 7. Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2849, 'auchipoly', 'statistics', 2, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Basic Science and any three (3) of the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics are compulsory.', 'Any of the three (3): 1. Economics/ Commerce 2. History/Government 3. CRS/IS 4. Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(2850, 'auchipoly', 'marketing', 2, 'Marketing', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
