(3088, 'babcock', 'computer-science-and-information-technology', 1, 'Computer Science and Information Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in science subjects including Mathematics (ii) NCE merit in Mathematics and one (1) other Science or Social Science subject.', 'Five (5) SSC credit passes to include English Language, Mathematics, Physics plus two (2) other Science subjects.', 'BABCOCK will accept any three of the following: Mathematics, Physics and one (1) of Biology, Chemistry, Agric Science, Economics, Geography and Technical Drawing.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(3089, 'babcock', 'political-science', 1, 'Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Government or History plus two (2) other Social Science/Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(3090, 'babcock', 'political-science-international-law-and-diplomacy', 1, 'Political Science / International Law and Diplomacy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Government or History plus two (2) other Social Science/Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(3091, 'babcock', 'information-and-communication-technology', 1, 'Information and Communication Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Two (2) \'A\' Level passes in science subjects including Mathematics (ii) NCE merit in Mathematics and one (1) other Science or Social Science subject.', 'Five (5) SSC credit passes to include English Language, Mathematics, Physics plus two (2) other Science subjects.', 'Mathematics, Physics and one (1) of Biology, Chemistry, Agric Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(3092, 'babcock', 'social-work', 1, 'Social Work', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in any subjects', 'Five (5) SSC credits including English Language and Mathematics.', 'Mathematics, Economics/Geography and any other subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(3093, 'babcock', 'biology', 1, 'Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Two (2) \'A\' Level passes from Chemistry, Biology, Botany/Zoology. (ii) NCE merit accepted.', 'Five (5) SSC credit passes to include English Language, Biology, Chemistry and Mathematics/Physics.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(3094, 'babcock', 'information-resource-management', 1, 'Information Resource Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Economics, Accounting and Business Management.', 'Five (5) SSC credit passes in English Language, Economics and three (3) other subjects plus at least a pass in Mathematics. For NBC holders, three (3) other Subjects could be from any of the following: Office Practice, Secretarial Duties, Principles of Accounts, Shorthand 80 WPM and Typewriting 35 WPM.', 'ANY three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(3095, 'babcock', 'software-engineering', 1, 'Software Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes ND/NCE at Credit/merit levels and HND lower credit in relevant programmes into 200 and 300 levels.', 'Five (5) SSC credit passes in Mathematics, English Language and any three (3) of the following subjects: Biology, Agricultural Science, Chemistry, Physics, Computer Science, Geography, Technical Drawing, and Economics.', 'Babcock will accept any three of Mathematics, Economics, Chemistry, Physics, Biology, Geography and Technical Drawing.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(3097, 'babcock', 'guidance-and-counselling', 1, 'Guidance and Counselling', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes or NCE in two (2) subjects plus the UTME requirements.', 'Five (5) \'O\' Level NTC/NBC credit passes or TC II merit including English Language with \'O\' Level pass in Mathematics.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(3098, 'babcock', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Economics and one (1) other relevant subject.(ii) NCE merit/credit in Economics and one (1) other subject.', 'Five (5) \'O\' Level credit passes to include English Language, Economics and Mathematics.', 'Economics, Mathematics and one (1) other subject from Geography/Physics, History, Government and Literature in English.', 1, NULL, 0, NULL, NULL, NULL, NULL),
