(3578, 'bells', 'food-science-and-technology', 1, 'Food Science and Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and any of Biology, Physics or Mathematics.HND/ND at Lower Credit in Food Science and Technology or Science and Technology or Science Laboratory Technology and related related disciplines.', 'Five (5) O\' Level Credits in one or two sittings which must include English Language, Mathematics, Chemistry, Biology/Agricultural Science, Physics.', 'English Language, Chemistry, Mathematics/ Physics and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(3579, 'bells', 'food-science-with-business', 1, 'Food Science with Business', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and Biology/Physics/Agric Science/Botany/Zoology.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology/Agricultural Science, Physics, Basic Catering and Food Services, Bakery and Confectionaries, Hotel & Catering Crafty course (Cookery), Hotel & Catering Craft Course (Food /Drinks Services) and Basic Electricity.', 'Chemistry, Mathematics/ Physics and Biology/ Agricultural Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(3580, 'bells', 'microbiology', 1, 'Microbiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes in Biology and Physics/ChemistryND/HND Lower Credit in Science Laboratory Technology, Food Science and Technology and related disciplines.', 'Five (5) O\' Level Credits at one or two sittings which must include the following: English Language, Mathematics, Biology, Chemistry and Physics', 'English Language, Biology, Chemistry and Physics /Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
