INSERT INTO `institution_program` (`id`, `institution_id`, `program_id`, `level_id`, `name`, `description`, `remarks`, `program_mode_id`, `duration`, `tuition_fee`, `utme_cutoff`, `requirements`, `direct_entry`, `o_level`, `utme_subjects`, `accreditation_body_id`, `accreditation_status_id`, `is_distinguished`, `accreditation_grant_date`, `accreditation_expiry_date`, `created_at`, `updated_at`) VALUES
(4081, 'biu', 'mechanical-engineering', 1, 'Mechanical Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes from Chemistry, Physics and Mathematics. (ii) ND upper credit, NCE technical and HND in Mech. Engineering.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics, English Language and any other Science subject.', 'Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4082, 'biu', 'library-and-information-studies', 1, 'Library and Information Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant subject plus the UTME requirements. (ii) NCE merit in relevant subjects.', 'Five (5) SSC credit passes in English Language, Mathematics and three (3) other relevant Arts/Sciences/Social Sciences subjects.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4083, 'biu', 'agricultural-science-and-education', 1, 'Agricultural Science and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) passes at \'A\' Level in Biology /Zoology /Botany and any other Science subject. (ii) NCE merit in Biology and any other Science subject. (iii) NCE merit in Agriculture (Double Major).', 'Five (5) \'O\' Level credit passes or equivalents in English Language, Chemistry, Biology/Agricultural Science., Mathematics and another relevant subject.', 'Any three (3) subjects from Chemistry, Biology, Agriculture, Physics, Economics, Geography and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4084, 'biu', 'education-and-political-science', 1, 'Education and Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant subjects chosen from Government or History, Economics and Geography/Physics.(ii) NCE merit in Government/History, Economics and Geography/Physics.', 'Five (5) \'O\' Level credit passes or equivalent to include English Language, Government/History and three (3) other subjects.', 'Government or History plus two (2) other Arts or Social Sciences subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4085, 'biu', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Economics and one (1) other relevant subject.(ii) NCE merit/credit in Economics and one (1) other subject.', 'Five (5) \'O\' Level credit passes to include English Language, Economics and Mathematics.', 'Economics, Mathematics and one (1) other subject from Geography/Physics, History, Government and Literature in English.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4086, 'biu', 'business-education', 1, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes or NCE merit in two (2) relevant subjects.(ii) NCE merit in Business Education Double Major.', 'Five (5) TC II merit, \'O\' Level or NTC/NBC credit passes including English Language, Mathematics, Economics and two (2) other subjects in the Social Sciences or Arts. For NBC, the other subjects could be from any of the following: Commerce, Office Practice, Principles of Accounts, Secretarial Duties, Typewriting and Shorthand.', 'Mathematics, Economics plus one (1) of Literature in English, History, Government, Geography, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
