(4180, 'bosu', 'education-and-english-language', 1, 'Education and English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Minimum of Merit in NCE English Language and other relevant subjects (English Language as major), From a recognized institution. Plus \'O\' level requirements.', 'Five (5) SSCE credit passes to include English Language, Mathematics and three (3) other Arts or Social Science subjects.', 'Any three (3) Arts or Social Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4181, 'bosu', 'political-science', 1, 'Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Minimum of Lower Credit/Merit ND/HND Political science and other relevant fields from a recognized institution. Plus \'O\' level requirements.', 'Five (5) SSCE credit passes in English Language, Mathematics, Government or History and any other two (2) from Arts or Social Science subjects.', 'Government or History plus two (2) other Social Science/Arts subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4182, 'bosu', 'peace-studies-and-conflict-resolution', 1, 'Peace Studies and Conflict Resolution', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Minimum of Lower Credit/Merit in ND/HND Peace Studies And Conflict Resolution, Social Works, Sociology, Political science, Criminology, Strategic & Security Studies, and other relevant subjects from a recognized institution. Plus \'O\' level requirements.', 'Five (5) SSCE credit passes including English Language, Mathematics, Government/History and any other two (2) from Arts or Social Science subjects.', 'Government/History, Economics and any other one (1) Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4183, 'bosu', 'sociology', 1, 'Sociology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Minimum of Lower Credit/Merit in ND/HND Sociology and other relevant fields from a recognized institution. Plus \'O\' level requirements.', 'Five (5) SSCE credit passes in English Language, Mathematics, Government or History and any other two (2) from Arts or Social Science subjects.', 'Any Three (3) Social Science or Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4184, 'bosu', 'educational-management', 1, 'Educational Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Minimum of Merit in NCE Education subjects From a recognized institution. Plus \'O\' level requirements.', 'Minimum of 5 credits including English Language, Mathematics, Economics and at least two (2) credits in relevant teaching subjects.', 'Economics, Mathematics and one (1) other Social Science/Arts subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4185, 'bosu', 'guidance-and-counselling', 1, 'Guidance and Counselling', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Minimum of Merit in NCE in Arts or social science subjects) From a recognized institution. Plus \'O\' level requirements.', 'Five (5) SSCE credit passes in English Language, Mathematics and any three (3) from Arts or Social Science subjects.', 'Any three (3) Arts or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4186, 'bosu', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Minimum of Merit in NCE Economics, and any other relevant subjects (Economics as major) from a recognized institution. Plus \'O\' level requirements.', 'Five (5) \'O\' Level credit passes to include English Language, Mathematics, Economics and any other two (2) Social Science Subjects.', 'Economics, Mathematics and any two (2) other subjects from Commerce, Geography, History, and Government', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4216, 'bowen', 'business-administration', 1, 'Business Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Economics, Accounts, Business Management, Government, Geography or Statistics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics, plus any two (2) of Accounting, Business Methods, Commerce, Government, Geography, and Statistics.', 'Mathematics, Economics and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4217, 'bowen', 'law', 1, 'Law', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5)\'O\' Level credit passes to include English Language, Literature in English and three other subjects obtained at not more than two sittings. A pass in Mathematics is acceptable.', 'English Language, Literature-in-English and any two (2) other Arts or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4218, 'bowen', 'accounting', 1, 'Accounting', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(I) At least two Passes at GCE Advanced Level, to include Economics and any one of Government, Geography, Mathematics, Business Method and Economic History. (ii) IJMB/JUPEB/NCE/ND/ATS of ICAN/NIM/NIMN/ANAN or approved equivalent. (iii) Holders of HND in Banking and Finance, Accounting, Business Administration and other related disciplines from a recognized Polytechnic.', 'Five (5) O\' Level Credits to include English Language, Mathematics, Economics and any other two subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4220, 'bowen', 'anatomy', 1, 'Anatomy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Biology, Chemistry and Physics in addition to the UTME requirements.', 'Five (5) O\' Level credits in English Language, Mathematics, Physics, Chemistry and Biology.', 'English Language, Biology, Chemistry and Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4221, 'bowen', 'agriculture', 1, 'Agriculture', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE, OND or approved equivalents of at least upper credit in relevant fields.(ii) Two A-Level passes to include Chemistry and any one of the following: Biology/Botany, Zoology/Agricultural Science, Economics, Physics, and Geography. (iii) IJMB at acceptable grade levels.', 'Five (5) five O\' Level credits to include: English Language, Mathematics, Biology/Agricultural Science/Home Economics/ Fisheries, Chemistry and one of Physics, Geography, or Economics.', 'Chemistry, Biology/Agriculture, and Physics/Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4222, 'bowen', 'banking-and-finance', 1, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(I) At least two Passes at GCE Advanced Level, to include Economics and any one of Government, Geography, Mathematics, Business Method, and Economic History. (ii) IJMB/JUPEB/NCE/ND/ATS of ICAN/NIM/NIMN/ANAN or approved equivalent. (iii) Holders of HND in Banking and Finance, Accounting, Business Administration and other related disciplines from a recognized Polytechnic.', 'Five (5) O\' Level Credits to include English Language and Mathematics, one Social Science subject and any other two subjects.', 'English Language, Mathematics, and two other social science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4223, 'bowen', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two GCE Advanced Level passes which must include Economics, and any other subject from Government, Geography, History, Sociology, Psychology, Mathematics, and Further Mathematics. (ii) IJMB/JUPEB/NCE/ND or its approved equivalent at an acceptable grade level.', 'Five (5) O\' Level credits to include English Language, Mathematics, Economics, one social science subject from Geography, Government, History, Civic Education, Sociology, Psychology, and any other subject.', 'English Language, Mathematics, Economics plus any other social science subject or any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4224, 'bowen', 'nutrition-and-dietetics', 1, 'Nutrition and Dietetics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two Advanced Level passes at acceptable grade levels.(ii) NCE/ND or approved equivalent in Food and Nutrition or be a Registered Nurse or approved equivalent in relevant fields', 'Five (5) O\' Level credits in English Language, Mathematics, Physics, Chemistry, and Biology.', 'English Language, Biology, Chemistry and Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4225, 'bowen', 'medical-laboratory-science', 1, 'Medical Laboratory Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Minimum of three Advanced Level GCE/Cambridge/IJMB/JUPEB at Grade C pass in each of Biology, Chemistry, and Physics.(ii) B.Sc. degree in relevant disciplines such as Biology, Zoology/Animal Science, Plant Science/Botany/Plant Biology, Microbiology, Anatomy, Physiology, Biochemistry, Chemistry, Physics, etc; as approved by Senate.(iii) HND in relevant fields as approved by Senate.(iv) Candidates must have completed the compulsory one-year National Youth Service (NYSC) or must have been issued an exemption/exclusion certificate', 'Five (5) O\' Level credits in English Language, Mathematics, Physics, Chemistry, and Biology at not more than two sittings.', 'English Language, Biology, Chemistry and Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4226, 'bowen', 'fisheries-and-aquaculture', 1, 'Fisheries and Aquaculture', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in any of Chemistry, Biology, Botany, Zoology, Agricultural Science Geography, Mathematics (pure & applied), Physics, Geology and Economics. (ii)NCE Agriculture', 'Five (5) SSC credit passes in Biology/Agricultural Science, Chemistry, Mathematics and English Language plus any other Science subject.', 'Chemistry, Biology/Agricultural Science and any other Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4227, 'bowen', 'nursing-nursing-science', 1, 'Nursing / Nursing Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Candidates with RN/SRN plus five (5) O\' level credits including English Language and Mathematics can apply and be admitted to 200 Level.', 'Five (5) O\' Level credits in English Language, Mathematics, Physics, Chemistry, and Biology.', 'English Language, Biology, Chemistry and Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4228, 'bowen', 'public-health', 1, 'Public Health', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Acceptable passes at the IJMB, JUPEB, International Baccalaureate, WAEC and Cambridge \'A\' Level examinations in science subjects (Physics, Chemistry, Biology/Zoology or related disciplines) in addition to fulfilling O\' Level requirements. (ii) B.Sc degree in any of the Biomedical or Biological Sciences not below Second Class Lower division.', 'Five (5) O\' Level credits in English Language, Mathematics, Physics, Chemistry, and Biology (or Health Science) at not more than two sittings.', 'English Language, Biology, Chemistry and Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4229, 'bowen', 'education-and-chemistry', 1, 'Education and Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level/NCE passes including Chemistry and one (1) other Science subject.', 'Five (5) SSC credits in Mathematics, Chemistry, English Language and two (2) of Physics, Biology and Agricultural Science.', 'Chemistry and two (2) other subjects chosen from Physics, Biology and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4230, 'bowen', 'medicine-and-surgery', 1, 'Medicine and Surgery', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Advanced Level GCE/Cambridge/IJMB/JUPEB at an acceptable grade level in three (3) subjects: Physics, Chemistry and Biology/Zoology for MB;BS programme. (ii) Candidates with B. Sc. Second Class Upper Division in a related discipline can apply for the MB;BS programme.', 'Five (5) O\' Level credits in English Language, Mathematics, Physics, Chemistry, and Biology.', 'English Language, Biology, Chemistry and Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4231, 'bowen', 'education-and-computer-science', 1, 'Education and Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Physics or Chemistry.', 'Five (5) SSC credit passes or its equivalents including Mathematics, English Language and three (3) other Science subjects.', 'Mathematics, Physics and one of Biology, Chemistry and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4232, 'bowen', 'physiology', 1, 'Physiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Chemistry, Physics and Biology/Zoology.', 'Five (5) O\' Level credits in English Language, Mathematics, Physics, Chemistry, and Biology.', 'English Language, Biology, Chemistry and Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4233, 'bowen', 'doctor-of-physiotherapy', 1, 'Doctor of Physiotherapy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'A degree in relevant discipline not less than 2nd Class Lower Division can apply.', 'Five (5) O\' Level credits in English Language, Mathematics, Physics, Chemistry, and Biology.', 'English Language, Biology, Chemistry and Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4234, 'bowen', 'biochemistry', 1, 'Biochemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Chemistry, Mathematics, Physics and Biology. NCE/ND/HND in related programmes plus the UTME requirements.', 'Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Physics and Biology.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4235, 'bowen', 'education-and-music', 1, 'Education and Music', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit in Music.', 'Five (5) SSC credit passes including Music and English Language.', 'Music and any other two (2) Arts/Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4236, 'bowen', 'communication-arts', 1, 'Communication Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE to include CRS/Religious Studies.', 'Five (5) SSC credit passes in English Language, CRS and three (3) other relevant subjects.', 'Two (2) Arts subjects including CRS and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4237, 'bowen', 'education-and-biology', 1, 'Education and Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NCE/\'A\' Level passes in Biology and one (1) other Science subject.', 'Five (5) SSC credit passes in English Language, Biology, Chemistry, Mathematics and one (1) other subject.', 'Biology and two (2) other subjects from Chemistry, Mathematics and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4238, 'bowen', 'library-and-information-science', 1, 'Library and Information Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2)\'A\' Level passes in relevant subjects. (ii) NCE/ND in relevant subject/programmes', 'Five (5)SSC credit passes including English Language and Mathematics.', 'Any three (3) Arts or Social Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4239, 'bowen', 'education-and-mathematics', 1, 'Education and Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes/NCE in Mathematics and one (1) Science subject.', 'Five (5) SSC credit passes to include English Language, Mathematics plus one (1) other Science subject.', 'Mathematics and any two (2) of the following Science subjects: Physics, Chemistry and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4240, 'bowen', 'physics', 1, 'Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Physics and Mathematics or Chemistry.', 'Five (5) O\' Level subjects to include English Language, Physics, Mathematics and any other two subjects preferably Chemistry, Further Mathematics, Technical Drawing, Geography, and Biology in that order (A pass in English Language can also apply).', 'English Language, Mathematics, Physics, Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4241, 'bowen', 'theatre-arts', 1, 'Theatre Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two Advanced Level passes in Literature and one other Arts subject. (ii) IJMB/JUPEB at acceptable grade levels. (iii) Diploma in Theatre Arts/Dramatic Arts from an accredited institution.', 'Five (5) O` Level credits to include English Language, Literature-in-English and three other Arts or Social Science subjects.', 'English Language, Literature- in- English and any two Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4242, 'bowen', 'physics-with-solar-energy', 1, 'Physics with Solar Energy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NCE/Two (2) \'A\' Level passes in Physics and Mathematics or Chemistry.', 'Five (5) SSC credit passes in English Language, Physics, Chemistry, Mathematics and any other Science subject from Further Mathematics and Biology or Agricultural Science.', 'Physics, Mathematics and Chemistry or Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4243, 'bowen', 'english-language', 1, 'English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two Advanced Level Passes or equivalent in Literature and other Arts subject. (ii) IJMB/JUPEB at acceptable grade levels.', 'Five (5) O`Level credits to include English Language, Literature- in-English plus at least one other Arts subject.', 'English Language, Literature- in- English and any two Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4244, 'bowen', 'education-and-physics', 1, 'Education and Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Physics and Mathematics. (ii) NCE credit/merit in relevant subjects.', 'Five (5) \'O\' Level credits passes to include English Language, Physics, Mathematics and two (2) other Science subjects or NTC/NBC.', 'Physics, Mathematics or Chemistry plus one (1) other subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4245, 'bowen', 'history-and-international-studies', 1, 'History and International Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two Advanced Level Passes or equivalents in Government and any one other Arts or Social Science subject.(ii) IJMB/JUPEB/International Baccalaureate Certificate at acceptable grade levels. (iii) NCE, ND or approved equivalents with at least Upper Credit in relevant fields.', 'Five O` Level Credits to include English Language, History or Government, Economics plus at least two other Arts or Social Science subjects.', 'English Language, History or Government and Economics and any other subjects from Arts and Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4246, 'bowen', 'chemistry', 1, 'Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Chemistry and any one (1) of Physics, Mathematics or Biology. (ii) ND/NCE with good grades in relevant \'O\' Level subjects.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology.', 'Chemistry and two (2) of Physics, Biology and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4247, 'bowen', 'industrial-chemistry', 1, 'Industrial Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two GCE Advanced Level passes in Chemistry and either Mathematics or Physics. (ii) IJMB/JUPEB/NCE/ND or approved equivalents. (iii) Holders of HND from a recognized Polytechnic with a minimum of lower credit in Chemistry, Applied Chemistry or Industrial Chemistry and Laboratory Technology can be admitted to 300 Level.', 'Five (5) \'O\' Level subjects to include English Language, Chemistry, Physics, Mathematics, and Biology.', 'English Language, Chemistry and any other two of Physics, Mathematics, and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4248, 'bowen', 'statistics', 1, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two GCE Advanced Level passes in Mathematics and any one of Biology, Chemistry, Economics, Statistics, and Physics.(ii) IJMB/JUPEB/NCE/ND or approved equivalent at an acceptable grade level in Mathematics and any one of Biology, Chemistry, Economics, Statistics, and Physics. (iii) Diploma in Statistics from a recognized university is acceptable.', 'Five (5) O\' Level credits to include English Language, Mathematics, Physics and any other two subjects from Chemistry, Biology/ Agricultural Science, Geography, Computer Studies, Economics, Further Mathematics and Technical Drawing.', 'English Language, Mathematics and any other two relevant subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4249, 'bowen', 'plant-biology', 1, 'Plant Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Biology/Botany/Zoology and Chemistry or Physics.', 'Five (5) SSC Credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'Biology, Chemistry and any other Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4250, 'bowen', 'zoology', 1, 'Zoology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes or NCE in Biology, Zoology or Botany and one other Science subject', 'Five (5) SSC credit passes in English Language, Mathematics, Biology and two (2) other Science subject.', 'Biology and any two (2) of Physics, Chemistry and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4251, 'bowen', 'music', 1, 'Music', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two Advanced Level Passes or equivalents including Music or ABRSM grade VIII or ND Music or NCE Music', 'Five (5) O\' Level credit passes in English Language, Mathematics and two other subjects in Arts or Social Science or Science.', 'English Language, Music or any three other subjects in Arts and Social Science or Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4252, 'bowen', 'philosophy', 1, 'Philosophy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Any two (2) \'A\' Level passes.', 'Five (5) SSC credit passes to include English Language and four (4) other relevant subjects.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4253, 'bowen', 'religious-studies', 1, 'Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two Advanced Level Passes or equivalent including Religious Studies.', 'Five (5) O` Level credits must include English Language and four (4) other relevant subjects in any of Arts and Social Science subjects.', 'English Language, Christians Religious Studies and two other relevant subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4254, 'bowen', 'mathematics', 1, 'Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two GCE Advanced Level passes to include Mathematics and any one of Biology, Chemistry, Economics, Statistics, and Physics. (ii) IJMB/JUPEB/NCE/ND or approved equivalent at an acceptable grade level in Mathematics and any one of Biology, Chemistry, Economics, Statistics, and Physics.', 'Five (5) O\' Level credits to include English Language, Mathematics, Physics and any other two subjects from Chemistry, Biology/ Agricultural Science, Geography, Computer Studies, Economics, Further Mathematics, and Technical Drawing.', 'English Language, Mathematics and any other two relevant subjects', 1, NULL, 0, NULL, NULL, NULL, NULL);
INSERT INTO `institution_program` (`id`, `institution_id`, `program_id`, `level_id`, `name`, `description`, `remarks`, `program_mode_id`, `duration`, `tuition_fee`, `utme_cutoff`, `requirements`, `direct_entry`, `o_level`, `utme_subjects`, `accreditation_body_id`, `accreditation_status_id`, `is_distinguished`, `accreditation_grant_date`, `accreditation_expiry_date`, `created_at`, `updated_at`) VALUES
(4255, 'bowen', 'food-science-and-technology', 1, 'Food Science and Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE, OND, or approved equivalents in relevant fields at the upper credit level.(II) Food Technology, Agriculture, Biology, Chemistry, Science Laboratory Technology, Physics, Mathematics, any of the sciences with the requisite \'O\' Level requirement. (iii) Two Advanced Level subjects. (a) Physics and Chemistry or Biology/Agriculture (b) Mathematics/Statistics and Chemistry or Biology/Agriculture(iv) IJMB at acceptable grade levels. (v) In addition to the two Advanced Level papers to be specified by the University, candidates must have credits in three ordinary level subjects.', 'Five (5) O\" Level credit passes in English Language, Mathematics and any other three from Physics, Chemistry, Biology/Agriculture/Geography and any other science-based subjects.', 'English Language, Chemistry, Biology and Mathematics/Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4256, 'bowen', 'microbiology', 1, 'Microbiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least any two GCE Advanced Level passes in Botany, Zoology, Biology and Chemistry.(ii) IJMB/JUPEB/NCE/ND or approved equivalent. (iii) ND holders must possess a minimum of Lower Credit (iv) HND holders must possess a minimum of Lower Credit for admission to 300 Level.', 'Five (5) O\' Level credit passes in English Language and any of Physics, Mathematics, Chemistry, Biology, Geography, Food and Nutrition.', 'English Language, Physics, Chemistry, Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4257, 'bowen', 'mass-communication', 1, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two Advanced Level passes in any Arts or Social Science subjects. This may include Commerce and Financial Accounting.(ii) IJMB/JUPEB/NCE/ND or its approved equivalent. (iii) HND holders with Upper Credit in Mass Communication or related courses.', 'Five (5) O\' Level credits to include English Language, Mathematics, Literature-in-English and two other subjects in Arts, Social Sciences, Business, and General subjects', 'English Language, Literature-in-English and any two (2) others from Government/History, CRS/IRS, Economics, Geography, Commerce.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4259, 'bowen', 'forestry-and-environmental-management', 1, 'Forestry and Environmental Management.', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and Biology or Agric Science or Zoology or Botany.', 'Five (5) SSC credit passes in English, Chemistry, Mathematics, Biology and one of Physics, Economics, Further Mathematics and Statistics.', 'Chemistry, Biology/Agriculture and Physics or Mathematics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4260, 'bowen', 'computer-science', 1, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE/ND or approved equivalent with at least Merit and Lower Credit respectively in the relevant fields. (ii) IJMB, JUPEB, Cambridge Moderated School of Basic Studies, GCE Advanced Level or approved equivalents at acceptable grade levels in Mathematics and Physics', 'Five (5) O\' Level subjects to include English Language, Mathematics, Physics, and any two from Further Mathematics, Biology/Agricultural Science, Chemistry, Economics, Technical Drawing, Basic Electronics/Electronics, Computer Studies, and Data Processing.', 'English Language, Mathematics, Physics and one (1) of Biology, Chemistry, Agricultural Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4261, 'bowen', 'education-and-english-language', 1, 'Education and English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant teaching subjects including Literature in English. (ii) NCE credit or merit in two(2)relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language and Literature in English plus three (3) other Arts or Social Science subjects.', 'Literature in English and one (1) Art and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4262, 'bowen', 'political-science', 1, 'Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two Advanced Level passes to include History/ Government, Civics, Geography, Economics or equivalent in Social Science subjects approved by Senate of Bowen University.(ii) IJMB/JUPEB/NCE/ND or its approved equivalent (iii) HND holders with a minimum of Upper Credit from a recognized Polytechnic in Public Administration, Local Government Studies, and Political Economy.', 'Five (5) O\' Level credits to include English Language, Mathematics, Government (or History) and any other two (2) subjects from Social Science general requirements.', 'English Language, Government plus any other Arts or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4263, 'bowen', 'education-and-religious-studies', 1, 'Education and Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit in Religious Studies and one (1) other Arts subject.', 'Five (5) \'O\' Level credit passes or TC II merit in five (5) subjects including English Language, Religious Studies and three (3) other Arts subjects.', 'Two (2) Arts subject including Religious studies and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4264, 'bowen', 'sociology', 1, 'Sociology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two Advanced Level passes to include Sociology, Psychology, Economics, History or Government, Geography, and Religious Studies.(ii) IJMB/JUPEB/NCE/ND or its approved equivalent. (iii) HND holders with a minimum of Upper Credit from a recognized Polytechnic in approved Sociology related subjects.', 'Five (5) O\' Level credits to include English Language, Mathematics and at least one from Economics, Geography, Government or History and any other two subjects at not more than two sittings.', 'English Language, two other social science subjects plus any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4265, 'bowen', 'pure-and-applied-biology', 1, 'Pure and Applied Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least any two GCE Advanced Level passes in Botany, Zoology, Biology and Chemistry.(ii) IJMB/JUPEB/NCE/ND or approved equivalent. (iii) ND holders must possess a minimum of Lower Credit (iv) HND holders must possess a minimum of Lower Credit for admission to 300 Level.', 'Five (5) O\' Level credit passes in English Language and any of Physics, Mathematics, Chemistry, Biology, Geography, Food and Nutrition.', 'English Language, Physics, Chemistry, Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4266, 'bowen', 'international-relations', 1, 'International Relations', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two Advanced Level passes in relevant subjects.(ii) IJMB/JUPEB/NCE/ND or its approved equivalent (iii) HND holders with a minimum of Upper Credit from a recognized Polytechnic in Public Administration, Local Government Studies, and Political Economy.', 'Five (5) O\' Level credits to include English Language, Mathematics, Government or History or Civics and any other two (2) subjects from Social Science general requirements. A credit in a foreign language will be an added advantage', 'English Language, Government or History and any other two Social Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4267, 'bowen', 'industrial-relations-and-personnel-management', 1, 'Industrial Relations and Personnel Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two passes at GCE Advanced Level to include Economics, Government, History and Geography. (ii) IJMB/JUPEB/NCE. (iii) CIPM successful completion of Foundation II Exam stage(iv) OND in relevant discipline. (v) HND in relevant discipline. (vi) Final Certificate of relevant Professional Bodies.', 'Five (5) O\' Level Credits to include English Language, Mathematics, Economics and any other two subjects at not more than two (2) sittings.', 'English Language, Mathematics, Economics plus any other social science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4268, 'bowen', 'electrical-electronics-engineering', 1, 'Electrical / Electronics Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) National Diploma (ND) with upper credit pass in the relevant field of study for admission into 200 level or Higher National Diploma (HND) in the relevant field for admission into 300 level (ii) GCE \'A\' Level Passes in Mathematics, Physics and Chemistry in addition to \'O\' level requirements. (iii) Candidates with JUPEB or IJMB at acceptable grade levels.', 'Five (5) O\' Level credits to include English Language, Mathematics, Physics, Chemistry, and any other Science subject.', 'English Language, Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4269, 'bowen', 'mechatronics-engineering', 1, 'Mechatronics Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) National Diploma (ND) with upper credit pass in the relevant field of study for admission into 200 level or Higher National Diploma (HND) in the relevant field for admission into 300 level.,(ii) GCE \'A\' Level Passes in Mathematics, Physics, and Chemistry in addition to \'O\' level requirements. (iii) Candidates with JUPEB or IJMB at acceptable grade levels.', 'Five (5) O\' Level credits to include English Language, Mathematics, Physics, Chemistry, and any other Science subject.', 'English Language, Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4270, 'bowen', 'educational-management', 1, 'Educational Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Same as in Educational Psychology, Guidance and Counseling.', 'Same as in Educational Psychology, Guidance and Counseling.', 'Economics, Mathematics and one (1) other Social Science/Arts subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4271, 'bowen', 'agricultural-science-and-education', 1, 'Agricultural Science and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) passes at \'A\' Level in Biology /Zoology /Botany and any other Science subject. (ii) NCE merit in Biology and any other Science subject. (iii) NCE merit in Agriculture (Double Major).', 'Five (5) \'O\' Level credit passes or equivalents in English Language, Chemistry, Biology/Agricultural Science., Mathematics and another relevant subject.', 'Any three (3) subjects from Chemistry, Biology, Agriculture, Physics, Economics, Geography and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4272, 'bowen', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Economics and one (1) other relevant subject.(ii) NCE merit/credit in Economics and one (1) other subject.', 'Five (5) \'O\' Level credit passes to include English Language, Economics and Mathematics.', 'Economics, Mathematics and one (1) other subject from Geography/Physics, History, Government and Literature in English.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4273, 'bowen', 'business-education', 1, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes or NCE merit in two (2) relevant subjects.(ii) NCE merit in Business Education Double Major.', 'Five (5) TC II merit, \'O\' Level or NTC/NBC credit passes including English Language, Mathematics, Economics and two (2) other subjects in the Social Sciences or Arts. For NBC, the other subjects could be from any of the following: Commerce, Office Practice, Principles of Accounts, Secretarial Duties, Typewriting and Shorthand.', 'Mathematics, Economics plus one (1) of Literature in English, History, Government, Geography, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4279, 'bestpotech', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(4280, 'bestpotech', 'business-administration-and-management', 2, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(4281, 'bestpotech', 'science-laboratory-technology', 2, 'Science Laboratory Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and two (2) of Physics, Biology/Agricultural Science/Health Science, Chemistry, and two (2) other subjects from Technical Drawing, Metal or Wood Work, Basic Electricity, Geography, Further Mathematics, and Fine Arts. \'O\' Level credit pass in each of the three (3) Basic Science subjects - Biology, Chemistry, Physics and a \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Mathematics, Biology/Agricultural Science or Physics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(4282, 'bestpotech', 'computer-science', 2, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, a basic science and three (3) other subjects chosen from the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics is compulsory.', 'Mathematics and any two (2) of Geography, Physics, Economics or Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(4283, 'bestpotech', 'computer-engineering-technology', 2, 'Computer Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering a pass in Biology is required. \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics and Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(4284, 'bestpotech', 'electrical-electronics-engineering-technology', 2, 'Electrical / Electronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(4286, 'bsu', 'accounting', 1, 'Accounting', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Economics, Accounting, Business Management, Government and Geography.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and any other two (2) other subjects. For NBC holders, the other two (2) relevant subjects could be from any of Principles of Accounts, Commerce, Office Practice and Secretarial Duties.?', 'Mathematics, Economics plus any Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4287, 'bsu', 'business-management', 1, 'Business Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Economics, Accounts, Business Management, Government, Geography or Statistics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics, plus any two (2) of Accounting, Business Methods, Commerce, Government, Geography, and Statistics.', 'Mathematics, Economics and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4288, 'bsu', 'law', 1, 'Law', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes in Arts or Social Science subjects. (ii) NCE/ND/First Degree (Second Class Lower).', 'Five (5)\'O\' Level credit passes to include English Language, Literature in English and Mathematics.', 'Any three (3) Arts or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
