(4481, 'calabar', 'agricultural-science-and-education', 1, 'Agricultural Science and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) passes at \'A\' Level in Biology /Zoology /Botany and any other Science subject. (ii) NCE merit in Biology and any other Science subject. (iii) NCE merit in Agriculture (Double Major).', 'Five (5) \'O\' Level credit passes or equivalents in English Language, Chemistry, Biology/Agricultural Science., Mathematics and another relevant subject.', 'Any three (3) subjects from Chemistry, Biology, Agriculture, Physics, Economics, Geography and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4482, 'calabar', 'adult-education', 1, 'Adult Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes. (ii) NCE merit in two (2) subjects.', 'Five (5) \'O\' Level credit passes including English Language, Mathematics and three (3) of Literature in English, History, French, Yoruba, Igbo, Hausa, Christian Religious Studies, Islamic Studies, Geography/Physic, Economics and Government or TC II with pass in English Language and four (4) other subjects.', 'Government/History, one (1) Social Science subject and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4483, 'calabar', 'education-and-social-studies', 1, 'Education and Social Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE Social Studies from recognized Colleges. (ii) Two (2) \'A\' Level passes in relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language plus two (2) Arts /Social Science subjects.', 'Any three (3) of Christian Religious Studies, Economics, Geography/Physics, Government, History and Islamic Studies.', 1, NULL, 0, NULL, NULL, NULL, NULL),
