(4485, 'calabar', 'education-and-political-science', 1, 'Education and Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant subjects chosen from Government or History, Economics and Geography/Physics.(ii) NCE merit in Government/History, Economics and Geography/Physics.', 'Five (5) \'O\' Level credit passes or equivalent to include English Language, Government/History and three (3) other subjects.', 'Government or History plus two (2) other Arts or Social Sciences subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4486, 'calabar', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Economics and one (1) other relevant subject.(ii) NCE merit/credit in Economics and one (1) other subject.', 'Five (5) \'O\' Level credit passes to include English Language, Economics and Mathematics.', 'Economics, Mathematics and one (1) other subject from Geography/Physics, History, Government and Literature in English.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(4487, 'calabar', 'business-education', 1, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes or NCE merit in two (2) relevant subjects.(ii) NCE merit in Business Education Double Major.', 'Five (5) TC II merit, \'O\' Level or NTC/NBC credit passes including English Language, Mathematics, Economics and two (2) other subjects in the Social Sciences or Arts. For NBC, the other subjects could be from any of the following: Commerce, Office Practice, Principles of Accounts, Secretarial Duties, Typewriting and Shorthand.', 'Mathematics, Economics plus one (1) of Literature in English, History, Government, Geography, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL);
