(5653, 'crawford', 'agricultural-economics-and-farm-management', 1, 'Agricultural Economics and Farm Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and one of Zoology/Botany/Agricultural Science/Biology, Geography, Mathematics, Physics, Geology, Economics and Health Science.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology/Agricultural Science and one of Geography, Physics and Economics.', 'Chemistry, Biology/ Agricultural Science and Mathematics or Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5654, 'crawford', 'criminology-and-security-studies', 1, 'Criminology and Security Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in any three (3) subjects: Business Management, History, Economics, Government, and any of the Arts and Social Sciences. A pass in Mathematics is required', 'Five (5) O\' credit passes in English Language and any other four (4) credit passes in Arts and Social Science subject. A pass in Mathematics is required.', 'Any three (3) Social Science or Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
