(5909, 'delar', 'agricultural-science', 3, 'Agricultural Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'SSC credit passes in English Language and any three (3) of 1. Agricultural Science 2. Mathematics 3. Chemistry 4. Biology 5. Health Science 6. Integrated/Rural Science 7. Physics 8. Nature Study and 9. General Science. NB GROUP A: 1. Agricultural Science 2. Biology 3. Nutrition 4. Health Science. 5. Applied Biology GROUP B: 1. Physics 2. Chemistry 3. Mathematics 4.Basic Mathematics/Arithmetic Process 5. Economics 6. Geography 7. Social Studies 8. Integrated Science 9. General Science', 'Agricultural Science, Chemistry, Biology/General Science or Mathematics.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5910, 'delar', 'christian-religious-studies-english', 3, 'Christian Religious Studies / English', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Christian Religious Studies and any other two (2) of Economics/Commerce, Government/History, Government/Social Studies.', 'Christian Religious Studies and any other of History/Government, Geography, Social Studies, Economics/Commerce.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5911, 'delar', 'integrated-science-mathematics-education', 3, 'Integrated Science / Mathematics Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics and any three (3) of the following 1. Biology/Agricultural Science 2. Chemistry 3. Physics and 4. General Science', 'Mathematics and any two (2) of: Biology, Physics and Chemistry.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5912, 'delar', 'christian-religious-studies-yoruba', 3, 'Christian Religious Studies / Yoruba', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Christian Religious Studies, Yoruba, and any other subject.', 'Yoruba, Christian Religious Studies and any other Arts subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5913, 'delar', 'integrated-science-physics', 3, 'Integrated Science / Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics Physics and any two (2) Science subjects', 'Physics and any other two (2) Science subjects.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5914, 'delar', 'computer-education-chemistry', 3, 'Computer Education / Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Physics and any other Science subject.', 'Mathematics, Chemistry/Physics and any other Science subject', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5915, 'delar', 'computer-education-economics', 3, 'Computer Education / Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Economics, Physics and any other Science/Social Science subject.', 'Any three (3) of Economics, Mathematics/Physics and Chemistry.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5916, 'delar', 'computer-science-education-integrated-science', 3, 'Computer Science Education / Integrated Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Biology/Agricultural Science and Chemistry.', 'Biology/Agricultural Science, Physics and Chemistry.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5917, 'delar', 'computer-science-education-mathematics', 3, 'Computer Science Education / Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics and any two (2) Science subjects.', 'Mathematics and any other two (2) Science subjects.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5918, 'delar', 'computer-education-physics', 3, 'Computer Education / Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics and any other two (2) Science subjects.', 'Mathematics, Physics and any other Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5919, 'delar', 'primary-education-studies', 3, 'Primary Education Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5)SSC credits including English Language.', 'English Language and any other three (3) subjects.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5920, 'delar', 'computer-science-political-science', 3, 'Computer Science / Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5)SSC credit passes in English Language, Mathematics, Physics, Government and any other Science/Social Science subject.', 'Mathematics/Physics, Government and any other Science/Social Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5921, 'delar', 'economics-english', 3, 'Economics / English', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Economics, Literature in English and any other Arts/Social Science subject.', 'Economics, Literature in English and any other subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5922, 'delar', 'mathematics-physics', 3, 'Mathematics / Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics and two (2) other Science subjects.', 'Mathematics, Physics and any other Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5923, 'delar', 'economics-political-science', 3, 'Economics / Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5)SSC credit passes in English Language, Mathematics, Economics and any other Social Science subjects.', 'Economics, Government/History and any other Social Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5924, 'delar', 'mathematics-social-studies', 3, 'Mathematics / Social Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Government/History, one (1) Science and one (1) Social Science subject.', 'Mathematics, one (1) Science and one (1) Social Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5925, 'delar', 'social-studies-yoruba', 3, 'Social Studies / Yoruba', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Government/History, Yoruba, one (1) Arts/Social Science subject.', 'Government/History, Yoruba, one (1) Arts/Social Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5926, 'delar', 'biology-chemistry', 3, 'Biology / Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes, in English Language, Mathematics, Biology, Chemistry and other Science subject.', 'Biology, Chemistry any other Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5927, 'delar', 'biology-integrated-science', 3, 'Biology / Integrated Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Biology, Chemistry/Physics and any other Science subject.', 'Biology, Chemistry/Physics and any other Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5928, 'delar', 'biology-mathematics', 3, 'Biology / Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes, in English Language, Mathematics, Biology, and any other two (2) Science subjects.', 'Mathematics, Biology and any other Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5929, 'delar', 'yoruba-social-studies', 3, 'Yoruba / Social Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Government/History, Yoruba and one (1) Arts/subject.', 'Yoruba, Government/History and one (1)Arts/Social Science.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(5954, 'delsu', 'banking-and-finance', 1, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Accounting, Economics, Management, Mathematics, Geography and Statistics.', 'Five (5) SSC credit passes to include: English Language, Mathematics and any other subjects. For NBC, the other two (2) relevant subjects could be from any of the following; Accounting, Principles of Accounts, Commerce, Office Practice and Economics.', 'Mathematics, Economics, plus any one (1) of Government and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5955, 'delsu', 'botany', 1, 'Botany', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Economics, Accounts, Business Management, Government, Geography or Statistics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics, plus any two (2) of Accounting, Business Methods, Commerce, Government, Geography, and Statistics.', 'Mathematics, Economics and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5956, 'delsu', 'law', 1, 'Law', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Candidate must possess GCE A\'Level passes in two (2) subjects one of which must include Literature in English with a minimum of 12 points. ii) Credit in DELSU Diploma in Law iii) Degrees in the Humanities with a second class upper division is accepted for Law.', 'Candidate must possess at least five (5) credit passes which must include English Language, Literature in English and Mathematics in not more than two sittings and two other subjects from Arts and Social Sciences.', 'English Language, English Literature and any other two subject in Art/Social Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5957, 'delsu', 'accounting', 1, 'Accounting', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5958, 'delsu', 'business-administration', 1, 'Business Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5959, 'delsu', 'chemical-engineering', 1, 'Chemical Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes in Physics, Chemistry and Mathematics.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics and English Language and any other Science subject.', 'Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5960, 'delsu', 'anatomy', 1, 'Anatomy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Biology, Chemistry and Physics in addition to the UTME requirements.', 'Five (5) SSC credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5961, 'delsu', 'agriculture', 1, 'Agriculture', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and one from Biology/Botany/Zoology/Agricultural Science, Economics, Physics, Geography and Geology/Mathematics (Pure & Applied).', 'Five (5) SSC credit passes to include English Language, Biology/Agricultural Science, Chemistry and any one of Mathematics, Physics, Geography and Economics.', 'Chemistry, Biology/Agriculture and any one of Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5962, 'delsu', 'civil-engineering', 1, 'Civil Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes in Physics and Mathematics. (ii) ND/HND upper credit at appropriate levels.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics, English Language and one Science subject', 'Physics, Chemistry and Mathematics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5963, 'delsu', 'fisheries', 1, 'Fisheries', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in any of Chemistry, Biology, Botany, Zoology, Agricultural Science Geography, Mathematics (pure & applied), Physics, Geology and Economics. (ii)NCE Agriculture', 'Five (5) SSC credit passes in Biology/Agricultural Science, Chemistry, Mathematics and English Language plus any other Science subject.', 'Chemistry, Biology/Agricultural Science and any other Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5964, 'delsu', 'medical-biochemistry', 1, 'Medical Biochemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) HSC or GCE A\' Level passes in Physics, Chemistry and Biology with a minimum of 11 points.(ii) Zoology (Botany may be accepted in lieu of Biology or Zoology)(iii) First degree in relevant Biological Sciences not below Second Class Lower Division', 'Candidates should possess SSCE or NECO or GCE O\' Level or its equivalent with credit pass in at least five (5) subjects which must include English Language, Mathematics, Physics, Chemistry and Biology in not more than two sittings.', 'English Language, Chemistry, Biology and Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5965, 'delsu', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes in Economics and any one of Mathematics, Statistics, Geography, Physics, Chemistry, Agricultural Science, Accounting, Business Management, History and Government.', 'Five (5)SSC credit passes in English Language, Mathematics, Economics and any two (2) of Arts or Social Science subjects.', 'Economics, Mathematics and any of Government, History, Geography, Literature in English, French and Christian Religious Studies/Islamic Studies.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5966, 'delsu', 'agricultural-economics', 1, 'Agricultural Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and one of Zoology/Botany/Agricultural Science/Biology, Geography, Mathematics, Physics, Geology, Economics and Health Science.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology/Agricultural Science and one of Geography, Physics and Economics.', 'Chemistry, Biology/ Agricultural Science and Mathematics or Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5967, 'delsu', 'nursing-nursing-science', 1, 'Nursing / Nursing Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes in any two (2) of Physics, Chemistry, Biology and Mathematics (ii) ND Upper Credit in Prosthesis and Orthopaedic Technology. (i) Two (2) \'A\' Level passes in Biology/ Zoology, Chemistry and Physics plus three (3) other \'O\' Level credit passes in Mathematics, Physics and English Language. (ii) NRN or its approved equivalent plus five (5) \'O\' Level credit passes in English Language and four (4) Science subjects chosen from Mathematics, Physics, Chemistry, Biology, Human Anatomy, Physiology and Hygiene, Health Science, Further Mathematics and General Science.', 'Five (5) SSC credit passes including English Language, Physics, Mathematics, Chemistry and Biology.', 'Chemistry, Biology and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5968, 'delsu', 'education-and-chemistry', 1, 'Education and Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least merit passes and above in Chemistry and Education or any other subject at NCE or above GCE A\'Level passes which must include Chemistry with a grade point of 4 points', 'SSCE O\'Level with credit passes in at least five (5) subjects which must include English Language, Mathematics and Chemistry', 'Subject to be taken must include English Language and Chemistry', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5969, 'delsu', 'medicine-and-surgery', 1, 'Medicine and Surgery', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes in Physics, Chemistry and Biology or Zoology in addition to the UTME requirements. (ii) BSC, BOS, etc in relevant programme.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology.', 'Physics, Chemistry and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5970, 'delsu', 'pharmacology-and-therapeutics', 1, 'Pharmacology and Therapeutics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Three (3) \'A\' Level passes in Chemistry, Biology/Zoology and Physics or Mathematics plus UTME requirements.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology.', 'Physics, Chemistry and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5971, 'delsu', 'education-and-computer-science', 1, 'Education and Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least merit a pass in NCE Computer Science Education(ii) OND in Computer Science Education with a grade not lower than upper credit with a grade point of 4 points(iii) Merit pass in DELSU Diploma(iv) Physics Education(v) Mathematics Education', 'Five O\'Level credit passes which must include English Language, Mathematics, Physics, Chemistry and any other one subject at not more than two sittings.', 'English Language, Mathematics, Physics, Chemistry or Economics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5972, 'delsu', 'petroleum-engineering', 1, 'Petroleum Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in any of Physics, Chemistry and Biology plus UTME entry requirements.', 'Five (5) SSC credit passes in English Language, Maths, Physics, Chemistry. & Biology.', 'Physics, Chemistry and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5973, 'delsu', 'physiology', 1, 'Physiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Chemistry, Physics and Biology/Zoology.', 'Five (5) SSC credit passes in English Language, Maths, Physics, Chemistry and Biology.', 'Physics, Chemistry and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5974, 'delsu', 'geography-and-regional-planning', 1, 'Geography and Regional Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE with at least merit passes in two subjects one of which must be Geography and any other Social Science subject.(ii) GCE A\' Level passes in at least two subjects to include Geography and any other Social Science subject with a minimum of 4 points', 'Candidates must possess five (5) O\' level credit passes in SSCE/NECO/GCE at not more than two sittings which must include English Language, Mathematics, Geography and any two other subjects from Arts, Science or Social Sciences.', 'English Language, Geography, and any two subjects from Science, Arts or Social Sciences', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5975, 'delsu', 'biochemistry', 1, 'Biochemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Chemistry, Mathematics, Physics and Biology. NCE/ND/HND in related programmes plus the UTME requirements.', 'Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Physics and Biology.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5976, 'delsu', 'education-and-integrated-science', 1, 'Education and Integrated Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NCE or DELSU Diploma with at least a merit pass and above in Physics Education or GCE A\'Level which must include Physics with a grade point of 4 points', 'SSCE O\'Level credit passes in at least five (5) subjects including English Language, Mathematics and Physics', 'Subject to be taken must include English Language and Mathematics and any other Art/Social Science/Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5977, 'delsu', 'education-and-music', 1, 'Education and Music', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit in Music.', 'Five (5) SSC credit passes including Music and English Language.', 'Music and any other two (2) Arts/Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5978, 'delsu', 'education-and-biology', 1, 'Education and Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least merit passes and above in Biology at NCE or above and in either Chemistry or Geography(ii) Merit in DELSU Diploma in Biology Education with a grade point of 4 points', 'SSCE O\'Level with credit passes in at least five (5) subjects which must include English Language, Mathematics, Chemistry or Geography and Biology', 'Subjects to be taken must include English Language, Biology, Chemistry and one other Art, Social Science/Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5979, 'delsu', 'fine-arts-fine-and-applied-arts', 1, 'Fine Arts / Fine and Applied Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) OND in Fine Art with a minimum grade of credit.(ii) Diploma in Fine and Applied Arts, DELSU, with at least merit grade(iii) A\' Level passes in Fine and Applied Arts and one other subject with an aggregate of 9 points(iv) JUPEB with a minimum of 3 points', '(i) Candidates without Fine Art/Visual Arts should possess at least five (5) O\'Level credits which may include Mathematics, English Language, and four other subjects from Arts, Social Science and Science', 'English Language and any other three subjects from Arts and Social Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5980, 'delsu', 'drama-dramatic-performing-arts', 1, 'Drama / Dramatic / Performing Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Arts, Social Sciences or Science subjects.', 'Five (5) SSC credit passes to include English Language and Arts subjects.', 'Literature in English and two (2) other relevant subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5981, 'delsu', 'education-and-mathematics', 1, 'Education and Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least merit pass in Mathematics and Education(ii) GCE A\'Level with a grade point of 4 points(iii) Merit in DELSU Diploma in Mathematics', 'SSCE O\'Level credit in five (5) subjects which must include Mathematics, English Language and one of Chemistry or Physics', 'Subject to be taken must include English Language and Mathematics plus any other Science/Social Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5982, 'delsu', 'physics', 1, 'Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NCE/Two (2) \'A\' Level passes in Physics and Mathematics or Chemistry.', 'Five (5) SSC credit passes in English Language, Physics, Chemistry, Mathematics and any other Science subject from Further Mathematics and Biology or Agricultural Science.', 'Physics, Mathematics and Chemistry or Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5983, 'delsu', 'theatre-arts', 1, 'Theatre Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NCE Merit in Theatre Arts and other related Arts in addition to the required Five (5) credits SSCE, GCE O/L, NECO, Candidates with Diploma (Upper Credit and above) in related Arts (Fine Art, Music, Mass Communication and Literature) may be admitted for the 3 years degree programme.', 'The University general admission requirements is five (5) credits at SSCE level or its equivalent, including English and Literature, earned at not more than two sitting.', 'The UME subjects are Literature in English, English Language and three others from Arts/Social Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5984, 'delsu', 'education-and-french', 1, 'Education and French', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit in French and one(1) other Arts subject.', 'Five (5) SSC credit passes to include English Language and French.', 'French plus two (2) other Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5985, 'delsu', 'english-and-literary-studies', 1, 'English and Literary Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Five (5) O\'Level credit passes in SSC/GCE/NECO(ii) A Merit Pass in not less than two (2) Arts subjects including Literature in English at the G.C.E \'A\' Level or at the Principle Level in the H.S.C examination or their equivalent.(iii) A Pass in \'A\' Level General Paper or NCE General English is not accepted in Lieu of an O\' Level Credit Pass in SSC/GCE/NECO English. English Language or Literature courses taken at OND will not be accepted for admission into the Department', 'At least five SSC/NECO/GCE O\' Level Credit Passes at not more than two sittings, to include English Language, Literature-in-English, plus one other Arts subject.', 'Use of English, Literature in English, CRS, and any other Arts/Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5986, 'delsu', 'french', 1, 'French', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Candidate must have at least a merit pass in French and one other Arts subject at the NCE level.(ii) GCE A/L passed should include French and one other Arts subject with an aggregate of at least 4 points(iii) Certified Diploma in French from a recognized Institute like the Nigerian French Language Village and the likes will be accepted in place of A level French', 'Five (5) credit level passes in SSCE/NECO/GCE O\'Level which may include Mathematics, English Language and four other subject from Arts, Social Science and Science', 'English Language, and any three from Arts, Social Science and Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5987, 'delsu', 'education-and-geography', 1, 'Education and Geography', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE merit passes and above in Geography and any other Social Science subjects.(ii) A\' Level credit passes must include Geography with a grade point not below 4 points', 'Five O\'Level which must include English Language, Mathematics, Geography and any three other from Arts/Social Science/Science', 'English Language, Geography and any other from Social Science/Science', 1, NULL, 0, NULL, NULL, NULL, NULL);
INSERT INTO `institution_program` (`id`, `institution_id`, `program_id`, `level_id`, `name`, `description`, `remarks`, `program_mode_id`, `duration`, `tuition_fee`, `utme_cutoff`, `requirements`, `direct_entry`, `o_level`, `utme_subjects`, `accreditation_body_id`, `accreditation_status_id`, `is_distinguished`, `accreditation_grant_date`, `accreditation_expiry_date`, `created_at`, `updated_at`) VALUES
(5988, 'delsu', 'education-and-history', 1, 'Education and History', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) NCE merit/\'A\' Level passes in History and one (1) other relevant Arts subject.', 'Five (5) SSC credit passes in English Language, History and three (3) relevant Arts subjects.', 'History and any other two (2) subjects chosen from Christian Religious Studies / Islamic Studies, Literature in English, French, Yoruba, Geography/Physics, Economics, Government and Hausa.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5989, 'delsu', 'education-and-physics', 1, 'Education and Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NCE or DELSU Diploma with at least a merit pass and above in Physics Education or GCE A\'Level which must include Physics with a grade point of 4 points', 'SSCE O\'Level credit passes in at least five (5) subjects including English Language, Mathematics and Physics', 'Subject to be taken must include English Language and Mathematics and any other Art/Social Science/Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5990, 'delsu', 'industrial-mathematics', 1, 'Industrial Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes from Mathematics, Physics, Economics or Chemistry. (ii) NCE merit in relevant subjects.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics and two (2) other Science subjects.', 'Mathematics and any two (2) of Physics, Chemistry, Economics, Biology and Agricultural Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5991, 'delsu', 'physical-and-health-education', 1, 'Physical and Health Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in any of Biology, Chemistry, Physics and Mathematics. (ii) NCE merit in Physical Education and credit in Arithmetical process or Mathematics. (iii) Diploma in Health Education, Environmental Sanitation, Physical Education, Social work, Health Administration with overall grades of merit plus three (3) \'O\' Level credit passes/TC II merit which should include English Language. (iv) NCE in Biology, Health Education, and Integrated Science with a pass grade plus two (2) \'O\' Level credit passes/TC II merit passes. (v) Registered Nurse plus five (5) \'O\' Level credit passes to include English Language.', 'i) Five (5) SSC credit passes/TC II merit passes including English Language, Biology or its equivalent. ii) Five (5) SSC credit passes/TC II merit passes to include English Language and Mathematics.', 'Biology and any two (2) relevant subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5992, 'delsu', 'history-and-international-studies', 1, 'History and International Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Candidates seeking admission into the three-year degree programme must obtain at least a merit pass at the NCE level, pass at the GCE (advanced level or HSC A/Level) in one of the following subjects: History, Government, Economic History, Economics, English, Geography and any other related Diploma in Mass Communication, Social Work, Administration and Law of the Delta State University', 'Candidate must have a credit pass in English Language, and in History or Government and at least three other Arts, Social Science subjects as well as a minimum of pass in Mathematics at the Senior Secondary School Certificate Level or its equivalent for admission into the four-year degree programme. the O\'Level Credits, which should be in at least five subjects should be obtained at not more than two sittings.', 'Candidates must have a credit pass in English Language, and in History or Government and at least three other Arts/Social﻿ Science subjects as well as a minimum of pass in Mathematics at the Senior Secondary School Certificate Level or its equivalent for admission into the four-year degree programme. The O\'level Credits, which should be in at least five subjects should be obtained at not more than two sittings.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5993, 'delsu', 'chemistry', 1, 'Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes in Chemistry and Mathematics or Physics or Biology', 'Five (5) \'O\' level credits which must include Chemistry, English Language, Mathematics, Physics and one other science subject', 'English Language, Chemistry, Physics and Mathematics or Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5994, 'delsu', 'health-education', 1, 'Health Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Two (2) \'A\' Level passes in any of Biology, Chemistry, Physics and Mathematics. (ii) NCE merit in Physical Education and credit in Arithmetical process or Mathematics. (iii) Diploma in Health Education, Environmental Sanitation, Physical Education, Social work, Health Administration with overall grades of merit plus three (3) \'O\' Level credit passes/TC II merit which should include English Language. (iv) NCE in Biology, Health Education, and Integrated Science with a pass grade plus two (2) \'O\' Level credit passes/TC II merit passes. (v) Registered Nurse plus five (5) \'O\' Level credit passes to include English Language.', 'i) Five (5) SSC credit passes/TC II merit passes including English Language, Biology or its equivalent. ii) Five (5) SSC credit passes/TC II merit passes to include English Language and Mathematics.', 'Biology and any two (2) relevant subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5995, 'delsu', 'animal-science', 1, 'Animal Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes or its equivalent in Chemistry and one of Biology/Botany/Zoology/Agriculture Science/Geography/Geology/Mathematics/Economics.', 'Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Biology/Agric Science and one of Physics, Geography or Economics.', 'Chemistry, Biology/Agriculture and Mathematics /Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5996, 'delsu', 'industrial-chemistry', 1, 'Industrial Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes in Chemistry and Mathematics or Physics or Biology', 'Five (5) \'O\' level credits which must include Chemistry, English Language, Mathematics, Physics and one other science subject', 'English Language, Chemistry, Physics and Mathematics or Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5997, 'delsu', 'geology', 1, 'Geology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes from Geology, Chemistry, Mathematics, Physics, Biology and Geography.', 'Five (5) SSC credit passes in English Language, Biology, Chemistry, Mathematics and any other subject.', 'Any three (3) of Chemistry, Physics, Mathematics, Biology and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5998, 'delsu', 'biotechnology', 1, 'Biotechnology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Biology/Botany/Zoology and Chemistry or Physics.', 'Five (5) SSC Credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'Biology, Chemistry and any other Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(5999, 'delsu', 'linguistics-and-urhobo', 1, 'Linguistic and Urhobo', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) A minimum of two passes at HSC, JUPEB, GCE (Advanced Level), its equivalent.(ii) NCE at merit pass in English Language or any Nigerian Language(iii) OND/HND/Diploma in Mass Communication/Theatre Arts/English/Literature/Law/Music with minimum of merit pass.(iv) English and any other subject are also acceptable (at NCE level)', 'Five (5) credit level passes in SSCE/NECO/GCE O\'Level which may include Mathematics, English Language, three other subject from Arts, Social Science and Science', 'English Language, and any three from Arts, Social Science and Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6000, 'delsu', 'zoology', 1, 'Zoology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes or NCE in Biology, Zoology or Botany and one other Science subject', 'Five (5) SSC credit passes in English Language, Mathematics, Biology and two (2) other Science subject.', 'Biology and any two (2) of Physics, Chemistry and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6001, 'delsu', 'sociology', 1, 'Sociology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and one of Zoology/Botany/Agric Science/Biology, Geography, Mathematics, Physics, Geology, Economics and Health Science.', 'Five (5) SSC credit passes in English Language Mathematics, Chemistry, Biology/Agricultural Science and any other Science subject.', 'Chemistry, Biology or Agricultural Science plus Mathematics or Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6002, 'delsu', 'linguistics', 1, 'Linguistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) A minimum of two passes at HSC, JUPEB, GCE (Advanced Level), its equivalent.(ii) NCE at merit pass in English Language or any Nigerian Language.(iii) OND/HND/Diploma in Mass Communication/Theatre Arts/English/Literature/Law/Music with minimum of merit pass.(iv) English and any other subject are also acceptable (at NCE level).', 'Five (5) credit level passes in SSCE/NECO/GCE O\'level which may include Mathematics, English Language, three other subject from Arts, Social Science and Science', 'English Language, and any three from Arts, Social Science and Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6003, 'delsu', 'technical-education', 1, 'Technical Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE (Technical) with an overall merit or above.(ii) Full Technological Certificate or National Diploma (ND) or HND or Advanced Technological Certificate (ANTC).(iii) GCE Advanced Level/HSC in two of the following subjects: Chemistry, Physics and Mathematics plus three credits in WASC/SSE/GCE O/L including English Language and Mathematics', '(i) GCE O/L, WASC or SSC or its equivalent pass with credits in five subjects in Mathematics, English Language, Physics or Chemistry and any other Arts/Social Science/Science subjects.(ii) City and Guilds Intermediate in addition to three credits pass in WASC/GCE/NECO/NTC ordinary level in Mathematics, English Language, Physics or Chemistry and any other Arts/Social Science/Science subjects.', '(i) English Language(ii) Mathematics(iii) Physics or Chemistry(v) Any other Science or Social Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6004, 'delsu', 'music', 1, 'Music', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes to include Music.', 'Five (5) SSC credit passes including Music and English Language.', 'Music, one other Arts subject plus any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6005, 'delsu', 'pharmacy', 1, 'Pharmacy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) 2 A/L Credit Passes in any Arts or Social Sciences with minimum of 9 points.(ii) Merit pass in DELSU Diploma in Law', '5 O/L (WAEC or NECO) Credit passes, including English Language and Mathematics and other three subjects. A Pass in Mathematics is acceptable but students must have five (5) credit passes with English Language.', 'English Language and any other three subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6006, 'delsu', 'public-administration', 1, 'Public Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) A/L passes in CRS and one other Arts or Social Sciences subject with minimum of 9 points(ii) Merit Pass in NCE, one of the subject must be Religious Studies(iii) Merit Pass in DELSU Diploma in Law, Social Studies Education, or Guidance and Counselling', '5 O/L (WAEC or NECO) Credit Passes including English Language, CRS and Mathematics and any other two subjects. A pass in Mathematics is acceptable but students must have five (5) credit passes with English Language and CRS.', 'Christian Religious Studies (CRS, English Language and any other two subjects)', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6007, 'delsu', 'mathematics', 1, 'Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, ') Two (2) \'A\' Level passes in Mathematics and any other science subject. (ii) NCE merit in Mathematics and one (1) of Physics, Chemistry or Economics', 'Five (5) SSC credit passes including English Language, Mathematics and Physics or Chemistry.', 'Mathematics and any two (2) of Physics, Chemistry and Economics or Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6008, 'delsu', 'microbiology', 1, 'Microbiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and any one (1) from Biology, Zoology or Botany.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology and Physics.', 'Biology, Chemistry and either Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6009, 'delsu', 'mass-communication', 1, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Arts or Social Science subjects.', 'Five (5) SSC credit passes in English Language and four (4) other subjects in Arts or Social Sciences.', 'Any three (3) from Arts or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6010, 'delsu', 'forestry-and-wildlife', 1, 'Forestry and Wildlife', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and Biology or Agric Science or Zoology or Botany.', 'Five (5) SSC credit passes in English, Chemistry, Mathematics, Biology and one of Physics, Economics, Further Mathematics and Statistics.', 'Chemistry, Biology/Agriculture and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6011, 'delsu', 'religious-studies', 1, 'Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and any one (1) from Biology, Zoology or Botany.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology and Physics.', 'Biology, Chemistry and either Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6012, 'delsu', 'home-economics-and-education', 1, 'Home Economics and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE merit in Home Economics (ii) \'A\' Level passes in two (2) of Chemistry or any Biology, Botany and Agricultural Science. (iii) ND/HND credit in Home Economics or Food Science or Hotel and Catering Management or any other related programme', 'Five (5) \'O\' Level NTC/NBC credit passes or TC II merit including English Language, Mathematics, Home Economics, Biology and Chemistry.', 'Chemistry, Biology or Agricultural Science and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6013, 'delsu', 'computer-science', 1, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two GCE A\'Level passes which must include Mathematics and Physics with a minimum of 6 points.(ii) A National Diploma with a minimum of Upper Credit or Higher National Diploma with a minimum of lower credit or with a minimum credit in any of the following:(a) Data Processing(b) Computer Engineering(c) Information System/Information Technology', 'Mathematics (core), English Language (core), Physics (core), and any two of Computer Science (related subject)(i) Biology(ii) Chemistry(iii) Economics(iv) Geography', 'English Language, Mathematics, Physics and any of Biology, Chemistry or Geography', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6014, 'delsu', 'teacher-education-science', 1, 'Teacher Education Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant teaching subjects including Literature in English. (ii) NCE credit or merit in two(2)relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language and Literature in English plus three (3) other Arts or Social Science subjects.', 'Literature in English and one (1) Art and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6015, 'delsu', 'education-and-english-language', 1, 'Education and English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant teaching subjects including Literature in English. (ii) NCE credit or merit in two(2)relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language and Literature in English plus three (3) other Arts or Social Science subjects.', 'Literature in English and one (1) Art and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6016, 'delsu', 'political-science', 1, 'Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) DELSU Diploma in Public Administration with a merit passii) OND in Political Science with a grade not lower than upper credit ii) A\' Level passes in at least two Social Science subjects. One of which must be Government with a minimum of 6 points', 'O/Level credits passes in five subjects which must include English Language, Mathematics, Government, one Social Science and any of Science or Arts subjects.', 'English Language, Government, one other Social Science subjects and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6017, 'delsu', 'education,-fine-and-applied-arts', 1, 'Education, Fine and Applied Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE merit in Fine and Applied Arts Double Major. (ii)\'A\' Level passes in Fine Arts and any other subject.', 'Five (5) \'O\' Level credit passes or TC II or NTC/NBC merit including Fine Art and English Language.', 'Fine Arts, one (1) other Arts subject and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6018, 'delsu', 'education-and-religious-studies', 1, 'Education and Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit in Religious Studies and one (1) other Arts subject.', 'Five (5) \'O\' Level credit passes or TC II merit in five (5) subjects including English Language, Religious Studies and three (3) other Arts subjects.', 'Two (2) Arts subject including Religious studies and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6019, 'delsu', 'psychology', 1, 'Psychology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'GCE A\' Level passes in at least two subjects which should include one social science subject with a minimum of 6 points', 'Five credit passes at SSCE/NECO/GCE O\' Level which should include English Language, Mathematics, Biology/Health Science, one social science and any other subject', 'English Language, Mathematics and any other two subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6020, 'delsu', 'philosophy', 1, 'Philosophy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Government and any other two (2) subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6021, 'delsu', 'science-laboratory-technology', 1, 'Science Laboratory Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Three (3) Social Science or Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6022, 'delsu', 'marketing', 1, 'Marketing', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) DELSU Diploma in Marketing or Business Administration(ii) OND in Marketing with a grade not Lower than merit pass(iii) A\' Level passes in at least two (2) subjects (Marketing or Business), one of which must be Economics with a minimum of 6 points', '(i) O\' Level Credit passes in Five (5) subjects which must include:(a) English Language (b) Mathematics (c) Economics/Commerce(d) Government or any other Social Science subjects', '(i) English Language(ii) Mathematics(iii) Economics or Commerce(iv) Government or any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6023, 'delsu', 'office-and-information-management', 1, 'Office and Information Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes to include Physics, Chemistry and Mathematics.', 'Five (5) SSC credits to include Physics, Chemistry, Mathematics, English Language and any one Science subject.', 'Chemistry, Mathematics and Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6024, 'delsu', 'electrical-electronics-engineering', 1, 'Electrical / Electronics Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Mathematics, Physics or Chemistry', 'Five (5) SSC credit passes to include Mathematics, Physics, Chemistry, English Language and any other Science subject.', 'Mathematics, Physics and Chemistry', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6025, 'delsu', 'mechanical-engineering', 1, 'Mechanical Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes from Chemistry, Physics and Mathematics. (ii) ND upper credit, NCE technical and HND in Mech. Engineering.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics, English Language and any other Science subject.', 'Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
