(6032, 'delsu', 'education-and-social-studies', 1, 'Education and Social Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE merit in Social Studies (Double Major) or Diploma in Social Studies/Social work with Lower Credit(ii) GCE A\'Level in relevant subjects with a grade point not below 4 points', 'Five O\'Level which must include English Language, Mathematics and any three other from Arts/Social Science/Science', 'English Language and any other three subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6033, 'delsu', 'education-and-political-science', 1, 'Education and Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least merit passes in Government plus one other subject at A\' Level with a grade not less than 4 points', 'Five O\'Level credits which must include English Language, Mathematics and Government', 'English Language, Government/History and any other two Arts/Social Science/Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6034, 'delsu', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE merit passes in Economics and any relevant Social Science subjects.(ii) DELSU Diploma in Economics at Merit(iii) A\'Level credit passes in Economics, one other Social Science at a grade not less than 4 points', 'Five O\'Level which must include English Language, Mathematics, Economics and any two other from Social Science', 'English Language, Economics and any other two subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(6035, 'delsu', 'business-education', 1, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes or NCE merit in two (2) relevant subjects.(ii) NCE merit in Business Education Double Major.', 'Five (5) TC II merit, \'O\' Level or NTC/NBC credit passes including English Language, Mathematics, Economics and two (2) other subjects in the Social Sciences or Arts. For NBC, the other subjects could be from any of the following: Commerce, Office Practice, Principles of Accounts, Secretarial Duties, Typewriting and Shorthand.', 'Mathematics, Economics plus one (1) of Literature in English, History, Government, Geography, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
