(9190, 'aefuna', 'physiotherapy', 1, 'Physiotherapy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Physics, Chemistry and Biology.', 'Five (5) SSC credit passes in English Language, Maths, Biology, Physics and Chemistry.', 'Physics, Chemistry and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(9191, 'aefuna', 'biochemistry', 1, 'Biochemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Chemistry, Mathematics, Physics and Biology. NCE/ND/HND in related programmes plus the UTME requirements.', 'Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Physics and Biology.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(9192, 'aefuna', 'christian-religious-studies', 1, 'Christian Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE to include CRS/Religious Studies.', 'Five (5) SSC credit passes in English Language, CRS and three (3) other relevant subjects.', 'Two (2) Arts subjects including CRS and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(9193, 'aefuna', 'education-and-biology', 1, 'Education and Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. A pass at merit level in relevant Diploma program with SSCE requirements. ii. Advanced level passes in two (2) relevant subjects with SSCE requirements. iii. NCE with at least merit pass in 2 relevant subjects or a double major subject with SSCE requirements. iv. IJMB passes in two (2) relevant subjects with SSCE requirements. v. Any other equivalent qualifications with SSCE requirements. vi. Any other equivalent qualifications as may be determined by the Department.', 'Credit Passes in English Language, Mathematics, Biology and any other two subjects from Chemistry, Physics, Health Science and Agricultural Science.', 'Use of English, Biology and any other two subjects from Chemistry, Health Science, and Agricultural Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(9194, 'aefuna', 'library-and-information-science', 1, 'Library and Information Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2)\'A\' Level passes in relevant subjects. (ii) NCE/ND in relevant subject/programmes', 'Five (5)SSC credit passes including English Language and Mathematics.', 'Any three (3) Arts or Social Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(9195, 'aefuna', 'fine-arts-fine-and-applied-arts', 1, 'Fine Arts / Fine and Applied Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. Basic School Certificate at O\' level (five credit pass) ii. NCE credit/Merit in Fine Arts iii. OND credit/merit polytechnic in Fine Arts iv. HND distinction/pass in Fine Arts (at 300 level).', 'Credit Passes in English language, Mathematics, and any other three subjects.', 'Use of English and any other three Arts or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(9196, 'aefuna', 'visual-and-applied-arts', 1, 'Visual and Applied Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Arts or Fine Arts and any other subject. ND upper credit HND lower credit from recognised institutions.', 'Five (5) SSC credit passes to include English Language and Fine Arts.For holders of NTC, the relevant subjects could be General Wood work, Building/Engineering Drawing, Introduction to Building Construction; Decorative Painting; Spray Painting, Lining, Sign and Design; Wall hanging, Colour Mixing/Matching and Glazing; Printing Origination; Machine Printing and Finishing; General Metal Work, Basic Electricity, Spinning, Weaving, Surface Design and Printing; Bleaching, Dyeing and Finishing; Graphic Design; Graphic Printing and Ceramics.', 'Fine Arts and two (2) other Arts subjects or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(9197, 'aefuna', 'education-and-mathematics', 1, 'Education and Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. A pass at merit level in relevant Diploma programme with SSCE requirements. ii. Advanced level passes in relevant subjects with SSCE requirements. iii. NCE with at least merit pass in 2 relevant subjects or a double major subject with SSCE requirements. iv. IJMB passes in 2 relevant subjects with SSCE requirements. v. Any other equivalent qualifications with SSCE requirements. vi Any other equivalent qualification as may be determined by the Department.', 'Credit Passes in English language, Mathematics and any other three subjects from Biology, Agricultural Science, Animal Husbandry, Chemistry, Physics, Economics, Geography and Data Processing', 'Use of English, Mathematics and any other two subjects from Physics, Chemistry, Geography, Economics and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(9198, 'aefuna', 'physics', 1, 'Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'ND, NCE, JUPEB', 'Credit Passes in English language, Mathematics, Physics, Biology, and Chemistry', 'Use of English, Mathematics, Physics, and Chemistry or Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(9199, 'aefuna', 'english-language', 1, 'English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Merit in NCE in relevant disciplines plus O\' level requirements, National Diploma (Not below lower credit) in relevant disciplines plus O\' level relevant credit pass or equivalent grades in JUPEB examination plus O\' level requirements.', 'Credit Passes in English Language, Mathematics, Literature in English and any other two (2) Arts or Social Science subject.', 'Use of English, Lit in English and any other two (2) Arts or Social Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(9200, 'aefuna', 'french', 1, 'French', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including French and one other Arts subject.', 'Five (5) SSC credit passes including French and English Language plus one other Arts subject.', 'French and any other two (2) subjects from Arts and Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(9201, 'aefuna', 'education-and-physics', 1, 'Education and Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. A pass at merit level in relevant Diploma program with SSCE requirements. Science/Animal Husbandry, and Geography ii. Advanced level passes in 2 relevant subjects with SSCE requirements. iii. NCE with at least merit pass in 2 relevant subjects or a double major subject with SSCE requirements. iv. IJMB passes in 2 relevant subjects with SSCE requirements.', 'Credit Passes in English Language, Mathematics, Physics and any other two subjects from Chemistry, Biology/Agricultural Science/Animal Husbandry, and Geography.', 'Use of English, Physics and any other two subjects from Chemistry, Mathematics, Geography, Economics and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
