(9511, 'fedfishbaga', 'fisheries-technology', 2, 'Fisheries Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science and two (2) of Physics, Chemistry, Mathematics and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(9512, 'fedfishlag', 'fisheries-technology', 2, 'Fisheries Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '-', 'Five (5) SSCE/GCE/NECO/NABTEB credit passes in English Language, Mathematics, Chemistry, Biology/Agricultura Science and any one of the following: Physics, Economics or Further Mathematics.', 'English Language, Chemistry, Biology/Agricultural Science and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(9513, 'fedfishlag', 'marine-engineering-technology', 2, 'Marine Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '-', 'Five (5) SSCE/GCE/NECO/NABTEB credit passes in English Language, Mathematics, Physics, Chemistry and any one of: Further Mathematics, Technical Drawing, Biology/Agricultural Science, Basic Electronics, Metal Work, Wood Work and Geography obtained at not more than two sittings.', 'English Language, Physics, Mathematics and Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(9514, 'fedfishlag', 'nautical-science', 2, 'Nautical Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '-', 'Five (5) SSCE/GCE/NECO/NABTEB credit passes in English Language, Mathematics, Physics, Geography and any one of: Chemistry, Technical Drawing and Economics/Commerce obtained at not more than two sittings and any other qualification considered relevant by the Academic Board.', 'English Language, Mathematics, Physics and Geography', 2, NULL, 0, NULL, NULL, NULL, NULL),
