(9969, 'fedponas', 'urban-and-regional-planning', 2, 'Urban and Regional Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Geography and three (3) other subjects from: English Language, Economics/Commerce, Fine Art/Technical Drawing, Further Mathematics, Chemistry, Physics, Biology/Agricultural Science, History/Government Business Methods/Bookkeeping and Principles of Accounting One of the three (3) subjects must be a basic science subject. At least a credit pass in English Language is compulsory.', 'Geography and two (2) other subjects from course requirement.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(9970, 'fedponas', 'chemical-engineering-technology', 2, 'Chemical Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SCC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry or Technical Drawing', 2, NULL, 0, NULL, NULL, NULL, NULL),
(9971, 'fedponas', 'surveying-and-geoinformatics', 2, 'Surveying and Geoinformatics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any other three (3) subjects from the following: Further Mathematics, Chemistry; Technical Drawing/Fine Art, Geography, Economics/Commerce, Biology/Agricultural Science, English Language, Basic Electricity At least \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Chemistry/Agricultural Science, Biology, Economics and Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(9972, 'fedponas', 'civil-engineering-technology', 2, 'Civil Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering a pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics and Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(9973, 'fedponas', 'computer-science', 2, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, a basic science and three (3) other subjects chosen from the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics is compulsory.', 'Mathematics and any two (2) of Geography, Physics, Economics or Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
