(10414, 'ftpotis', 'business-education', 3, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'SSC credit passes or TC II merits in English Language and any three (3) of: 1. Economics 2. Accounts 3. Government 4. Geography 5. History 6. Business Method 7. Statistics 8. Commerce 9. Any Science subjects NB: GROUP A: Commercial Arithmetic Costing, Principles of Accounts, Book Keeping Mathematics, Statistics. GROUP B: Office Practice, Business Method, Commerce, Economics.', 'Mathematics, Economics and any of Geography, Commerce and Principles of Accounts.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(10415, 'ftpotis', 'agricultural-science', 3, 'Agricultural Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'SSC credit passes in English Language and any three (3) of 1. Agricultural Science 2. Mathematics 3. Chemistry 4. Biology 5. Health Science 6. Integrated/Rural Science 7. Physics 8. Nature Study and 9. General Science. NB GROUP A: 1. Agricultural Science 2. Biology 3. Nutrition 4. Health Science. 5. Applied Biology GROUP B: 1. Physics 2. Chemistry 3. Mathematics 4.Basic Mathematics/Arithmetic Process 5. Economics 6. Geography 7. Social Studies 8. Integrated Science 9. General Science', 'Agricultural Science, Chemistry, Biology/General Science or Mathematics.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(10416, 'ftpotis', 'integrated-science-physics', 3, 'Integrated Science / Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics Physics and any two (2) Science subjects', 'Physics and any other two (2) Science subjects.', 3, NULL, 0, NULL, NULL, NULL, NULL),
