(10421, 'ftpotis', 'primary-education-studies', 3, 'Primary Education Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5)SSC credits including English Language.', 'English Language and any other three (3) subjects.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(10422, 'ftpotis', 'biology-integrated-science', 3, 'Biology / Integrated Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Biology, Chemistry/Physics and any other Science subject.', 'Biology, Chemistry/Physics and any other Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
