(11731, 'iaued', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes in Economics and any one of Mathematics, Statistics, Geography, Physics, Chemistry, Agricultural Science, Accounting, Business Management, History and Government.', 'Five (5)SSC credit passes in English Language, Mathematics, Economics and any two (2) of Arts or Social Science subjects.', 'Economics, Mathematics and any of Government, History, Geography, Literature in English, French and Christian Religious Studies/Islamic Studies.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11732, 'iaued', 'secretarial-education', 1, 'Secretarial Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE Business Education Social Studies Secretarial Education Major. (ii) Two (2) \'A\' Level passes in Business Method and any other Social Science subject and \'O\' Level pass in Mathematics.', 'Five (5) SSC credit to include English Language, Economics and any two(2) of Government, Geography/Physics, Accounting, Business Methods, History, Shorthand, Mathematics, Commerce, Principles of Accounts, Office Practice AND Secretarial Duties.', 'Economics and any two (2) Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
