(11743, 'iaued', 'theatre-arts', 1, 'Theatre Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Arts, Social Sciences or Science subjects.', 'Five (5) SSC credit passes to include English Language and Arts subjects.', 'Literature in English and two (2) other relevant subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11744, 'iaued', 'english-language', 1, 'English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes to include Literature in English and one other Arts subject.', 'Five (5) SSC credit passes to include Literature in English, English Language and three other Arts or Social Science subjects.', 'Literature in English, one other Arts subject and another Arts or Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11745, 'iaued', 'education-and-french', 1, 'Education and French', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'An N.C.E. (National Certificate in Education), JUPEB (Joint Universities Preliminary Examinations Board) Certificate or Diploma Certificate which qualifies the candidate into the two hundred (200) level of the degree programme, DELF A1, A2 which qualifies the candidate into the one hundred (100) level of the degree programme, DELF B1, B2 or DALF C1, C2 which qualifies the candidate into the two hundred (200) level of the degree programme', 'Five (5) Ordinary Level credits at the G.C.E., WAEC/SSCE or NECO or a combination of these, including English Language, Mathematics, and any other three (3) Arts or Social Sciences subjects at not more than two sittings, or has obtained a pass in the Certificate Programme of the Department which qualifies the candidate into the one hundred (100) level of the degree programme', 'English Language, Literature in English, Government, CRS etc.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11746, 'iaued', 'french', 1, 'French', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'An N.C.E. (National Certificate in Education), JUPEB (Joint Universities Preliminary Examinations Board) Certificate or Diploma Certificate which qualifies the candidate into the two hundred (200) level of the degree programme, DELF A1, A2 which qualifies the candidate into the one hundred (100) level of the degree programme, DELF B1, B2 or DALF C1, C2 which qualifies the candidate into the two hundred (200) level of the degree programme', 'Five (5) Ordinary Level credits at the G.C.E., WAEC/SSCE or NECO or a combination of these, including English Language, Mathematics, and any other three (3) Arts or Social Sciences subjects at not more than two sittings, or has obtained a pass in the Certificate Programme of the Department which qualifies the candidate into the one hundred (100) level of the degree programme', 'English Language, Literature in English, Government, CRS etc.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11747, 'iaued', 'education-and-geography', 1, 'Education and Geography', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit which should include Geography /Physics.', 'Five (5) SSC credit passes to include Geography, English Language and Mathematics.', 'Geography plus two (2) other Social Sciences/Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11748, 'iaued', 'education-and-history', 1, 'Education and History', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) NCE merit/\'A\' Level passes in History and one (1) other relevant Arts subject.', 'History, Government, or Civic Education, English & Maths and any other two subjects from Humanities, Social Science and Sciences', 'English, History or Government, and CRS.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11749, 'iaued', 'education-and-physics', 1, 'Education and Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Physics and Mathematics. (ii) NCE credit/merit in relevant subjects.', 'Five (5) \'O\' Level credits passes to include English Language, Physics, Mathematics and two (2) other Science subjects or NTC/NBC.', 'Physics, Mathematics or Chemistry plus one (1) other subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11750, 'iaued', 'chemistry', 1, 'Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Chemistry and any one (1) of Physics, Mathematics or Biology. (ii) ND/NCE with good grades in relevant \'O\' Level subjects.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology.', 'Chemistry and two (2) of Physics, Biology and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11751, 'iaued', 'history-and-diplomatic-studies', 1, 'History and Diplomatic Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE (upper credit) in History/ Government and any other related subject.', 'History, Government, or Civic Education, English & Maths and any other two subjects from Humanities, Social Science and Sciences.', 'English, History or Government, and CRS.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11752, 'iaued', 'health-and-safety-education', 1, 'Health and Safety Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two A level credit passes in any of Biology, Chemistry, Physics and Mathematics. NCE merit in Physics and credit in Arithmetical process or Mathematics. OND in Physical Education or Health Education (ii) Diploma in Health Education, Environmental Sanitation, Physical Education, Social work, Health Administration with overall grades of merit plus three (3) \'O\' Level credit passes/TC II merit which should include English Language. (iii) NCE in Biology, Health Education, and Integrated Science with a pass grade plus two (2) \'O\' Level credit passes/TC II merit passes.', 'Five credits passes in SSCE or its equivalent. These must include English Language, Mathematics. Plus 3 Sciences Subjects from Biology/Health Sciences, Chemistry, Agriculture Science.', 'English Language, Biology and any two subjects from Physical Education, Health Science or Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11753, 'iaued', 'human-kinetics', 1, 'Human Kinetics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) NCE in Physical and Health Education with overall percentage of 60% plus the UTME requirements.', 'Five (5) \'O\' Level credit passes at one (1) sitting to include English Language, Mathematics, Health Science/Physical Education/Biology and any two (2) other subjects.', 'English Language and three (3) other relevant subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11754, 'iaued', 'technical-education', 1, 'Technical Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) NCE (Technical or Physics or Math\'s) With merit pass in the relevant area plus UTME requirements (ii) Two \'A\' level of IJMA passed in physics and Math\'s plus UTME requirements', 'Five \'O\' level credit which must include English Language Mathematics Physic, and any other 2 (Two) subjects', 'Physics, Mathematics and any other relevant subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11755, 'iaued', 'music', 1, 'Music', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes to include Music.', 'Five (5) SSC credit passes including Music and English Language.', 'Music, one other Arts subject plus any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
