(11757, 'iaued', 'mathematics', 1, 'Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes in pure and applied Mathematics and either Physics and/or Chemistry. NCE with credit passes in Mathematics and another science subject for Direct Entry.', 'Five (5) credit passes at SSCE (or its equivalent) including English Language and Mathematics and any other three (3) subjects preferably Further Mathematics, Physics, Chemistry, Biology, Data Processing, Computer Studies, Agricultural Science and Health Science in that order for UTME.', 'Mathematics and any two (2) of Physics, Chemistry and Economics or Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11758, 'iaued', 'home-economics-and-education', 1, 'Home Economics and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE merit in Home Economics (ii) \'A\' Level passes in two (2) of Chemistry or any Biology, Botany and Agricultural Science. (iii) ND/HND credit in Home Economics or Food Science or Hotel and Catering Management or any other related programme', 'Five (5) \'O\' Level NTC/NBC credit passes or TC II merit including English Language, Mathematics, Home Economics, Biology and Chemistry.', 'Chemistry, Biology or Agricultural Science and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11759, 'iaued', 'computer-science', 1, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, ') Two (2) \'A\' Level passes in science subjects including Mathematics (ii) NCE merit in Mathematics and one (1) other Science or Social Science subject.', 'Five (5) SSC credit passes to include English Language, Mathematics, Physics plus two (2) other Science subjects.', 'Mathematics, Physics and one (1) of Biology, Chemistry, Agric Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11760, 'iaued', 'teacher-education-science', 1, 'Teacher Education Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant teaching subjects including Literature in English. (ii) NCE credit or merit in two(2)relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language and Literature in English plus three (3) other Arts or Social Science subjects.', 'Literature in English and one (1) Art and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11761, 'iaued', 'education-and-english-language', 1, 'Education and English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant teaching subjects including Literature in English. (ii) NCE credit or merit in two(2)relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language and Literature in English plus three (3) other Arts or Social Science subjects.', 'Literature in English and one (1) Art and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11762, 'iaued', 'education,-fine-and-applied-arts', 1, 'Education, Fine and Applied Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE merit in Fine and Applied Arts Double Major. (ii)\'A\' Level passes in Fine Arts and any other subject.', 'Five (5) \'O\' Level credit passes or TC II or NTC/NBC merit including Fine Art and English Language.', 'Fine Arts, one (1) other Arts subject and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11763, 'iaued', 'education-and-religious-studies', 1, 'Education and Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit in Religious Studies and one (1) other Arts subject.', 'Five (5) \'O\' Level credit passes or TC II merit in five (5) subjects including English Language, Religious Studies and three (3) other Arts subjects.', 'Two (2) Arts subject including Religious studies and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11764, 'iaued', 'education-and-christian-religious-studies', 1, 'Education and Christian Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit in Religious Studies and one (1) other Arts subject.', 'Five (5) \'O\' Level credit passes or TC II merit in five (5) subjects including English Language, Religious Studies and three (3) other Arts subjects.', 'Two (2) Arts subject including Religious studies and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11765, 'iaued', 'sociology', 1, 'Sociology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Three (3) Social Science or Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11766, 'iaued', 'biology', 1, 'Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Two (2) \'A\' Level passes from Chemistry, Biology, Botany/Zoology. (ii) NCE merit accepted.', 'Five (5) SSC credit passes to include English Language, Biology, Chemistry and Mathematics/Physics.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11768, 'iaued', 'educational-management', 1, 'Educational Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Same as in Educational Psychology, Guidance and Counseling.', 'Same as in Educational Psychology, Guidance and Counseling.', 'Economics, Mathematics and one (1) other Social Science/Arts subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11769, 'iaued', 'library-and-information-science', 1, 'Library and Information Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant subject plus the UTME requirements. (ii) NCE merit in relevant subjects.', 'Five (5) SSC credit passes in English Language, Mathematics and three (3) other relevant Arts/Sciences/Social Sciences subjects.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11770, 'iaued', 'primary-education-studies', 1, 'Primary Education Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from relevant subjects.', 'Five (5) \'O\' Level credit passes including English Language.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11771, 'iaued', 'early-childhood-education', 1, 'Early Childhood Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from relevant subjects.', 'Five `O` Level credits including English Language and Mathematics', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11772, 'iaued', 'guidance-and-counselling', 1, 'Guidance and Counselling', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes or NCE in two (2) subjects plus the UTME requirements.', 'Five (5) \'O\' Level NTC/NBC credit passes or TC II merit including English Language with \'O\' Level pass in Mathematics.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11773, 'iaued', 'special-education', 1, 'Special Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Arts or Social Science subjects. (ii) NCE merit in Arts or Social Science subjects.', 'Five (5) \'O\' Level credit passes including English Language.', 'Any three (3) Subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11774, 'iaued', 'agricultural-science-and-education', 1, 'Agricultural Science and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) passes at \'A\' Level in Biology /Zoology /Botany and any other Science subject. (ii) NCE merit in Biology and any other Science subject. (iii) NCE merit in Agriculture (Double Major).', 'Five (5) \'O\' Level credit passes or equivalents in English Language, Chemistry, Biology/Agricultural Science., Mathematics and another relevant subject.', 'Any three (3) subjects from Chemistry, Biology, Agriculture, Physics, Economics, Geography and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11775, 'iaued', 'education-and-social-studies', 1, 'Education and Social Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE Social Studies from recognized Colleges. (ii) Two (2) \'A\' Level passes in relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language plus two (2) Arts /Social Science subjects.', 'Any three (3) of Christian Religious Studies, Economics, Geography/Physics, Government, History and Islamic Studies.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11776, 'iaued', 'education-and-political-science', 1, 'Education and Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant subjects chosen from Government or History, Economics and Geography/Physics.(ii) NCE merit in Government/History, Economics and Geography/Physics.', 'Five (5) \'O\' Level credit passes or equivalent to include English Language, Government/History and three (3) other subjects.', 'Government or History plus two (2) other Arts or Social Sciences subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11777, 'iaued', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Economics and one (1) other relevant subject.(ii) NCE merit/credit in Economics and one (1) other subject.', 'Five (5) \'O\' Level credit passes to include English Language, Economics and Mathematics.', 'Economics, Mathematics and one (1) other subject from Geography/Physics, History, Government and Literature in English.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11778, 'iaued', 'business-education', 1, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes or NCE merit in two (2) relevant subjects.(ii) NCE merit in Business Education Double Major.', 'Five (5) TC II merit, \'O\' Level or NTC/NBC credit passes including English Language, Mathematics, Economics and two (2) other subjects in the Social Sciences or Arts. For NBC, the other subjects could be from any of the following: Commerce, Office Practice, Principles of Accounts, Secretarial Duties, Typewriting and Shorthand.', 'Mathematics, Economics plus one (1) of Literature in English, History, Government, Geography, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11779, 'iaued', 'integrated-science', 1, 'Integrated Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Biology/Chemistry and any other Science subject.', 'Any three (3) of Mathematics, Biology, Physics, Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11794, 'ibadan', 'law', 1, 'Law', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two papers at Advanced Level plus Credit in 5/6 other \'O\' level subjects including English Language and Literature in English. (ii) A good first Degree with credit in English Language and Literature at \'O\' Level', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at 2 sittings to include English Language, Literature in English and any other subjects from Arts, Social Sciences or Science.', 'English Language and any three subjects from Arts, Social Science and / or Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11795, 'ibadan', 'agricultural-and-environmental-engineering', 1, 'Agricultural and Environmental Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes in Physics and Mathematics plus UME requirements.', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at 2 sittings to include English Language, Physics, Chemistry and Mathematics with any ONE or TWO of the following subjects as the case may be; Biology, Agricultural Science, Further Mathematics, Technical Drawing, Economics, Geography, Metal Work and Wood Work. SSC credit passes in English Language, Mathematics, Physics, Chemistry and any from Introduction to Agricultural Science, Materials and Workshop Process and Machining, Tractor Layout Power Unit Under Carriage and Auto Electricity; Transmission System; Implement and Machine; Principles of Crop Husbandry and Land Use, Materials and Workshop Processes; Construction and Maintenance of Agricultural Machines; general Metal Work; General Wood Work and Building/Engineering Drawing.', 'English Language, Physics, Chemistry, and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11796, 'ibadan', 'agriculture', 1, 'Agriculture', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and one from Biology/Botany/Zoology/Agricultural Science, Economics, Physics, Geography and Geology/Mathematics (Pure & Applied).', 'Five (5) \'O\' level subjects at one sitting or Six (6) \'O\' level subjects at two (2) sittings to include: English Language, Biology/Agric Science, Chemistry, Mathematics and anyone/two of Geography, Physics and Economics.', 'English Language, Chemistry, Agriculture or Biology, Mathematics or Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11797, 'ibadan', 'civil-engineering', 1, 'Civil Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes in Physics and Mathematics plus UME requirements.', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at 2 sittings to include English Language, Physics, Chemistry and Mathematics with any ONE or TWO of the following subjects as the case may be; Biology, Agricultural Science, Further Mathematics, Technical Drawing, Economics, Geography, Metal Work and Wood Work. SSC credit passes to include Physics, Chemistry, Mathematics, English Language and one Science subject', 'English Language, Physics, Chemistry, and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11798, 'ibadan', 'biochemistry', 1, 'Biochemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level subjects from Mathematics, Physics, Chemistry, Biology, Zoology or Botany plus UME requirement.', 'Five (5) \'O\' Level Credit Passes in English Language, Mathematics, Physics, Chemistry and Biology', 'English Language, Physics, Chemistry, and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11799, 'ibadan', 'fisheries', 1, 'Fisheries', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in any of Chemistry, Biology, Botany, Zoology, Agricultural Science Geography, Mathematics (pure & applied), Physics, Geology and Economics. (ii)NCE Agriculture', 'Five (5) SSC credit passes in Biology/Agricultural Science, Chemistry, Mathematics and English Language plus any other Science subject.', 'Chemistry, Biology/Agricultural Science and any other Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
