(11801, 'ibadan', 'human-nutrition-and-dietetics', 1, 'Human Nutrition and Dietetics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level Passes in Chemistry, Biology and Physics plus UTME requirements.', 'Five (5) \'O\' level Credit Passes in English Language, Mathematics, Chemistry, Biology and Physics.', 'English Language, Physics, Chemistry, and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11802, 'ibadan', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes in Economics and any one of Mathematics or Statistics, Geography, History, Government, Physics, Chemistry and Agricultural Science', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at 2 sittings to include English Language, Mathematics, Economics and any two / three of Arts, Social Sciences or Science subjects.', 'English Language, Economics, Mathematics and any of Government, History, Geography, Lit-In-English, CRK/IRK.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11803, 'ibadan', 'medical-laboratory-science', 1, 'Medical Laboratory Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '3 A level passes in Chemistry, Biology and one other science subject.', 'Five (5) \'O\' Level Credit Passes in English Language, Mathematics, Physics, Chemistry and Biology', 'English Language, Physics, Chemistry, and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11804, 'ibadan', 'agricultural-economics', 1, 'Agricultural Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes in Chemistry and One from Biology / Botany / Zoology / Agricultural Science, Economics, Physics, Geography and Geology / Mathematics (Pure & Applied)', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at two sittings to include: English Language, Biology/Agric Science, Chemistry, Mathematics and anyone/two of Geography, Physics and Economics.', 'English Language, Chemistry, Agriculture or Biology, Mathematics or Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
