(11806, 'ibadan', 'education-and-chemistry', 1, 'Education and Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level subjects including Chemistry and one of Physics, Mathematics and Biology. NCE to include Chemistry, Physics, Biology, Mathematics or Geography with minimum of Credit or Merit', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at 2 sittings to include English Language and any other four or five Science subjects.', 'English Language, Biology, Chemistry and Physics (excluding Agric Science)', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11807, 'ibadan', 'medicine-and-surgery', 1, 'Medicine and Surgery', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) 3 A level passes in Physics, Chemistry, Biology or Zoology plus UME requirements. (ii) B.Sc in relevant fields.', 'Five (5) \'O\' Level Credit Passes in English Language, Mathematics, Physics, Chemistry and Biology', 'English Language, Physics, Chemistry, and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11808, 'ibadan', 'pharmacy', 1, 'Pharmacy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) A/Level Passes in Chemistry, Biology, Physics or Mathematics plus UME requirements. (ii) B.Sc. degree in relevant fields', 'Five (5) \'O\' Level Credit Passes in English Language, Mathematics, Physics, Chemistry and Biology at a single sitting.', 'English Language, Physics, Chemistry, and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11809, 'ibadan', 'physiology', 1, 'Physiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two A level subjects from Mathematics, Physics, Chemistry, Biology, Zoology or Botany plus UME requirement.', 'Five (5) \'O\' Level Credit Passes in English Language, Mathematics, Physics, Chemistry and Biology', 'English Language, Physics, Chemistry, and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
