(11814, 'ibadan', 'education-and-yoruba', 1, 'Education and Yoruba', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least 2 \'A\' level passes to include Yoruba and another Arts or Social Science subjects.', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at two sittings to include: English Language, one Arts subject and any other three or four subjects from Arts, Social Sciences or Science.', 'English Language, one Arts subject and any other two subjects from Arts, Social Sciences or Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11815, 'ibadan', 'archaeology', 1, 'Archaeology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes or NCE with Credit pass in Arts subjects: Geography / Economics', 'Five (5) English Language, one Arts subject and any two Arts or Social Sciences. Commerce, Business Studies, Book Keeping, Accounting and Civic Education are not acceptable', 'Any two (2) subjects from Arts, Social Sciences and one of History, Religious Studies, Government and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11816, 'ibadan', 'classical-studies', 1, 'Classical Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two \'A\' level passes including Lit-In-English or History.', 'Five (5) \'O\' level Credits at one sitting or 6 \'O\' level Credit at two sittings to include English Language, Literature in English or History, one Arts or Social Science subjects and any other subjects.', 'English Language, Literature in English or History and any other two subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11817, 'ibadan', 'education-and-biology', 1, 'Education and Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two \'A\' level science subjects to include Biology or Zoology. NCE/ND candidates with minimum of Merit or Upper Credit in two science subjects to include Biology or Zoology or Animal Science. Direct entry candidate should also fulfil the UTME entry requirement.', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at 2 sittings to include English Language, Mathematics, Biology, Chemistry, and the 6th subject can be from Science, Arts and Social Sciences excluding Agric Science.', 'English Language, Biology, Chemistry and Physics (excluding Agric Science)', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11818, 'ibadan', 'education-and-mathematics', 1, 'Education and Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' level passes in Physics and Mathematics, NCE with minimum of Credit or Merit in Physics, Mathematics, Chemistry, and/or Geography', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at 2 sittings to include English Language and any other four or five Science subjects.', 'English Language, Mathematics and any other two Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11819, 'ibadan', 'physics', 1, 'Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' level passes in Physics and Mathematics, NCE and OND holders are eligible.', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at two sittings to include: English Language, Mathematics, Physics and any two or three of the following: Biology, Chemistry, Geography and Further Mathematics', 'English Language, Mathematics, Physics and any of the following: Biology, Chemistry, Geography and Further Mathematics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11820, 'ibadan', 'theatre-arts', 1, 'Theatre Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes in Arts, Social Science or Science subjects.', 'Five (5)\'O\' Level Credits at ONE sitting or 6 \'O\' Level Credits at TWO sittings to include English Language, Literature in English and other subjects from Arts or Social Science.', 'English Language, Literature in English and two other subjects from Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11821, 'ibadan', 'education-and-islamic-studies', 1, 'Education and Islamic Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes in Arabic and any other Arts or Social Science subjects', 'Five (5) \'O\' level credits at one sitting or 6 \'O\' level credits at two sittings to include: English Language, Islamic Studies and any other three or four subjects from Arts or Social Sciences.', 'English Language, Islamic Studies and any other two subjects from Arts, Science or Social Sciences', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11822, 'ibadan', 'communication-and-language-arts-education', 1, 'Communication and Language Arts Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes to include Literature in English and one other Arts or Social Science subjects.', 'Five (5) \'O\' Level Credits at one sitting or 6 \'O\' Level Credits at 2 sittings to include English Language, Lit-In-English, one Arts subject and any other two or three subjects from Arts, Social Sciences or Science. [Please note that Government and Economics are not Arts subjects ]', 'English Language and two Arts subjects including Literature in English and any other one from Arts, Social Sciences or Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11823, 'ibadan', 'english-language-and-literature', 1, 'English Language and Literature', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level subjects to include Literature in English.', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at two sittings to include: English Language, two Arts subjects including Literature-in-English and any other two or three subjects from Arts, Social Sciences or Science.', 'English Language and two Arts subjects including Literature in English and any other one from Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11824, 'ibadan', 'education-and-french', 1, 'Education and French', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in French and any other subject in Arts and Social Science subjects OR the equivalent of \'A\' level Certificate', 'Five (5) \'O\' level credits at ONE sitting or Six (6) \'O\' level credits at TWO (2) sittings to include Literature in English and any other subject from Arts and Social Science subjects.', 'English Language, Literature in English, any one other Arts subject and any other from Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11825, 'ibadan', 'agricultural-extension-and-rural-development', 1, 'Agricultural Extension and Rural Development', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes in Chemistry and One from Biology / Botany / Zoology / Agricultural Science, Economics, Physics, Geography and Geology / Mathematics (Pure & Applied)', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at two sittings to include: English Language, Biology/Agric Science, Chemistry, Mathematics and anyone/two of Geography, Physics and Economics.', 'English Language, Chemistry, Agriculture or Biology, Mathematics or Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11826, 'ibadan', 'french', 1, 'French', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level passes in French and any other subject in Arts and Social Science subjects OR the equivalent of \'A\' level Certificate', 'Five (5) \'O\' level credits at ONE sitting or Six (6) \'O\' level credits at TWO (2) sittings to include Literature in English and any other subject from Arts and Social Science subjects.', 'English Language, two Arts subjects to include Literature in English and any other Arts or Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11827, 'ibadan', 'education-and-geography', 1, 'Education and Geography', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Geography and any one of Economics, Government and History.', 'Five (5) \'O\' level subjects at one sitting or 6 \'O\' level subjects at two sittings to include English Language, Geography and any other subjects from Arts or Social Sciences.', 'English Language and any other three subjects from Arts or Social Sciences', 1, NULL, 0, NULL, NULL, NULL, NULL);
