(11882, 'ibadan', 'education-and-arabic', 1, 'Education and Arabic', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two \'A\' level passes in Arabic and any other Arts or Social Science subjects (ii) NCE in relevant subjects including Arabic at Merit level.', 'Five (5) \'O\' level credits at one sitting or Six (6) \'O\' level credits at two sittings to include: English Language, Arabic and any other subjects from Arts or Social Sciences.', 'English Language, Arabic and any other two from Arts, Science or Social Sciences', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11883, 'ibadan', 'educational-management', 1, 'Educational Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) OND with Upper Credit in Estate Management, Architecture Building Technology, Quantity Surveying, Urban and Regional Planning. (ii)Two (2) \'A\' Level passes in Mathematics, Economics, Geography, Biology and Physics.', 'Five (5) \'O\' level credit passes at one sitting or Six (6) \'O\' level credit passes subjects at two (2) sittings to include English Language, Mathematics, Geography and any two from Physics, Chemistry, Biology, Technical Drawing, Fine Arts, Surveying.', 'English Language, Mathematics, Economics, Geography or Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11884, 'ibadan', 'library-and-information-science', 1, 'Library and Information Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant subject plus the UTME requirements. (ii) NCE merit passes in relevant subjects.', 'Five (5) \'O\' level credit passes at one sitting or Six (6) \'O\' level credit passes at two (2) sittings in English Language, Mathematics and any other three or four relevant subjects from Arts, Social Sciences or Science.', 'English Language and any other three subjects from Arts, Social Sciences or Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11885, 'ibadan', 'early-childhood-education', 1, 'Early Childhood Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes chosen from relevant subjects. (ii) NCE merit level in PRE – PRIMARY/PRIMARY EDUCATION plus one U.I approved teaching subjects.', 'Five (5) \'O\' level credit passes at one sitting or Six (6) \'O\' level credit passes at two (2) sittings to include English Language, Government or History and three or four other subjects.', 'English Language and any other three subjects from Arts, Social Sciences or Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11886, 'ibadan', 'guidance-and-counselling', 1, 'Guidance and Counselling', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' level passes or NCE merit level in two (2) subjects (in teaching subjects available in U.I.) plus the UTME requirements.', 'Five (5) \'O\' level credit passes at one sitting or Six (6) \'O\' level credit passes at two (2) sittings to include English Language and any other relevant and related subjects from Arts, Science or Social Sciences.', 'English Language and any other related subjects from Arts, Science or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11887, 'ibadan', 'special-education', 1, 'Special Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Arts or Social Science subjects. (ii) NCE merit in Arts or Social Science subjects.', 'Five (5) \'O\' level credit passes at one (1) sitting or Six (6) \'O\' level credit passes at two (2) sittings to include English Language and any other four or five relevant subjects from Arts, Social Sciences or Science.', 'English Language and any other three relevant subjects from Arts, Social Sciences or Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11888, 'ibadan', 'adult-education', 1, 'Adult Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes. (ii) NCE with passes in two (2) subjects at Merit level.', 'Five (5) \'O\' Level credit passes or Six (6) \'O\' Level Credits at Two (2) sittings including English Language, and any other subjects from Arts, Social Sciences or Science.', 'English Language and any three subjects from Arts, Social Science and/or Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11889, 'ibadan', 'education-and-political-science', 1, 'Education and Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant subjects chosen from Government or History, Economics and Geography/Physics. (ii) NCE merit in Government/History, Economics and Geography/Physics.', 'Five (5) \'O\' Level credit passes at one (1) sitting or Six (6) \'O\' Level credit passes at two (2) sitting to include English Language, Government/History and three (3) other subjects.', 'English Language, Government or History plus two (2) other Arts or Social Sciences subjects or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11890, 'ibadan', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two \'A\' level passes in Economics and any one of Mathematics, Statistics, Geography, Physics, Government, History, Chemistry and Agricultural Science(ii) NCE merit/credit in Economics and one (1) other subject.', 'Five (5) \'O\' level subjects at one sitting or Six (6) \'O\' level subjects at 2 sittings to include English Language, Mathematics, Economics and any two / three of Arts, Social Sciences or Science.', 'English Language, Economics, Mathematics and any of Government, History, Geography, Lit-In-English, CRK/IRK.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(11921, 'ibadancitypoly', 'business-administration-and-management', 2, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11922, 'ibadancitypoly', 'statistics', 2, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Basic Science and any three (3) of the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics are compulsory.', 'Any of the three (3): 1. Economics/ Commerce 2. History/Government 3. CRS/IS 4. Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11923, 'ibadancitypoly', 'computer-science', 2, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, a basic science and three (3) other subjects chosen from the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics is compulsory.', 'Mathematics and any two (2) of Geography, Physics, Economics or Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11924, 'ibadancitypoly', 'computer-engineering-technology', 2, 'Computer Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering a pass in Biology is required. \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics and Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11925, 'ibadancitypoly', 'electrical-electronics-engineering-technology', 2, 'Electrical / Electronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11928, 'ibdpoly', 'geological-technology', 2, 'Geological Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five SSC credit passes in Physics, Mathematics and Chemistry and any two (2) subjects from 1. Geography 2. Biology 3. Agricultural Science 4. Economics 5. Basic Electronics 6. Further Mathematics 7. English Language. \'O\' Level credit pass in English Language is compulsory.', 'Mathematics, Chemistry and Physics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11929, 'ibdpoly', 'insurance', 2, 'Insurance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting and Shorthand', 'Mathematics and any two (2) of Economics, Geography, Commerce or Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11930, 'ibdpoly', 'library-and-information-science', 2, 'Library and Information Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language and Mathematics and any three (3) other subjects from: History, Literature in English, Economics/Commerce, Fine Arts, Government, Biology Physics, Chemistry Basic Electricity Geography, Typewriting, Commerce/Principles of Accounting.', 'Any three (3) subjects from Arts/Social Science/Physical Science.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11931, 'ibdpoly', 'local-government-studies', 2, 'Local Government Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand.', 'Government or History and any two (2) of Economics, Commerce, Geography and Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11932, 'ibdpoly', 'mass-communication', 2, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language and Mathematics and any three (3) other subjects from: History, Literature in English, Economics/Commerce, Fine Arts, Government, Biology Physics, Chemistry Basic Electricity Geography, Typewriting, Commerce/Principles of Accounting.', 'Any three (3) subjects from Arts/Social Science/Physical Science.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11933, 'ibdpoly', 'mechanical-engineering-technology', 2, 'Mechanical Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any one (1) subject from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required.', 'Mathematics, Chemistry and Physics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11934, 'ibdpoly', 'mechatronics-engineering-technology', 2, 'Mechatronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce. \'O\' Level credit pass in English Language is required.', 'Mathematics, Chemistry and Physics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11935, 'ibdpoly', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11936, 'ibdpoly', 'agricultural-technology', 2, 'Agricultural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. At least \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science, Chemistry and any other Science subject', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11937, 'ibdpoly', 'agricultural-engineering-technology', 2, 'Agricultural Engineering / Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, English Language, Physics and any two (2) of the following: Biology/Agricultural Science Chemistry Technical Drawing Basic Electronics/Basic Electricity Auto Mechanics Metal Work Further Mathematics Food and Nutrition Geography', 'Mathematics and Physics/Technical Drawing, Chemistry or any two (2) Science subjects.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11938, 'ibdpoly', 'architectural-technology', 2, 'Architectural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics, English Language and any two (2) subjects from the following: Biology, Fine Art, Chemistry, History English Language, Geography, Further Mathematics Economics/Commerce, Religious Knowledge, Technical Drawing, Business Method. \'O\' Level pass in Fine Art or Technical Drawing will be an advantage.', 'Mathematics and any two (2) of Physics, Chemistry and Technical Drawing.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11939, 'ibdpoly', 'arts-and-design', 2, 'Arts and Design', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Fine Art Mathematics and any two (2) of the following: History/Government Chemistry/Physical Science, Biology/Agricultural Science, Literature in English, Clothing and Textiles, Religious Knowledge, Economics/Commerce Geography, Home Economics', 'Fine Art and any two (2) of History, Chemistry, Mathematics, Biology and a Nigerian Language.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11940, 'ibdpoly', 'banking-and-finance', 2, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and any two (2) of Economics, Geography, History, Government, Commerce or Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11941, 'ibdpoly', 'building-technology', 2, 'Building Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following: Economics/Commerce, Technical Drawing/Fine Art, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, And at least a credit pass in English Language is Compulsory. A pass in Art or Technical Drawing will be an advantage.', 'Mathematics, Physics and Chemistry or Fine Arts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11942, 'ibdpoly', 'procurement-and-supply-chain-management', 2, 'Procurement and Supply Chain Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in English Language not Literature in English and Mathematics and any three (3) subjects of the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography, Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Government, History and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11943, 'ibdpoly', 'business-administration-and-management', 2, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11944, 'ibdpoly', 'quantity-surveying', 2, 'Quantity Surveying', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following Economics/Commerce, Technical Drawing/Fine Arts, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, and \'O\' Level credit pass in English Language is Compulsory. \'O\' Level pass in Art or Technical Drawing is required.', 'Any three (3) of Physics, Mathematics, Geography, Economics, Biology/Agricultural Science', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11945, 'ibdpoly', 'science-laboratory-technology', 2, 'Science Laboratory Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and two (2) of Physics, Biology/Agricultural Science/Health Science, Chemistry, and two (2) other subjects from Technical Drawing, Metal or Wood Work, Basic Electricity, Geography, Further Mathematics, and Fine Arts. \'O\' Level credit pass in each of the three (3) Basic Science subjects - Biology, Chemistry, Physics and a \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Mathematics, Biology/Agricultural Science or Physics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(11946, 'ibdpoly', 'office-technology-and-management', 2, 'Office Technology and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) of the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English, Geography, Office Practice, Biology/Agricultural Science, Chemistry, Physics, History/Government, Typewriting, Shorthand', 'Any three (3) of: 1. Mathematics 2. Economics 3. Commerce 4. History/Govt. 5. Geography 6. CRS/IS 7. Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL);
