(13489, 'imtenu', 'public-administration', 2, 'Public Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in English Language not Literature in English and Mathematics and any three (3) subjects of the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography, Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Government, History and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(13490, 'imtenu', 'business-administration', 2, 'Business Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
