(13683, 'jigpoly', 'social-development', 2, 'Social Development', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand.', 'Government or History and any two (2) of Economics, Commerce, Geography and Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(13684, 'jigpoly', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(13685, 'jigpoly', 'architectural-technology', 2, 'Architectural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics, English Language and any two (2) subjects from the following: Biology, Fine Art, Chemistry, History English Language, Geography, Further Mathematics Economics/Commerce, Religious Knowledge, Technical Drawing, Business Method. \'O\' Level pass in Fine Art or Technical Drawing will be an advantage.', 'Mathematics and any two (2) of Physics, Chemistry and Technical Drawing.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(13686, 'jigpoly', 'building-technology', 2, 'Building Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following: Economics/Commerce, Technical Drawing/Fine Art, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, And at least a credit pass in English Language is Compulsory. A pass in Art or Technical Drawing will be an advantage.', 'Mathematics, Physics and Chemistry or Fine Arts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(13687, 'jigpoly', 'public-administration', 2, 'Public Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in English Language not Literature in English and Mathematics and any three (3) subjects of the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography, Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Government, History and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
