(14317, 'katpoly', 'forestry-technology', 2, 'Forestry Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. \'O\' Level credit pass in English Language is required.', 'Mathematics and any two (2) of Chemistry, Physics or Technical Drawing.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14318, 'katpoly', 'fisheries-technology', 2, 'Fisheries Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science and two (2) of Physics, Chemistry, Mathematics and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14319, 'katpoly', 'hospitality-management', 2, 'Hospitality Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science and two (2) of Physics, Chemistry, Mathematics and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14320, 'katpoly', 'library-and-information-science', 2, 'Library and Information Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language and Mathematics and any three (3) other subjects from: History, Literature in English, Economics/Commerce, Fine Arts, Government, Biology Physics, Chemistry Basic Electricity Geography, Typewriting, Commerce/Principles of Accounting.', 'Any three (3) subjects from Arts/Social Science/Physical Science.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14321, 'katpoly', 'mass-communication', 2, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language and Mathematics and any three (3) other subjects from: History, Literature in English, Economics/Commerce, Fine Arts, Government, Biology Physics, Chemistry Basic Electricity Geography, Typewriting, Commerce/Principles of Accounting.', 'Any three (3) subjects from Arts/Social Science/Physical Science.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14322, 'katpoly', 'mechanical-engineering-technology', 2, 'Mechanical Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any one (1) subject from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required.', 'Mathematics, Chemistry and Physics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14323, 'katpoly', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14324, 'katpoly', 'agricultural-technology', 2, 'Agricultural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. At least \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science, Chemistry and any other Science subject', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14325, 'katpoly', 'agricultural-engineering-technology', 2, 'Agricultural Engineering / Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, English Language, Physics and any two (2) of the following: Biology/Agricultural Science Chemistry Technical Drawing Basic Electronics/Basic Electricity Auto Mechanics Metal Work Further Mathematics Food and Nutrition Geography', 'Mathematics and Physics/Technical Drawing, Chemistry or any two (2) Science subjects.', 2, NULL, 0, NULL, NULL, NULL, NULL),
