(14332, 'katpoly', 'business-administration', 2, 'Business Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14333, 'katpoly', 'science-laboratory-technology', 2, 'Science Laboratory Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following Economics/Commerce, Technical Drawing/Fine Arts, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, and \'O\' Level credit pass in English Language is Compulsory. \'O\' Level pass in Art or Technical Drawing is required.', 'Any three (3) of Physics, Mathematics, Geography, Economics, Biology/Agricultural Science', 2, NULL, 0, NULL, NULL, NULL, NULL),
