(14335, 'katpoly', 'office-technology-and-management', 2, 'Office Technology and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) of the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English, Geography, Office Practice, Biology/Agricultural Science, Chemistry, Physics, History/Government, Typewriting, Shorthand', 'Any three (3) of: 1. Mathematics 2. Economics 3. Commerce 4. History/Govt. 5. Geography 6. CRS/IS 7. Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14337, 'katpoly', 'home-and-rural-economics', 2, 'Home and Rural Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in a ny three (3) of the following: Government, Business Methods, Economics/Commerce, Religious Knowledge, Any Nigerian Language, Geography, Bookkeeping and Principles of Accounts History, Clothing and Textile, plus \'O\' Level credit passes in English Language and Mathematics.', 'Biology, Agricultural Science and any other subject.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14338, 'katpoly', 'welding-and-fabrication-technology', 2, 'Welding and Fabrication Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from Biology/ Agricultural Science, Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Technology), Further Mathematics, English Language, Geography, Economics/ Commerce. At least a credit pass in English Language is required.', 'Mathematics, Physics and Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
