(14492, 'kogipoly', 'foundry-engineering-technology', 2, 'Foundry Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. \'O\' Level pass in English Language is required.', 'Mathematics, Chemistry, Physics or Technical Drawing', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14493, 'kogipoly', 'library-and-information-science', 2, 'Library and Information Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language and Mathematics and any three (3) other subjects from: History, Literature in English, Economics/Commerce, Fine Arts, Government, Biology Physics, Chemistry Basic Electricity Geography, Typewriting, Commerce/Principles of Accounting.', 'Any three (3) subjects from Arts/Social Science/Physical Science.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14494, 'kogipoly', 'mechanical-engineering-technology', 2, 'Mechanical Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any one (1) subject from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required.', 'Mathematics, Chemistry and Physics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14495, 'kogipoly', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14496, 'kogipoly', 'architectural-technology', 2, 'Architectural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics, English Language and any two (2) subjects from the following: Biology, Fine Art, Chemistry, History English Language, Geography, Further Mathematics Economics/Commerce, Religious Knowledge, Technical Drawing, Business Method. \'O\' Level pass in Fine Art or Technical Drawing will be an advantage.', 'Mathematics and any two (2) of Physics, Chemistry and Technical Drawing.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14497, 'kogipoly', 'arts-and-design', 2, 'Arts and Design', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Fine Art Mathematics and any two (2) of the following: History/Government Chemistry/Physical Science, Biology/Agricultural Science, Literature in English, Clothing and Textiles, Religious Knowledge, Economics/Commerce Geography, Home Economics', 'Fine Art and any two (2) of History, Chemistry, Mathematics, Biology and a Nigerian Language.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14498, 'kogipoly', 'metallurgical-engineering-technology', 2, 'Metallurgical Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any one (1) subject from Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce.', 'Mathematics, Chemistry and Physics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14499, 'kogipoly', 'mineral-resources-engineering-technology', 2, 'Mineral Resources Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any one (1) subject from Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce.', 'Mathematics, Physics, Chemistry or Technical Drawing.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14500, 'kogipoly', 'building-technology', 2, 'Building Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following: Economics/Commerce, Technical Drawing/Fine Art, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, And at least a credit pass in English Language is Compulsory. A pass in Art or Technical Drawing will be an advantage.', 'Mathematics, Physics and Chemistry or Fine Arts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14501, 'kogipoly', 'public-administration', 2, 'Public Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in English Language not Literature in English and Mathematics and any three (3) subjects of the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography, Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Government, History and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14502, 'kogipoly', 'business-administration', 2, 'Business Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14503, 'kogipoly', 'science-laboratory-technology', 2, 'Science Laboratory Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and two (2) of Physics, Biology/Agricultural Science/Health Science, Chemistry, and two (2) other subjects from Technical Drawing, Metal or Wood Work, Basic Electricity, Geography, Further Mathematics, and Fine Arts. \'O\' Level credit pass in each of the three (3) Basic Science subjects - Biology, Chemistry, Physics and a \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Mathematics, Biology/Agricultural Science or Physics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14504, 'kogipoly', 'office-technology-and-management', 2, 'Office Technology and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) of the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English, Geography, Office Practice, Biology/Agricultural Science, Chemistry, Physics, History/Government, Typewriting, Shorthand', 'Any three (3) of: 1. Mathematics 2. Economics 3. Commerce 4. History/Govt. 5. Geography 6. CRS/IS 7. Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14505, 'kogipoly', 'statistics', 2, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Basic Science and any three (3) of the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics are compulsory.', 'Any of the three (3): 1. Economics/ Commerce 2. History/Government 3. CRS/IS 4. Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14506, 'kogipoly', 'urban-and-regional-planning', 2, 'Urban and Regional Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Geography and three (3) other subjects from: English Language, Economics/Commerce, Fine Art/Technical Drawing, Further Mathematics, Chemistry, Physics, Biology/Agricultural Science, History/Government Business Methods/Bookkeeping and Principles of Accounting One of the three (3) subjects must be a basic science subject. At least a credit pass in English Language is compulsory.', 'Geography and two (2) other subjects from course requirement.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14507, 'kogipoly', 'surveying-and-geoinformatics', 2, 'Surveying and Geoinformatics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any other three (3) subjects from the following: Further Mathematics, Chemistry; Technical Drawing/Fine Art, Geography, Economics/Commerce, Biology/Agricultural Science, English Language, Basic Electricity At least \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Chemistry/Agricultural Science, Biology, Economics and Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14508, 'kogipoly', 'civil-engineering-technology', 2, 'Civil Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering a pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics and Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14509, 'kogipoly', 'computer-science', 2, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, a basic science and three (3) other subjects chosen from the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics is compulsory.', 'Mathematics and any two (2) of Geography, Physics, Economics or Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14510, 'kogipoly', 'electrical-electronics-engineering-technology', 2, 'Electrical / Electronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14523, 'koladaisi', 'accounting', 1, 'Accounting', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14524, 'koladaisi', 'business-administration', 1, 'Business Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14525, 'koladaisi', 'banking-and-finance', 1, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2)\'A\' Level passes in Accounting or Economics and one other subject. (ii) NCE merit in relevant subjects. (iii) ND credit. (iv) Foundation International exam such as ICAN, ACCA, ICMA, GPFA.', 'Five (5)SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, one Social Science subject and any other subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
