(14527, 'koladaisi', 'biochemistry', 1, 'Biochemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Chemistry, Mathematics, Physics and Biology. NCE/ND/HND in related programmes plus the UTME requirements.', 'Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Physics and Biology.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14528, 'koladaisi', 'library-and-information-science', 1, 'Library and Information Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2)\'A\' Level passes in relevant subjects. (ii) NCE/ND in relevant subject/programmes', 'Five (5)SSC credit passes including English Language and Mathematics.', 'Any three (3) Arts or Social Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
