(14530, 'koladaisi', 'english-language', 1, 'English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes to include Literature in English and one other Arts subject.', 'Five (5) SSC credit passes to include Literature in English, English Language and three other Arts or Social Science subjects.', 'Literature in English, one other Arts subject and another Arts or Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14531, 'koladaisi', 'chemistry', 1, 'Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Chemistry and any one (1) of Physics, Mathematics or Biology. (ii) ND/NCE with good grades in relevant \'O\' Level subjects.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology.', 'Chemistry and two (2) of Physics, Biology and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
