(14535, 'koladaisi', 'mathematics', 1, 'Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, ') Two (2) \'A\' Level passes in Mathematics and any other science subject. (ii) NCE merit in Mathematics and one (1) of Physics, Chemistry or Economics', 'Five (5) SSC credit passes including English Language, Mathematics and Physics or Chemistry.', 'Mathematics and any two (2) of Physics, Chemistry and Economics or Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14536, 'koladaisi', 'microbiology', 1, 'Microbiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and any one (1) from Biology, Zoology or Botany.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology and Physics.', 'Biology, Chemistry and either Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
