(14894, 'kwasu', 'library-and-information-science', 1, 'Library and Information Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Two (2) \'A\' Level passes in science subjects including Mathematics (ii) NCE merit in Mathematics and one (1) other Science or Social Science subject.', 'Five (5) SSC credit passes to include English Language, Mathematics, Physics plus two (2) other Science subjects.', 'Mathematics, Physics and one (1) of Biology, Chemistry, Agric Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14895, 'kwasu', 'sociology', 1, 'Sociology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Three (3) Social Science or Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14896, 'kwasu', 'entrepreneurship', 1, 'Entrepreneurship', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes to include Economics and at least one of, Accounts, Business Management, Government, Geography or Mathematics.', 'Five (5) SSC credit passes to include English Language, Mathematics, Economics, one Science subject and one other Social Science or Commercial subject.', 'Economics, Mathematics and one other Social Science or Commercial subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14897, 'kwasu', 'business-and-entrepreneurship-studies', 1, 'Business and Entrepreneurship Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes to include Economics and at least one of, Accounts, Business Management, Government, Geography or Mathematics.', 'Five (5) SSC credit passes to include English Language, Mathematics, Economics, one Science subject and one other Social Science or Commercial subject.', 'Economics, Mathematics and one other Social Science or Commercial subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14898, 'kwasu', 'food-science-and-technology', 1, 'Food Science and Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes in two (2) of Physics Chemistry, and Mathematics. (ii) ND/HND upper credit in relevant programmes.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics, English Language and any other Science subject.', 'Mathematics, Chemistry and Physics or Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14899, 'kwasu', 'computer-engineering', 1, 'Computer Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Three (3) \'A\' Level passes in Pure Mathematics or Pure and Applied Mathematics, Chemistry and Physics.', 'Five (5) SSC credit passes to include Mathematics, Further Mathematics, Chemistry, Physics and English Language.', 'Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
