(14906, 'kwasu', 'special-education', 1, 'Special Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Arts or Social Science subjects. (ii) NCE merit in Arts or Social Science subjects.', 'Five (5) \'O\' Level credit passes including English Language.', 'Any three (3) Subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14907, 'kwasu', 'business-education', 1, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes or NCE merit in two (2) relevant subjects.(ii) NCE merit in Business Education Double Major.', 'Five (5) TC II merit, \'O\' Level or NTC/NBC credit passes including English Language, Mathematics, Economics and two (2) other subjects in the Social Sciences or Arts. For NBC, the other subjects could be from any of the following: Commerce, Office Practice, Principles of Accounts, Secretarial Duties, Typewriting and Shorthand.', 'Mathematics, Economics plus one (1) of Literature in English, History, Government, Geography, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14957, 'lagcity', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14958, 'lagcity', 'business-administration-and-management', 2, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14959, 'lagcity', 'office-technology-and-management', 2, 'Office Technology and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) of the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English, Geography, Office Practice, Biology/Agricultural Science, Chemistry, Physics, History/Government, Typewriting, Shorthand', 'Any three (3) of: 1. Mathematics 2. Economics 3. Commerce 4. History/Govt. 5. Geography 6. CRS/IS 7. Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14960, 'lagcity', 'computer-science', 2, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, a basic science and three (3) other subjects chosen from the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics is compulsory.', 'Mathematics and any two (2) of Geography, Physics, Economics or Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14961, 'lagcity', 'computer-engineering-technology', 2, 'Computer Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering a pass in Biology is required. \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics and Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL);
INSERT INTO `institution_program` (`id`, `institution_id`, `program_id`, `level_id`, `name`, `description`, `remarks`, `program_mode_id`, `duration`, `tuition_fee`, `utme_cutoff`, `requirements`, `direct_entry`, `o_level`, `utme_subjects`, `accreditation_body_id`, `accreditation_status_id`, `is_distinguished`, `accreditation_grant_date`, `accreditation_expiry_date`, `created_at`, `updated_at`) VALUES
(14962, 'lagcity', 'electrical-electronics-engineering-technology', 2, 'Electrical / Electronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(14964, 'lagos', 'accountancy-accounting', 1, 'Accountancy / Accounting', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three (3) JUPEB subjects: Accounting, Economics and any one (1) of Business Management, Government and Geography and Mathematics. Three (3) \'A\' level passes in Accounting, Economics and any one of Business Management, Government, Mathematics and Geography.', 'Five O/Level credit passes to include English Language, Mathematics, Economics and any two (2) subjects from the following: Geography, Further Mathematics, Financial Accounting/Principles of Accounting, Government, Business Management, Data Processing/Computer Studies, and Biology.', 'English Language, Mathematics, Economics and any one of Financial Accounting, Geography, Government and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14965, 'lagos', 'banking-and-finance', 1, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three (3) JUBEB subjects: Economics and any two (2) from Financial Accounting, Business Management/Studies, Mathematics, Geography and Government. Three (3) \'A\' level passes in Economics and any two (2) subjects from Financial Accounting, Business Studies, Mathematics, Geography and Government.', 'Five O/Level credit passes in English Language, Mathematics, Economics and any two (2) subjects from Financial Accounting, Geography, Government, Commerce, Business Studies, Physics and Chemistry.', 'English Language, Mathematics, Economics and any one (1) subject from Science, Social Science or Arts.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14966, 'lagos', 'finance', 1, 'Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three (3) JUBEB subjects: Economics and any two (2) from Financial Accounting, Business Management/Studies, Mathematics, Geography and Government. Three (3) \'A\' level passes in Economics and any two (2) subjects from Financial Accounting, Business Studies, Mathematics, Geography and Government.', 'Five O/Level credit passes in English Language, Mathematics, Economics and any two (2) subjects from Financial Accounting, Geography, Government, Commerce, Business Studies, Physics and Chemistry.', 'English Language, Mathematics, Economics and any one (1) subject from Science, Social Science or Arts.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14967, 'lagos', 'actuarial-science', 1, 'Actuarial Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three (3) JUBEB subjects: Mathematics, Economics and any one (1) of Financial Accounting, Geography, Government, Biology, Business Studies, Chemistry, Physics, Further Mathematics. Three (3) \'A\' level passes in Mathematics, Economics and any one (1) of Financial Accounting, Geography, Government, Biology, Business Studies, Chemistry, Physics, Further Mathematics.', 'Five O/Level credit passes in English Language, Mathematics, Economics, and any two (2) of Financial Accounting, Data Processing, Further Mathematics, CRS, IRS, Geography, Government, Biology, Chemistry, Physics, Commerce, Civic Education, Insurance.', 'English Language, Mathematics, Economics and any one (1) subject from Financial Accounting, Geography, Government, Biology, Chemistry, Physics, Further Mathematics, and Commerce.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14968, 'lagos', 'business-administration', 1, 'Business Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three (3) JUBEB subjects: Economics and any two (2) from Financial Accounting, Business Management/Studies, Mathematics, Geography and Government. Three (3) \'A\' level passes in Economics and any two (2) of Financial Accounting, Business Management, Government, Geography or Statistics.', 'Five O/Level credit passes in English Language, Mathematics, Economics, and any two (2) subjects from Arts, Science and Social Sciences.', 'English Language, Mathematics, Economics and any one (1) subject from Science, Social Science or Arts.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14969, 'lagos', 'law', 1, 'Law', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. (i) Very good passes in JUPEB/A\' Level Subjects: Literature-in-English and any two of History, Government, Economics, CRS, IRS, Yoruba, Geography, Igbo, Law, Accounting, Hausa, Politics and Social Science.II. (ii) First Degree with a minimum of Second Class Upper. \"Lagos does not accept JUPEB / A\' level passes in Fine Arts, Commerce or Music\"', 'Five O/Level credit passes in English Language, Mathematics, Literature in English and any two Arts or Social Sciences subjects or Principles of Accounting and any one of Arts or Social Science subjects. \"Lagos does not accept Civic Education\"', 'English Language and any three Arts or Social Sciences subjects. Lagos accepts only ONE of Economics or Commerce or Accounting. Lagos also accepts Principle of Accounting. \"Lagos does not accept Music or Fine Arts\"', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14970, 'lagos', 'biomedical-engineering', 1, 'Biomedical Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A\' Level subjects: Physics, Mathematics and Chemistry.', 'Six O/Level credit passes in English, Mathematics, Further Mathematics, Biology, Physics and Chemistry.', 'English Language, Chemistry, Mathematics & Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14971, 'lagos', 'building', 1, 'Building', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. (i) Three passes in JUPEB/A\' Level subjects: Mathematics, Physics and Chemistry. II. (ii) OND (Distinction) in Building, Civil Engineering or Quantity Surveying into 200 level.(iii) HND (Upper Credit) in Building, Civil Engineering or Quantity Surveying into 300 level.', 'Five O/Level credit passes in English Language, Mathematics, Physics, Chemistry and Further Mathematics.', 'English Language, Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14972, 'lagos', 'chemical-engineering', 1, 'Chemical Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. i Very good passes in three JUPEB/A\' Level subjects: Physics, Mathematics and Chemistry. II. ii \'A\' level Cambridge iii HND/ND (Upper Credit) in related Engineering courses.', 'Five O/Level credit passes in English, Mathematics, Further Mathematics, Physics and Chemistry.', 'English Language, Chemistry, Mathematics & Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14973, 'lagos', 'educational-administration', 1, 'Educational Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE credit/merit in Arts, Social Sciences. ii. Very good passes in any three JUBEP subjects: Economics, Literature-in-English, CRS/IRS, Government, History, Geography, Igbo/Yoruba and French.iii Three \'A\' Level passes from English Language, History, French, Geography, Mathematics, Igbo/Yoruba, CRS/IRS, Economics and Government.', 'Five O/Level credit passes in English Language, Mathematics, Economics and any two of Literature-in-English, History, Government, Economics, Geography, any Nigerian Language, CRS/IRS.', 'English Language and any three of Literature-in-English, History, Government, Geography, any Nigerian Language, CRS/IRS, Economics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14974, 'lagos', 'civil-engineering', 1, 'Civil Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. (i) Very good passes in three JUPEB/A\' Level subjects: Physics, Mathematics and Chemistry. II. (ii) \'A\' level Cambridge III. (iii) HND (Upper Credit) in Civil Engineering courses. (iv) ND (Distinction) in Civil Engineering courses.', 'Five O/Level credit passes in English Language, Mathematics, Further Mathematics, Physics and Chemistry.', 'English Language, Chemistry, Mathematics & Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14975, 'lagos', 'fisheries', 1, 'Fisheries', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in any of Chemistry, Biology, Botany, Zoology, Agricultural Science Geography, Mathematics (pure & applied), Physics, Geology and Economics. (ii)NCE Agriculture', 'Five (5) SSC credit passes in Biology/Agricultural Science, Chemistry, Mathematics and English Language plus any other Science subject.', 'Chemistry, Biology/Agricultural Science and any other Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14976, 'lagos', 'insurance', 1, 'Insurance', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14977, 'lagos', 'dentistry-and-dental-surgery', 1, 'Dentistry and Dental Surgery', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(a) JUPEB/A\' -level passes in Physics Chemistry and Biology. (b) B.Sc. Degree (first class/second class upper) in Medical related fields.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14978, 'lagos', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A Level subjects: Economics, Mathematics and any one of Accounting, Geography, Government, Physics, Chemistry and Biology. Three Cambridge \'A\' Level passes in Economics, Mathematics and any one of the following: Accounting, Geography, Mathematics, Government, Physics and Biology.', 'Five \'O\' Level credit passes in English Language, Mathematics, Economics and any two subjects from: Biology, Financial Accounting, Geography and Government.', 'English, Mathematics, Economics and any one subject from Biology, Financial Accounting, Geography and Government.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14979, 'lagos', 'medical-laboratory-science', 1, 'Medical Laboratory Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(a) JUPEB/\'A\' -level passes in Physics Chemistry and Biology.(b) B.Sc. Degree (first class/second class upper) in Medical related fields. (c) Pass in Medical Laboratory Technician Diploma Examination with not less than a \"B\" grade.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14981, 'lagos', 'education-and-chemistry', 1, 'Education and Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE with credit/merit in Chemistry and any Science subject. ii. Very good passes in the following JUPEB subjects: Chemistry, Physics and Biology.', 'Five O/Level credit passes in English Language, Mathematics, Chemistry, and any two of Physics, Biology and Agricultural Science.', 'English Language, Chemistry and any two of Physics, Biology, Agricultural Science and Integrated Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14982, 'lagos', 'medicine-and-surgery', 1, 'Medicine and Surgery', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(a) JUPEB/\'A\' -level passes in Physics Chemistry and Biology. (b) B.Sc. Degree (first class/second class upper) in Medical related fields.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14983, 'lagos', 'pharmacy', 1, 'Pharmacy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three (3) JUPEB/\'A\'-level subjects: Physics, Chemistry and Biology. (b) does not accept B.Sc. degrees', 'Five O/Level credit passes in English Language, Mathematics, Physics, Chemistry and Biology.', 'English Language, Physics, Chemistry and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14984, 'lagos', 'pharmacology', 1, 'Pharmacology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(a) JUPEB/\'A\' -level passes in Physics Chemistry and Biology. (b) B.Sc. Degree (first class/second class upper) in Medical related fields.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14985, 'lagos', 'physiology', 1, 'Physiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(a) JUPEB/\'A\' -level passes in Physics Chemistry and Biology. (b) B.Sc. Degree (first class/second class upper) in Medical related fields.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14986, 'lagos', 'physiotherapy', 1, 'Physiotherapy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(a) JUPEB/\'A\' - level passes in Physics Chemistry and Biology. (b) B.Sc. Degree (first class/second class upper) in Medical related fields.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14987, 'lagos', 'geography', 1, 'Geography', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A\' Level subjects: Geography and any two of Economics, Chemistry, Biology, Physics, Mathematics and Government.', 'Five \'O\' Level credit passes in English Language, Mathematics, Geography and any two subjects from Science or Social Sciences.', 'English Language, Geography and any two from Biology, Chemistry, Physics, Economics, Government and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14988, 'lagos', 'radiography', 1, 'Radiography', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Passes in three (3) JUPEB/A\' level subjects: Physics, Chemistry, Biology.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14989, 'lagos', 'biochemistry', 1, 'Biochemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\' level subjects: Biology, Chemistry and Physics Candidates must satisfy the UTME requirements.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14990, 'lagos', 'education-and-integrated-science', 1, 'Education and Integrated Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE with at least credit/merit in Chemistry and any Science subjects.ii. Very good passes in the following JUPEB subjects: Physics, Chemistry and Biology. iii. Three \'A\' Level passes in Science subjects.', 'Five O/Level credit passes in English Language, Mathematics, Physics and any two of Chemistry, Biology, Agricultural Science.', 'English Language, Biology and any two of Chemistry, Physics, Agricultural Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14991, 'lagos', 'education-and-yoruba', 1, 'Education and Yoruba', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE credit/merit in Primary Education Studies and any two teaching subjects. ii. Very good passes in three JUPEB subjects: Arts or Social Science. iii. Three \'A\' Level passes in Yoruba, and any of English, CRS/IRS, Igbo, French, History, Geography and Arabic.', 'Five O/Level credit passes in English Language, Mathematics, and any three subjects from Arts, Science and Social Sciences.', 'English Language and any three subjects from Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14992, 'lagos', 'christian-religious-studies', 1, 'Christian Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Passes at the JUPEB, GCE A/level or its equivalents. One of the A/level Subjects should be CRS. NCE with credit or merit in CRS.', 'Five Credit passes in English Language, Mathematics, CRS and any other two subjects.', 'English Language, CRS and any two (2) from Literate-in-English, History, Government, French, Yoruba, Igbo, Hausa, Visual Arts, Economics and Commerce.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14993, 'lagos', 'education-and-biology', 1, 'Education and Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE with credit/merit in Biology and any Science subject. ii. Very good passes in the following JUPEB subjects: Biology, Chemistry and Physics.', 'Five O/Level credit passes in English Language, Biology, Chemistry, Mathematics and any one of Physics, Agricultural Science, Health Science.', 'English Language, Biology and any two of Chemistry, Physics, Mathematics, Integrated Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14994, 'lagos', 'creative-arts', 1, 'Creative Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A\' Level subjects: i. Theatre Arts: Literature in English and any two of Igbo/Yoruba, CRS/IRS, French, History, Government, Music and Visual Arts. Also accept NCE at credit/merit level in Drama/Theatre. ii. Visual Arts: Visual Arts and any other two subjects. Also accepts HND/OND at upper credit level, NCE at credit/merit in Fine Arts/Visual Arts or IGCSE. iii. Music: Any three from Music, Literature in English, Igbo/Yoruba, CRS/IRS, French, History, Commerce, Government, Economics, Chemistry, Biology, Further Mathematics and Visual Arts. Accepts OND/NCE at credit/merit level in Drama/Theatre, Music and Fine Arts. Also accept Diploma or Advanced level in Music from the Royal School of Music, London, Trinity College, London and Musical Society of Nigeria (MUSON) or IGCSE.', 'Theatre Arts Five O/Level credit passes in English Language, Literature-in-English, Mathematics, and any other two subjects, one of which must be an Art subject.Music: Five O/Level credit passes in English Language, Mathematics, one Art subject (which may be Music), and any two subjects.Visual Arts:Five O/Level credit passes in English Language, Mathematics, any of Visual Arts/Fine Arts/Photography/Craft Practice/Dyeing and Bleaching/Painting and Decoration, one Art subject and any other subject.', 'Theatre ArtsEnglish Language, Literature-in-English, one Art subject and other subject.Music:English Language, one Art subject and any two subjects.Visual Arts:English Language, one Art subject and any two subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14995, 'lagos', 'education-and-mathematics', 1, 'Education and Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE with credit/merit in Mathematics and any Science subject from Mathematics, Chemistry and Biology ii. Very good passes in three JUPEB subjects: Mathematics, Physics, Chemistry. iii. Three \'A\' Level passes in Mathematics and two Science subject.', 'Five O/Level credit passes in English Language, Mathematics, Physics and any two of Chemistry, Biology, Agricultural Science, Further Mathematics, Computer Studies/Data Processing.', 'English Language, Mathematics, Physics and any one of Chemistry, Biology, Computer Studies, Data Processing.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14996, 'lagos', 'physics', 1, 'Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\'-level subjects in Physics, Mathematics, and Chemistry. Candidate must satisfy the O/level Requirements which include credit in Further Mathematics.', 'Five O/Level credit passes in English Language, Mathematics, Physics, Chemistry and Further Mathematics.', 'English Language, Physics, Mathematics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14997, 'lagos', 'education-and-islamic-studies', 1, 'Education and Islamic Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE credit/merit in: Islamic Studies.ii. Very good passes in three JUPEB subject: IRS and any two of Government/History, Literature in English, French, Yoruba/Igbo and Economics. iii. Three \'A\' Level passes in relevant teaching subject areas.', 'Five O/Level credit passes in English Language, Mathematics, Islamic Religious Studies (IRS) and two of Literature-in-English, any Nigerian Language, History/ Government, French/ Arabic, Economics/Commerce, Civic Education/Social Studies.', 'English Language and Islamic Religious Studies (IRS) and any two of Literature-in-English, History/ Government, French/ Arabic, Geography, Mathematics, Yoruba/ Igbo, CRS, Economics/Commerce.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14998, 'lagos', 'english-language', 1, 'English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A\' Level subjects: Literature-in-English and any two of Igbo/Yoruba, CRS, IRS, History, Government, Music, Fine Arts and French.', 'Five O/Level credit passes in English Language, Mathematics, Literature-in-English and any two of French, History/Government, CRS/IRS and any Nigerian Language.', 'English Language, Literature-in-English and any two of CRS/IRS, French, History, Government and any Nigerian Language.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(14999, 'lagos', 'education-and-french', 1, 'Education and French', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE credit/merit: Subject (French and any other two Arts subjects) NFLV Diploma/Modules I-III. ii. Very good passes in three JUPEB subjects: French and any two of Literature in English, CRS, IRS, Igbo/Yoruba, Government/History. iii. Three \'A\' Level passes in relevant teaching subject areas.', 'Five O/Level credit passes in English Language, Mathematics, and any three subjects from Arts, Science and Social Sciences.', 'English Language and any three subjects from Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15000, 'lagos', 'education-and-igbo', 1, 'Education and Igbo', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE credit/merit in Igbo and any two Arts subjects. ii. Very good passes in three JUPEB subjects: Igbo and two of French, Yoruba, Literature-in-English, CRS/IRS, Geography and Government/History and O/Level requirements. Three \'A\' Level passes in relevant teaching subject areas.', 'Five O/Level credit passes in English Language, Mathematics, and any three subjects from Arts, Science and Social Sciences.', 'English Language and any three subjects from Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15001, 'lagos', 'french', 1, 'French', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. Very good passes in JUPEB/A\' Level subjects: French and any two of Igbo/Yoruba, CRS/IRS, History, Government, Literature-in-English, Music and Fine Arts. ii. NCE in French/NFLV, Diploma/Diplôme Supérieur (MODULE III), DALF (France), CEGEP (Canada), Baccalaureate, CAP and BTS.', 'Five O/Level credit passes in English Language, Mathematics and any three Arts or Social Sciences. Civic Education and Computer Studies are also accepted.', 'English Language and any three Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15002, 'lagos', 'education-and-geography', 1, 'Education and Geography', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. Very good passes in three JUPEB subjects: Geography and any two of Economics, Biology, Government/History, CRS/IRS, Igbo/Yoruba. ii. Three \'A\' Level passes in relevant teaching subject areas.', 'Five O/Level credit passes in English, Mathematics, Geography and any two subjects from Science or Social Sciences.', 'English language, Geography and any two subjects from Science or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15003, 'lagos', 'education-and-history', 1, 'Education and History', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE credit/merit in: History, Social Studies and Political Science. ii. Very good passes in three JUPEB subjects: History and any two of CRS/IRS, Literature-in-English, Igbo/Yoruba, Government, French and Geography. iii. Three \'A\' Level passes in relevant teaching subject areas.', 'Five O/Level credit passes in English Language, Mathematics, History/Government and any two subjects from Arts or Social Sciences.', 'English Language and any three subjects from Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15004, 'lagos', 'education-and-physics', 1, 'Education and Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE with credit/merit in Physics and one of Mathematics, Chemistry, and Biology. ii. Very good passes in three JUPEB subjects: Physics, Chemistry and any one of Biology or Mathematics. iii. Three \'A\' Level passes to includes Physics, Mathematics', 'Five O/Level credit passes in English Language, Mathematics, Physics, and any two of Biology, Further Mathematics, Agricultural Science, Integrated Science, Computer Studies/Data Processing.', 'English Language, Physics, Mathematics/Chemistry and one of Biology, Agricultural Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15005, 'lagos', 'industrial-mathematics', 1, 'Industrial Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\'-level subjects: Physics, Mathematics and any one (1) of Chemistry, Biology, Economics and Geography and requires O/level credit pass in Further Mathematics. Does not accept NCE.', 'Five O/Level credit passes in English Language, Mathematics, Further Mathematics, Physics and any one of Economics, Chemistry and Geography.', 'English Language, Mathematics, Physics and any of Chemistry, Economics, Biology and Geography', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15006, 'lagos', 'history-and-strategic-studies', 1, 'History and Strategic Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A\' Level subjects: History and/or Government and any two or one of Igbo/Yoruba, CRS/IRS, Literature-in-English, French, Music and Fine Arts.', 'Five O/Level credit passes in English Language, Mathematics, History/Government and any two of Literature-in-English, CRS/IRS, Civic Education and any Nigerian Language.', 'English Language, History and/or Government and any one or two Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15007, 'lagos', 'chemistry', 1, 'Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\' level subjects Biology, Chemistry and Physics', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Chemistry, Physics and any of Biology or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15008, 'lagos', 'health-education', 1, 'Health Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE credit/merit in Physical Education/Physical & Health Education/Human Kinetics & Health Education. ii. Very good passes in three JUPEB subjects: Biology/Health Science/Physical Education and one other Science subject. iii. Unilag 2-year Diploma in HKE.', 'Five O/Level credit passes in English Language, Mathematics, Biology/Health Science/Physical Education, one Science subject and any other subject.', 'English Language, Biology and any two Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15009, 'lagos', 'human-kinetics', 1, 'Human Kinetics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE credit/merit in Physical Education/Physical & Health Education/Human Kinetics & Health Education.ii. Very good passes in three JUPEB subjects: Biology/Health Science/Physical Education and one other Science subject. iii. Unilag 2-year Diploma in HKE.', 'Five O/Level credit passes in English Language, Mathematics, Biology/Health Science/Physical Education, one Science subject and any other subject.', 'English Language, Biology and any two Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15010, 'lagos', 'industrial-chemistry', 1, 'Industrial Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\' level subjects Biology, Chemistry and Physics.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Chemistry, Physics and any of Biology or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15012, 'lagos', 'geology', 1, 'Geology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following JUPEB/A\' level subjects: Mathematics, Physics and or Chemistry. Candidates must have \'O\' level credit pass in Biology.', 'Five O/Level credit passes in English Language, Mathematics, Physics, Chemistry and Biology or Further Mathematics.', 'English Language, Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15013, 'lagos', 'igbo', 1, 'Igbo', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. Very good passes in three JUPEB/A\' Level subjects in Igbo/Yoruba and any two of History, CRS/IRS, French, Government, Music, Visual Arts and Literature-in-English. ii. NCE (Merit) in two subjects to include a Nigerian Language. iii. LASU Diploma in Communication Arts.', 'Five O/Level credit passes in English Language, Mathematics and any three Arts, Science or Social Sciences. Social Studies and Civic Education are also accepted.', 'English Language and any three Arts, Science or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15014, 'lagos', 'linguistics', 1, 'Linguistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. Very good passes in three JUPEB/A\' Level subjects in Igbo/Yoruba and any two of History, CRS/IRS, French, Government, Music, Visual Arts and Literature-in-English. ii. NCE (Merit) in two subjects to include a Nigerian Language. iii. LASU Diploma in Communication Arts.', 'Five O/Level credit passes in English Language, Mathematics and any three Arts, Science or Social Sciences. Social Studies and Civic Education are also accepted.', 'English Language and any three Arts, Science or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15015, 'lagos', 'islamic-studies', 1, 'Islamic Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Passes at the JUPEB, GCE A/level or its equivalents. One of the A/level Subjects should be Islamic Studies or Arabic. NCE with credit or merit in Islamic Studies or Arabic.', 'Five Credit passes in English Language, Mathematics, Islamic Studies and any other two (2) subjects.', 'English Language, Islamic Studies and any two from Literature in English, History, Government, French, Yoruba, Igbo, Visual Arts, Economics and Commerce.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15016, 'lagos', 'statistics', 1, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\'-level subjects: Physics, Mathematics and any one (1) of Chemistry, Biology, Economics and Geography and requires O/level credit pass in Further Mathematics. Does not accept NCE.', 'Five O/Level credit passes in English Language, Mathematics, Further Mathematics, Physics and any one of Economics, Chemistry and Geography.', 'English Language, Mathematics, Physics and any of Chemistry, Economics, Biology and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15017, 'lagos', 'botany', 1, 'Botany', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\' level subjects: Biology, Chemistry and Physics.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15018, 'lagos', 'russian', 1, 'Russian', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in JUPEB/A\' Level subjects: Any three of French, Igbo/Yoruba, CRS/IRS, History, Government, Literature-in-English, Music and Fine Arts.', 'Five O/Level credit passes in English Language, Mathematics and any three Arts or Social Sciences. Civic Education and Computer Studies are also accepted.', 'English Language and any three Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15020, 'lagos', 'zoology', 1, 'Zoology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following JUPEB/A\'- level subjects: Physics, Chemistry and Biology.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15021, 'lagos', 'technical-education', 1, 'Technical Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE Merit / Credit in Technical drawing / woodwork, Technical drawing Automobile, Technical drawing / Building, Technical drawing/ Electrical- Electronics, Technical drawing / Metal work. ii. Very good passes in three JUPEB subjects: Physics/ Technical Drawing and any other two Science Subjects. iii. Three \'A\' level passes in Building/Woodwork, Electrical/Electronics and Mechanical/Auto Mechanics.', 'Five O/Level credit passes in English Language, Mathematics, Physics/ Technical Drawing and any two of Chemistry, Electrical/ Electronics, Metal/ Automobile works.', 'English Language, Mathematics, Physics and any one of Chemistry, Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15022, 'lagos', 'philosophy', 1, 'Philosophy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A\' Level subjects: Any three of Literature-in-English, Igbo/Yoruba, CRS/IRS, French, History, Economics, Government, Chemistry, Physics, Biology, Geography but at least one Arts subject.', 'Five O/level credit in English Language, Mathematics, one Arts and any two Arts, Social Sciences and Science. Civic Education is also accepted.', 'English Language, one Arts and any two Arts, Social Sciences or Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15023, 'lagos', 'mathematics', 1, 'Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\'-level subjects: Physics, Mathematics and any one (1) of Chemistry, Biology, Economics and Geography and requires O/level credit pass in Further Mathematics.Does not accept NCE.', 'Five O/Level credit passes in English Language, Mathematics, Further Mathematics, Physics and any one of Economics, Chemistry and Geography.', 'English Language, Mathematics, Physics and any of Chemistry, Economics, Biology and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15024, 'lagos', 'geophysics', 1, 'Geophysics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\' level subjects: Physics, Chemistry Mathematics.', 'Five O/Level credit passes in English Language, Mathematics, Physics, Chemistry and Biology or Further Mathematics.', 'English Language, Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15025, 'lagos', 'yoruba', 1, 'Yoruba', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. Very good passes in three JUPEB/A\' Level subjects in Yoruba/Igbo and any two of History, CRS/IRS, French, Government, Music, Visual Arts and Literature in English. ii. NCE (Merit) in two subjects to include a Nigerian Language.', 'Five O/Level credit passes in English Language, Mathematics and any three Arts, Science or Social Sciences. Social Studies and Civic Education are also accepted.', 'English Language and any three Arts, Science or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15026, 'lagos', 'microbiology', 1, 'Microbiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\'-level subjects: Biology, Chemistry and Physics.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15027, 'lagos', 'mass-communication', 1, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A\' Level subjects: Literature-in-English and any two of Economics, Government, History and CRS/IRS.', 'Five \'O\' Level credit passes in English Language, Mathematics, Literature-in-English and any two of Economics, History/Government, Geography, any Nigerian Language, CRS/IRS and Civic Education.', 'English Language, Literature-in-English and any two subjects from Arts or Social Sciences. **Mathematics is accepted.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15028, 'lagos', 'chinese-studies', 1, 'Chinese Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Lagos does not accept Direct Entry.', 'Five O/Level credit passes in English Language, Mathematics and any three Arts, Science or Social Sciences. Social Studies and Civic Education are also accepted.', 'English Language and any three Arts, Science or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15029, 'lagos', 'home-economics-and-education', 1, 'Home Economics and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE in Home Economics, Catering and Hotel Management, Clothing & Textile Management.ii. Very good passes in three JUPEB Subjects: Chemistry, Biology and one other subject from Home Economics, Physics, Food & Nutrition, Home Management and clothing & Textileiii. Three \'A\' Level passes in any two relevant Science subjects of Chemistry and any one of Biology, Botany and Agricultural Science, Physics. iv. ND with Distinction in Hotel Management, Tourism, Catering and Hotel Management, or any other related course.', 'Five O/Level credit passes in English Language, Mathematics, Chemistry Biology/Agricultural Science and any one of Economics, Home Economics, Physics, Food & Nutrition/Home Management, Clothing and Textile, Garment Making/Dyeing & Bleaching/ Catering Craft Practice.', 'English Language, Chemistry, Biology/Agricultural Science and any one of Mathematics, Physics, Food & Nutrition/Home Management, Clothing & Textile.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15030, 'lagos', 'computer-science', 1, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\' level subjects: Physics, Mathematics, Chemistry or Biology. Candidates must have Further Mathematics at \'O\' level. Direct Entry into Computer Science is four (4) years Does not accept NCE/HND', 'Five O/Level credit passes in English Language, Mathematics, Further Mathematics, Physics and Chemistry or Biology.', 'English Language, Mathematics, Physics and any of Chemistry or Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15031, 'lagos', 'teacher-education-science', 1, 'Teacher Education Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant teaching subjects including Literature in English. (ii) NCE credit or merit in two(2)relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language and Literature in English plus three (3) other Arts or Social Science subjects.', 'Literature in English and one (1) Art and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15032, 'lagos', 'education-and-english-language', 1, 'Education and English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE credit/merit in English, Literature-in-English, Mathematics and any two subjects. ii. Very good passes in three JUPEB subjects: Literature-in-English and any two of French, Igbo/Yoruba, History, CRS/IRS, Government, Economics and Arabic. iii. Three \'A\' Level passes in relevant teaching subject areas.', 'Five O/Level credit passes in English Language, Mathematics, Literature-in-English and any two subjects from Arts, Science and Social Sciences.', 'English Language and any three subjects from Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15033, 'lagos', 'political-science', 1, 'Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A\' Level subjects: Government and any two of Literature-in-English, Economics, CRS/IRS and History.', 'Five \'O\' Level credit passes in English Language, Mathematics, Government, Economics/Geography and any one of History, Literature-in-English and CRS/IRS.', 'English Language, Government, Economics/Geography and any one of History, Literature-in-English, CRS/IRS.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15034, 'lagos', 'education-and-christian-religious-studies', 1, 'Education and Christian Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE credit/merit in CRS and any Arts subject. ii. Very good passes in three JUBEP subjects: CRS and any two of Government, History, Literature in English, Geography, Economics, Yoruba, Igbo and French. iii. Three \'A\' Level passes in relevant teaching subject areas.', 'Five O/Level credit passes in English Language, Mathematics, CRS and any two of Literature-in-English, any Nigerian Language, History/Government, French, Economics/Commerce, Geography, Civic Education/Social Studies.', 'English Language, CRS and any two of Literature-in-English, History/Government, French, any Nigerian Language.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15035, 'lagos', 'psychology', 1, 'Psychology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A\' Level subjects: Biology and any two of Economics, Government, Chemistry, Physics and Literature-in-English.', 'Five \'O\' Level credit passes in English Language, Mathematics, Biology and any two subjects from Social Sciences, Arts and Science (including Health Education, Health Science and Integrated Science). UNILAG does not accept Commerce, CRS/IRS and Financial Accounting', 'English Language and any three subjects from Mathematics. Biology, Physics, Chemistry, Economics, Government, Literature-in-English.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15036, 'lagos', 'social-work', 1, 'Social Work', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A\' Level subjects: Any three of Economics, Government, Geography, History and CRS/IRS. University of Lagos Diploma in Social Development and Administration (SDA).', 'Five \'O\' Level credit passes in English Language, Mathematics, and any two of Economics, Government/History, Civic Education and Geography and one of Literature-in-English, CRK/IRK, any Nigerian Language and Biology.', 'English Language, two Social Sciences subjects and one Arts subject. **Mathematics is accepted.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15037, 'lagos', 'industrial-relations-and-personnel-management', 1, 'Industrial Relations and Personnel Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Economics, Accounting, Business Management, Government, Geography and Statistics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics plus any two (2) subjects listed under the Direct Entry column.', 'Mathematics, Economics and one other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15038, 'lagos', 'sociology', 1, 'Sociology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in three JUPEB/A Level subjects: Any three of Economics, Government, Geography, History and CRS/IRS. University of Lagos Diploma in Social Development and Administration (SDA).', 'Five \'O\' Level credit passes in English Language, Mathematics, and any two of Economics, Government/History, Civic Education and Geography and any one of Literature-in-English, CRK/IRK and any Nigerian Language.', 'English Language, two Social Sciences and one Arts subject. **Mathematics is accepted.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15039, 'lagos', 'biology', 1, 'Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Two (2) \'A\' Level passes from Chemistry, Biology, Botany/Zoology. (ii) NCE merit accepted.', 'Five (5) SSC credit passes to include English Language, Biology, Chemistry and Mathematics/Physics.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15040, 'lagos', 'cell-biology-and-genetics', 1, 'Cell Biology and Genetics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\' level subjects Biology, Chemistry and Physics.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15041, 'lagos', 'marine-biology', 1, 'Marine Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Very good passes in the following three (3) JUPEB/A\'- level subjects: Biology, Chemistry and Physics. Do not accept NCE/HND.', 'Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'English Language, Biology, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15044, 'lagos', 'architecture', 1, 'Architecture', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. Very good passes in JUPEB/A\' Level subjects: Mathematics, Physics and Visual Arts. A minimum of lower credit in HND/ND in Architecture with good credit in the assessment of Architectural Portfolio into 200 level.', 'Five O/Level credit passes in English Language, Mathematics, Physics, Fine Arts or Technical Drawing and any one of Economics, Geography, Chemistry, Biology, Painting and Decoration/Building Construction.', 'English Language, Mathematics, Physics and any one of Chemistry, Geography, Economics, Biology, Fine Arts.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15045, 'lagos', 'quantity-surveying', 1, 'Quantity Surveying', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. Three passes in JUPEB/A\' Level subjects: Mathematics, Physics and any one from Economics, Geography, Chemistry. II. OND/HND (Distinction) in Quantity Surveying, Building, Architecture, Civil Engineering, Mechanical Engineering, and Electrical Engineering into 200/300 levels respectively.', 'Five O/Level credit passes in English Language, Mathematics, Physics and any two of Geography, Economics, Technical Drawing and Chemistry.', 'English Language, Mathematics, Physics and any one of Economics, Geography or Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15046, 'lagos', 'surveying-and-geoinformatics', 1, 'Surveying and Geoinformatics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. Very good passes in JUPEB subjects: Physics, Mathematics and Chemistry. II. \'A\' level Cambridge. III. ND (Minimum of Upper Credit) into 200 level. IV. HND (Minimum of Upper Credit) into 300 level. HND Federal School of Surveying Certificate into 300 level at a minimum of Upper Credit.', 'Five O/Level credit passes in English, Mathematics, Further Mathematics, Physics and Chemistry.', 'English Language, Chemistry, Mathematics & Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15047, 'lagos', 'computer-engineering', 1, 'Computer Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. Very good passes in three JUPEB/A\' Level subjects: Physics, Mathematics and Chemistry. II. \'A\' level Cambridge HND/ND (Upper Credit) in related Engineering courses.', 'Five O/Level credit passes in English, Mathematics Further Mathematics, Physics and Chemistry.', 'English Language, Chemistry, Mathematics & Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15048, 'lagos', 'urban-and-regional-planning', 1, 'Urban and Regional Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. Very good passes in JUPEB/A\' Level subjects: Mathematics, Geography and any one of Chemistry, Physics, Biology or Economics. II. HND/ND (Upper credit) requirements in relevant field or related disciple (Architecture, Estate Management) into 300/200 levels.', 'Five O/Level credit passes in English Language, Mathematics, Geography and any two of Physics, Biology, Chemistry, Economics, and Fine Arts/Technical Drawing.', 'English Language, Mathematics, Geography/Economics and any one of Chemistry, physics, Biology, Fine Arts /Technical Drawing.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15049, 'lagos', 'petroleum-and-gas-engineering', 1, 'Petroleum and Gas Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. Very good passes in JUPEB subjects: Physics, Mathematics and Chemistry. II. A \'level Cambridge HND/ND (Upper credit).', 'Five O/Level credit passes in English, Mathematics, Further Mathematics, Physics and Chemistry.', 'English Language, Chemistry, Mathematics and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15050, 'lagos', 'electrical-electronics-engineering', 1, 'Electrical / Electronics Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. Very good passes in three JUPEB/A\' Level subjects: Physics, Mathematics and Chemistry. II. A\' level Cambridge HND/ND (Upper Credit) in related Engineering courses.', 'Five O/Level credit passes in English, Mathematics, Further Mathematics, Physics and Chemistry.', 'English Language, Chemistry, Mathematics & Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(15051, 'lagos', 'estate-management', 1, 'Estate Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'I. Three passes in JUPEB/A\' Level subjects: Mathematics, Economics, Geography and Chemistry.II. ND with minimum of Upper Credit in Estate Management or relevant field into 200 level. III. HND with minimum of Upper Credit in Estate Management or relevant field into 300 level.', 'Five O/Level credit passes in English Language, Mathematics, Economics, and any two of Geography, Physics, Chemistry, Technical Drawing, Agricultural Science, Fine Arts/Building.', 'English Language, Mathematics, Economics and any one of Geography, Biology, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL);
