(16510, 'mkar', 'public-administration', 1, 'Public Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16511, 'mkar', 'banking-and-finance', 1, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2)\'A\' Level passes in Accounting or Economics and one other subject. (ii) NCE merit in relevant subjects. (iii) ND credit. (iv) Foundation International exam such as ICAN, ACCA, ICMA, GPFA.', 'Five (5)SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, one Social Science subject and any other subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16512, 'mkar', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes in Economics and any one of Mathematics, Statistics, Geography, Physics, Chemistry, Agricultural Science, Accounting, Business Management, History and Government.', 'Five (5)SSC credit passes in English Language, Mathematics, Economics and any two (2) of Arts or Social Science subjects.', 'Economics, Mathematics and any of Government, History, Geography, Literature in English, French and Christian Religious Studies/Islamic Studies.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16513, 'mkar', 'education-and-chemistry', 1, 'Education and Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level/NCE passes including Chemistry and one (1) other Science subject.', 'Five (5) SSC credits in Mathematics, Chemistry, English Language and two (2) of Physics, Biology and Agricultural Science.', 'Chemistry and two (2) other subjects chosen from Physics, Biology and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16514, 'mkar', 'biochemistry', 1, 'Biochemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Chemistry, Mathematics, Physics and Biology. NCE/ND/HND in related programmes plus the UTME requirements.', 'Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Physics and Biology.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16515, 'mkar', 'education-and-biology', 1, 'Education and Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NCE/\'A\' Level passes in Biology and one (1) other Science subject.', 'Five (5) SSC credit passes in English Language, Biology, Chemistry, Mathematics and one (1) other subject.', 'Biology and two (2) other subjects from Chemistry, Mathematics and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16516, 'mkar', 'education-and-mathematics', 1, 'Education and Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes/NCE in Mathematics and one (1) Science subject.', 'Five (5) SSC credit passes to include English Language, Mathematics plus one (1) other Science subject.', 'Mathematics and any two (2) of the following Science subjects: Physics, Chemistry and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16517, 'mkar', 'physics', 1, 'Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NCE/Two (2) \'A\' Level passes in Physics and Mathematics or Chemistry.', 'Five (5) SSC credit passes in English Language, Physics, Chemistry, Mathematics and any other Science subject from Further Mathematics and Biology or Agricultural Science.', 'Physics, Mathematics and Chemistry or Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16518, 'mkar', 'industrial-physics', 1, 'Industrial Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Physics and Mathematics.', 'As for Physics', 'As for Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16519, 'mkar', 'education-and-physics', 1, 'Education and Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Physics and Mathematics. (ii) NCE credit/merit in relevant subjects.', 'Five (5) \'O\' Level credits passes to include English Language, Physics, Mathematics and two (2) other Science subjects or NTC/NBC.', 'Physics, Mathematics or Chemistry plus one (1) other subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16520, 'mkar', 'chemistry', 1, 'Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Chemistry and any one (1) of Physics, Mathematics or Biology. (ii) ND/NCE with good grades in relevant \'O\' Level subjects.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology.', 'Chemistry and two (2) of Physics, Biology and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16521, 'mkar', 'industrial-chemistry', 1, 'Industrial Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Chemistry and Mathematics (ii) ND in Science Technology or ND in relevant programmes with the UTME requirements.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Physics and Biology/Agricultural Science.', 'Chemistry, Mathematics and any of Physics/Biology/ Agricultural Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16522, 'mkar', 'statistics', 1, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes to include Mathematics or Statistics. NCE credit in relevant subjects.', 'Five (5) SSC credit passes to include English Language, Mathematics and at least three (3) subjects from Physics, Statistics, Chemistry, Further Mathematics, Economics and Geography.', 'Mathematics and any two (2) of Physics, Chemistry and Economics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(16523, 'mkar', 'botany', 1, 'Botany', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Biology/Botany/Zoology and Chemistry or Physics.', 'Five (5) SSC Credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'Biology, Chemistry and any other Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
