(16946, 'muritadha', 'integrated-science-mathematics-education', 3, 'Integrated Science / Mathematics Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics and any three (3) of the following 1. Biology/Agricultural Science 2. Chemistry 3. Physics and 4. General Science', 'Mathematics and any two (2) of: Biology, Physics and Chemistry.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(16947, 'muritadha', 'arabic-medium', 3, 'Arabic Medium', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'SSC credit passes to include English Language, Mathematics, Arabic, Christian Religious Studies/Islamic Studies and any other subjects.', 'Arabic and two (2) subjects from Arts/Social Science', 3, NULL, 0, NULL, NULL, NULL, NULL),
