(16971, 'nacabspoly', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(16972, 'nacabspoly', 'business-administration-and-management', 2, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
