(17448, 'ndu', 'geology', 1, 'Geology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes from Geology, Chemistry, Mathematics, Physics, Biology and Geography.', 'Five (5) SSC credit passes in English Language, Biology, Chemistry, Mathematics and any other subject.', 'Any three (3) of Chemistry, Physics, Mathematics, Biology and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17449, 'ndu', 'crop-production-technology', 1, 'Crop Production Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and Biology/Agricultural Science/Botany/Zoology or Physics/Mathematics/Economics.', 'Five (5) SSC credit passes to include Chemistry, Biology/Agricultural Science, Mathematics and one Science/Social Science subject and at least \'O\' Level pass in Physics.', 'Chemistry, Biology/Agriculture and Mathematics or Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17450, 'ndu', 'zoology', 1, 'Zoology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes or NCE in Biology, Zoology or Botany and one other Science subject', 'Five (5) SSC credit passes in English Language, Mathematics, Biology and two (2) other Science subject.', 'Biology and any two (2) of Physics, Chemistry and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17451, 'ndu', 'technical-education', 1, 'Technical Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE merit in two (2) relevant Science subjects plus the UTME requirements. (ii) Two \'A\' Level passes in Physics, Mathematics and Chemistry.', 'Five (5) \'O\' Level credit passes in relevant subjects which must include English Language and Mathematics or NTC/NBC.', 'Physics, Mathematics, Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17452, 'ndu', 'philosophy', 1, 'Philosophy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Any two (2) \'A\' Level passes.', 'Five (5) SSC credit passes to include English Language and four (4) other relevant subjects.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17453, 'ndu', 'religious-studies', 1, 'Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level subjects to include Religious Studies (CRS/IRS).', 'Five (5) SSC credit passes to include English Language and CRS/IRS.', 'CRS/IRS and any other two (2) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17454, 'ndu', 'industrial-education-technology', 1, 'Industrial Education Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Physics and Mathematics. (ii) ND lower credit in Civil Engineering, Production/Electrical Engineering. (iii) Final City and Guilds or its equivalent plus National Technical Certificate. (iv) NCE credit in Technical Education plus \'O\' Level credit passes in Physics or Mathematics.', 'Five (5) \'O\' Level credit passes to include Physics or Mathematics.', 'Mathematics, Physics and one (1) other Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17455, 'ndu', 'microbiology', 1, 'Microbiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and any one (1) from Biology, Zoology or Botany.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology and Physics.', 'Biology, Chemistry and either Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17456, 'ndu', 'mass-communication', 1, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Arts or Social Science subjects.', 'Five (5) SSC credit passes in English Language and four (4) other subjects in Arts or Social Sciences.', 'Any three (3) from Arts or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17457, 'ndu', 'education-and-science', 1, 'Education and Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant Science subjects which should include candidates proposed course. (ii) NCE credit/merit in addition to TC II merit or \'O\' Level credit in relevant subjects.', 'Five (5) \'O\' Level credit passes including English Language, Mathematics and two (2) other Science subjects.', 'Three (3) relevant Science or NBC subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17458, 'ndu', 'education-and-english-language', 1, 'Education and English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant teaching subjects including Literature in English. (ii) NCE credit or merit in two(2)relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language and Literature in English plus three (3) other Arts or Social Science subjects.', 'Literature in English and one (1) Art and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17459, 'ndu', 'political-science', 1, 'Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Government or History plus two (2) other Social Science/Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17460, 'ndu', 'education-and-religious-studies', 1, 'Education and Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit in Religious Studies and one (1) other Arts subject.', 'Five (5) \'O\' Level credit passes or TC II merit in five (5) subjects including English Language, Religious Studies and three (3) other Arts subjects.', 'Two (2) Arts subject including Religious studies and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17461, 'ndu', 'sociology-and-anthropology', 1, 'Sociology and Anthropology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Three (3) Social Science or Arts Subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17462, 'ndu', 'mathematics-computer-science', 1, 'Mathematics / Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Mathematics and Physics', 'Five (5) SSC credit passes in English Language , Mathematics and any three (3) of Biology, Chemistry, Physics, Further Maths, and Technical Drawing.', 'Mathematics, Physics and any one (1) of Chemistry, Economics and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17463, 'ndu', 'biology', 1, 'Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Two (2) \'A\' Level passes from Chemistry, Biology, Botany/Zoology. (ii) NCE merit accepted.', 'Five (5) SSC credit passes to include English Language, Biology, Chemistry and Mathematics/Physics.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17464, 'ndu', 'marine-engineering', 1, 'Marine Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes in Physics and Mathematics. (ii) ND/HND upper credit at appropriate levels.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics, English Language and one Science subject .', 'Chemistry, Mathematics and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17465, 'ndu', 'insurance', 1, 'Insurance', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Economics, Accounts, Business Management, Government, Geography or Statistics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics plus any two(2) of Accounting, Business Methods, Commerce, Government, Geography and Statistics.', 'Mathematics, Economics and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17467, 'ndu', 'architecture', 1, 'Architecture', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes chosen from Mathematics or Physics and Chemistry, Geography or Fine Arts. ND/HND upper credits in relevant field.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any of Fine Art, Geography or Wood Work, Biology, Economics, Technical Drawing, Further. Mathematics., Introduction to Building Construction, Bricklaying/Block laying, Concreting, Wall, Floors and Ceiling Finishing, Joinery, Carpentary, Decorative Painting, Lining, Sign and Design, Wall Hanging, Colour Mixing/Matching and Glazing, Ceramics, Graphics Design, Graphic Printing, Basic Electricity.', 'Physics, Mathematics, and any of Chemistry, Geography, Art, Biology and Economics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17468, 'ndu', 'quantity-surveying', 1, 'Quantity Surveying', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes chosen from Mathematics or Physics and Chemistry, Geography or Fine Arts. ND/HND upper credits in relevant field.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any of Fine Art, Geography or Wood Work, Biology, Economics, Technical Drawing, Further. Mathematics., Introduction to Building Construction, Bricklaying/Block laying, Concreting, Wall, Floors and Ceiling Finishing, Joinery, Carpentary, Decorative Painting, Lining, Sign and Design, Wall Hanging, Colour Mixing/Matching and Glazing, Ceramics, Graphics Design, Graphic Printing, Basic Electricity.', 'Physics, Mathematics, and any of Chemistry, Geography, Art, Biology and Economics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17469, 'ndu', 'environmental-management', 1, 'Environmental Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Mathematics or Geography and one of Economics, Physics and Chemistry.', 'Five (5) SSC credit passes to include Geography and any other four (4) relevant subjects plus a pass in English Language.', 'Mathematics, Geography and any one of Economics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL);
