(17479, 'ndu', 'educational-management', 1, 'Educational Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Same as in Educational Psychology, Guidance and Counseling.', 'Same as in Educational Psychology, Guidance and Counseling.', 'Economics, Mathematics and one (1) other Social Science/Arts subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17480, 'ndu', 'guidance-and-counselling', 1, 'Guidance and Counselling', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes or NCE in two (2) subjects plus the UTME requirements.', 'Five (5) \'O\' Level NTC/NBC credit passes or TC II merit including English Language with \'O\' Level pass in Mathematics.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17481, 'ndu', 'agricultural-science-and-education', 1, 'Agricultural Science and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) passes at \'A\' Level in Biology /Zoology /Botany and any other Science subject. (ii) NCE merit in Biology and any other Science subject. (iii) NCE merit in Agriculture (Double Major).', 'Five (5) \'O\' Level credit passes or equivalents in English Language, Chemistry, Biology/Agricultural Science., Mathematics and another relevant subject.', 'Any three (3) subjects from Chemistry, Biology, Agriculture, Physics, Economics, Geography and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17482, 'ndu', 'adult-and-community-education', 1, 'Adult and Community Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes.(ii) NCE merit in two (2) subjects.', 'Five (5) \'O\' Level credit passes including English Language, Mathematics and three (3) of Literature in English, History, French, Yoruba, Igbo, Hausa, Christian Religious Studies, Islamic Studies, Geography/Physic, Economics and Government or TC II with pass in English Language and four (4) other subjects.', 'Government/History, one (1) Social Science subject and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17484, 'ndu', 'education-and-social-studies', 1, 'Education and Social Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE in two (2) relevant subjects. (ii)Two (2) \'A\' Level passes in relevant subjects.', 'Five (5) \'O\' Level credit passes or equivalent to include English Language and Mathematics.', 'Any three (3) Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17485, 'ndu', 'education-and-political-science', 1, 'Education and Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant subjects chosen from Government or History, Economics and Geography/Physics.(ii) NCE merit in Government/History, Economics and Geography/Physics.', 'Five (5) \'O\' Level credit passes or equivalent to include English Language, Government/History and three (3) other subjects.', 'Government or History plus two (2) other Arts or Social Sciences subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17486, 'ndu', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Economics and one (1) other relevant subject.(ii) NCE merit/credit in Economics and one (1) other subject.', 'Five (5) \'O\' Level credit passes to include English Language, Economics and Mathematics.', 'Economics, Mathematics and one (1) other subject from Geography/Physics, History, Government and Literature in English.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17487, 'ndu', 'business-education', 1, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes or NCE merit in two (2) relevant subjects.(ii) NCE merit in Business Education Double Major.', 'Five (5) TC II merit, \'O\' Level or NTC/NBC credit passes including English Language, Mathematics, Economics and two (2) other subjects in the Social Sciences or Arts. For NBC, the other subjects could be from any of the following: Commerce, Office Practice, Principles of Accounts, Secretarial Duties, Typewriting and Shorthand.', 'Mathematics, Economics plus one (1) of Literature in English, History, Government, Geography, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17488, 'ndu', 'business-administration-and-management', 1, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following:Economics/Commerce,Business Methods,Principles of Accounts,Literature in EnglishGeographyOffice PracticeBiology/Agricultural Science,Chemistry,Physics,History/GovernmentTypewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 1, NULL, 0, NULL, NULL, NULL, NULL),
(17536, 'newgate', 'nutrition-and-dietetics', 2, 'Nutrition and Dietetics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Chemistry, Biology/Agricultural Science/Health Science and any three (3) of the following: Food and Nutrition, Mathematics, Economics/Commerce, Physics, English Language, Home Management. \'O\' Level credit passes in English Language and Mathematics are required.', 'Chemistry, Biology and Agricultural Science', 2, NULL, 0, NULL, NULL, NULL, NULL),
(17537, 'newgate', 'community-health', 2, 'Community Health', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Biology/Health Science and any three (3) from the following: Nutrition, Chemistry, Physics, Religious Studies, Geography, Economics, Nigerian Language Plus at least a pass in English Language, Food and Nutrition/Home Management.', 'Mathematics, Physics and Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
