(17539, 'newgate', 'environmental-health-technology', 2, 'Environmental Health Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Biology/Health Science and any three (3) from the following: Nutrition, Chemistry, Physics, Religious Studies, Geography, Economics, Nigerian Language Plus at least a pass in English Language, Food and Nutrition/Home Management.', 'Mathematics, Physics and Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(17543, 'nicturomi', 'architectural-technology', 2, 'Architectural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics, English Language and any two (2) subjects from the following: Biology, Fine Art, Chemistry, History English Language, Geography, Further Mathematics Economics/Commerce, Religious Knowledge, Technical Drawing, Business Method. \'O\' Level pass in Fine Art or Technical Drawing will be an advantage.', 'Mathematics and any two (2) of Physics, Chemistry and Technical Drawing.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(17544, 'nicturomi', 'banking-and-finance', 2, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and any two (2) of Economics, Geography, History, Government, Commerce or Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(17545, 'nicturomi', 'building-technology', 2, 'Building Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following: Economics/Commerce, Technical Drawing/Fine Art, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, And at least a credit pass in English Language is Compulsory. A pass in Art or Technical Drawing will be an advantage.', 'Mathematics, Physics and Chemistry or Fine Arts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(17546, 'nicturomi', 'business-administration-and-management', 2, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(17547, 'nicturomi', 'quantity-surveying', 2, 'Quantity Surveying', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following Economics/Commerce, Technical Drawing/Fine Arts, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, and \'O\' Level credit pass in English Language is Compulsory. \'O\' Level pass in Art or Technical Drawing is required.', 'Any three (3) of Physics, Mathematics, Geography, Economics, Biology/Agricultural Science', 2, NULL, 0, NULL, NULL, NULL, NULL),
(17548, 'nicturomi', 'statistics', 2, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Basic Science and any three (3) of the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics are compulsory.', 'Any of the three (3): 1. Economics/ Commerce 2. History/Government 3. CRS/IS 4. Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
