(18348, 'okeogun', 'horticultural-technology', 2, 'Horticultural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. \'O\' Level credit pass in English Language is required.', 'Mathematics and any two (2) of Chemistry, Physics or Technical Drawing.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18349, 'okeogun', 'insurance', 2, 'Insurance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting and Shorthand', 'Mathematics and any two (2) of Economics, Geography, Commerce or Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18350, 'okeogun', 'local-government-studies', 2, 'Local Government Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand.', 'Government or History and any two (2) of Economics, Commerce, Geography and Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18351, 'okeogun', 'mechanical-engineering-technology', 2, 'Mechanical Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any one (1) subject from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required.', 'Mathematics, Chemistry and Physics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18352, 'okeogun', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18353, 'okeogun', 'agricultural-technology', 2, 'Agricultural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. At least \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science, Chemistry and any other Science subject', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18354, 'okeogun', 'agricultural-engineering-technology', 2, 'Agricultural Engineering / Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, English Language, Physics and any two (2) of the following: Biology/Agricultural Science Chemistry Technical Drawing Basic Electronics/Basic Electricity Auto Mechanics Metal Work Further Mathematics Food and Nutrition Geography', 'Mathematics and Physics/Technical Drawing, Chemistry or any two (2) Science subjects.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18355, 'okeogun', 'agricultural-and-bioenvironmental-engineering-technology', 2, 'Agricultural and Bioenvironmental Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, English Language, Physics and any two (2) of the following: Biology/Agricultural Science Chemistry Technical Drawing Basic Electronics/Basic Electricity Auto Mechanics Metal Work Further Mathematics Food and Nutrition Geography', 'Mathematics and Physics/Technical Drawing, Chemistry or any two (2) Science subjects.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18356, 'okeogun', 'animal-health-and-production-technology', 2, 'Animal Health and Production Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics.', 'Biology/Agricultural Science, Chemistry and any other Science subject', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18357, 'okeogun', 'production-technology', 2, 'Production Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. At least \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science, Chemistry and any other Science subject', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18358, 'okeogun', 'architectural-technology', 2, 'Architectural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics, English Language and any two (2) subjects from the following: Biology, Fine Art, Chemistry, History English Language, Geography, Further Mathematics Economics/Commerce, Religious Knowledge, Technical Drawing, Business Method. \'O\' Level pass in Fine Art or Technical Drawing will be an advantage.', 'Mathematics and any two (2) of Physics, Chemistry and Technical Drawing.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18359, 'okeogun', 'banking-and-finance', 2, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and any two (2) of Economics, Geography, History, Government, Commerce or Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18360, 'okeogun', 'building-technology', 2, 'Building Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following: Economics/Commerce, Technical Drawing/Fine Art, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, And at least a credit pass in English Language is Compulsory. A pass in Art or Technical Drawing will be an advantage.', 'Mathematics, Physics and Chemistry or Fine Arts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
