(18930, 'otefe', 'mass-communication', 2, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language and Mathematics and any three (3) other subjects from: History, Literature in English, Economics/Commerce, Fine Arts, Government, Biology Physics, Chemistry Basic Electricity Geography, Typewriting, Commerce/Principles of Accounting.', 'Any three (3) subjects from Arts/Social Science/Physical Science.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18931, 'otefe', 'mechanical-engineering-technology', 2, 'Mechanical Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any one (1) subject from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required.', 'Mathematics, Chemistry and Physics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18932, 'otefe', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18933, 'otefe', 'banking-and-finance', 2, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and any two (2) of Economics, Geography, History, Government, Commerce or Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18934, 'otefe', 'business-administration-and-management', 2, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(18935, 'otefe', 'science-laboratory-technology', 2, 'Science Laboratory Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and two (2) of Physics, Biology/Agricultural Science/Health Science, Chemistry, and two (2) other subjects from Technical Drawing, Metal or Wood Work, Basic Electricity, Geography, Further Mathematics, and Fine Arts. \'O\' Level credit pass in each of the three (3) Basic Science subjects - Biology, Chemistry, Physics and a \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Mathematics, Biology/Agricultural Science or Physics', 2, NULL, 0, NULL, NULL, NULL, NULL);
