(19518, 'phpoly', 'agricultural-technology', 2, 'Agricultural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. At least \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science, Chemistry and any other Science subject', 2, NULL, 0, NULL, NULL, NULL, NULL),
(19519, 'phpoly', 'banking-and-finance', 2, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and any two (2) of Economics, Geography, History, Government, Commerce or Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(19520, 'phpoly', 'building-technology', 2, 'Building Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following: Economics/Commerce, Technical Drawing/Fine Art, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, And at least a credit pass in English Language is Compulsory. A pass in Art or Technical Drawing will be an advantage.', 'Mathematics, Physics and Chemistry or Fine Arts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(19521, 'phpoly', 'public-administration', 2, 'Public Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in English Language not Literature in English and Mathematics and any three (3) subjects of the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography, Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Government, History and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(19522, 'phpoly', 'science-laboratory-technology', 2, 'Science Laboratory Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and two (2) of Physics, Biology/Agricultural Science/Health Science, Chemistry, and two (2) other subjects from Technical Drawing, Metal or Wood Work, Basic Electricity, Geography, Further Mathematics, and Fine Arts. \'O\' Level credit pass in each of the three (3) Basic Science subjects - Biology, Chemistry, Physics and a \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Mathematics, Biology/Agricultural Science or Physics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(19523, 'phpoly', 'statistics', 2, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Basic Science and any three (3) of the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics are compulsory.', 'Any of the three (3): 1. Economics/ Commerce 2. History/Government 3. CRS/IS 4. Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(19524, 'phpoly', 'urban-and-regional-planning', 2, 'Urban and Regional Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Geography and three (3) other subjects from: English Language, Economics/Commerce, Fine Art/Technical Drawing, Further Mathematics, Chemistry, Physics, Biology/Agricultural Science, History/Government Business Methods/Bookkeeping and Principles of Accounting One of the three (3) subjects must be a basic science subject. At least a credit pass in English Language is compulsory.', 'Geography and two (2) other subjects from course requirement.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(19525, 'phpoly', 'surveying-and-geoinformatics', 2, 'Surveying and Geoinformatics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any other three (3) subjects from the following: Further Mathematics, Chemistry; Technical Drawing/Fine Art, Geography, Economics/Commerce, Biology/Agricultural Science, English Language, Basic Electricity At least \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Chemistry/Agricultural Science, Biology, Economics and Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL);
