(19745, 'plasu', 'sociology', 1, 'Sociology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '-', 'Five (5) SSC credit passes to include English Language, Mathematics, History/Government/Economics one Science subject and any Arts or Social Science subject', 'Government/ History plus two (2) other Social Sciences/Arts subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(19753, 'plspoly', 'foundry-engineering-technology', 2, 'Foundry Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. \'O\' Level pass in English Language is required.', 'Mathematics, Chemistry, Physics or Technical Drawing', 2, NULL, 0, NULL, NULL, NULL, NULL),
(19754, 'plspoly', 'hospitality-management', 2, 'Hospitality Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science and two (2) of Physics, Chemistry, Mathematics and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(19755, 'plspoly', 'library-and-information-science', 2, 'Library and Information Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language and Mathematics and any three (3) other subjects from: History, Literature in English, Economics/Commerce, Fine Arts, Government, Biology Physics, Chemistry Basic Electricity Geography, Typewriting, Commerce/Principles of Accounting.', 'Any three (3) subjects from Arts/Social Science/Physical Science.', 2, NULL, 0, NULL, NULL, NULL, NULL),
