(19930, 'rectem', 'computer-engineering-technology', 2, 'Computer Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering a pass in Biology is required. \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics and Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(19931, 'rectem', 'electrical-electronics-engineering-technology', 2, 'Electrical / Electronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(19932, 'rectem', 'estate-management-and-valuation', 2, 'Estate Management and Valuation', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, English Language, a basic science subject and any two (2) from the following: Geography, Economics/Commerce, Physics, Biology, Chemistry, Technical Drawing, Fine Art, Woodwork, Literature, Metal Work, Principles of Accounts and Book Keeping Government', 'Mathematics and any two (2) of Economics, Arts, Physics, Chemistry, Biology', 2, NULL, 0, NULL, NULL, NULL, NULL),
