(21041, 'taccoed', 'computer-education-english', 3, 'Computer Education / English', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5)SSC credit passes in English Language, Mathematics, Physics, Literature in English and Arts/Science subjects.', 'Mathematics/Physics, Literature in English and any other Arts/Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(21042, 'taccoed', 'computer-education-physics', 3, 'Computer Education / Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics and any other two (2) Science subjects.', 'Mathematics, Physics and any other Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(21043, 'taccoed', 'primary-education-studies', 3, 'Primary Education Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5)SSC credits including English Language.', 'English Language and any other three (3) subjects.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(21044, 'taccoed', 'islamic-studies-political-science', 3, 'Islamic Studies / Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Islamic Studies, Government/History and one (1) Arts/Social Science subject.', 'Islamic Studies, Government/History and any one (1) Arts/Social Science subject..', 3, NULL, 0, NULL, NULL, NULL, NULL),
(21045, 'taccoed', 'islamic-studies-social-studies', 3, 'Islamic Studies / Social Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Islamic Studies and any two (2) of 1. Economics 2. Government/History 3. Geography', 'Islamic Studies, Government/History and any one (1) Social/Arts Subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(21046, 'taccoed', 'mathematics-physics', 3, 'Mathematics / Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics and two (2) other Science subjects.', 'Mathematics, Physics and any other Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(21047, 'taccoed', 'biology-chemistry', 3, 'Biology / Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes, in English Language, Mathematics, Biology, Chemistry and other Science subject.', 'Biology, Chemistry any other Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(21048, 'taccoed', 'biology-mathematics', 3, 'Biology / Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes, in English Language, Mathematics, Biology, and any other two (2) Science subjects.', 'Mathematics, Biology and any other Science subject.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(21053, 'tansian', 'banking-and-finance', 1, 'Banking and Finance', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Accounting, Economics, Management, Mathematics, Geography and Statistics.', 'Five (5) SSC credit passes to include: English Language, Mathematics and any other subjects. For NBC, the other two (2) relevant subjects could be from any of the following; Accounting, Principles of Accounts, Commerce, Office Practice and Economics.', 'Mathematics, Economics, plus any one (1) of Government and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21054, 'tansian', 'accounting', 1, 'Accounting', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21055, 'tansian', 'business-administration', 1, 'Business Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21056, 'tansian', 'public-administration', 1, 'Public Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21057, 'tansian', 'marketing', 1, 'Marketing', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21058, 'tansian', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2)\'A\' Level passes in Economics and any one of Mathematics, Statistics, Geography, Physics, Chemistry, Agricultural Science, Accounting, Business Management, History and Government.', 'Five (5)SSC credit passes in English Language, Mathematics, Economics and any two (2) of Arts or Social Science subjects.', 'Economics, Mathematics and any of Government, History, Geography, Literature in English, French and Christian Religious Studies/Islamic Studies.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21059, 'tansian', 'biochemistry', 1, 'Biochemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from Chemistry, Mathematics, Physics and Biology. NCE/ND/HND in related programmes plus the UTME requirements.', 'Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Physics and Biology.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21060, 'tansian', 'education-and-biology', 1, 'Education and Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NCE/\'A\' Level passes in Biology and one (1) other Science subject.', 'Five (5) SSC credit passes in English Language, Biology, Chemistry, Mathematics and one (1) other subject.', 'Biology and two (2) other subjects from Chemistry, Mathematics and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21061, 'tansian', 'chemistry', 1, 'Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Chemistry and any one (1) of Physics, Mathematics or Biology. (ii) ND/NCE with good grades in relevant \'O\' Level subjects.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology.', 'Chemistry and two (2) of Physics, Biology and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21062, 'tansian', 'industrial-chemistry', 1, 'Industrial Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Chemistry and Mathematics (ii) ND in Science Technology or ND in relevant programmes with the UTME requirements.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Physics and Biology/Agricultural Science.', 'Chemistry, Mathematics and any of Physics/Biology/ Agricultural Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21063, 'tansian', 'philosophy', 1, 'Philosophy', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Any two (2) \'A\' Level passes.', 'Five (5) SSC credit passes to include English Language and four (4) other relevant subjects.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21064, 'tansian', 'religious-studies', 1, 'Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level subjects to include Religious Studies (CRS/IRS).', 'Five (5) SSC credit passes to include English Language and CRS/IRS.', 'CRS/IRS and any other two (2) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21065, 'tansian', 'microbiology', 1, 'Microbiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and any one (1) from Biology, Zoology or Botany.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology and Physics.', 'Biology, Chemistry and either Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21066, 'tansian', 'education-technology', 1, 'Education Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Physics and Mathematics. (ii) ND lower credit in Civil Engineering, Production/Electrical Engineering. (iii) Final City and Guilds or its equivalent plus National Technical Certificate. (iv) NCE credit in Technical Education plus \'O\' Level credit passes in Physics or Mathematics', 'Five (5) \'O\' Level credit passes to include Physics or Mathematics.', 'Mathematics, Physics and one (1) other Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21067, 'tansian', 'mass-communication', 1, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Arts or Social Science subjects.', 'Five (5) SSC credit passes in English Language and four (4) other subjects in Arts or Social Sciences.', 'Any three (3) from Arts or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21068, 'tansian', 'computer-science', 1, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, ') Two (2) \'A\' Level passes in science subjects including Mathematics (ii) NCE merit in Mathematics and one (1) other Science or Social Science subject.', 'Five (5) SSC credit passes to include English Language, Mathematics, Physics plus two (2) other Science subjects.', 'Mathematics, Physics and one (1) of Biology, Chemistry, Agric Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21069, 'tansian', 'education-and-english-and-literary-studies', 1, 'Education and English and Literary Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant teaching subjects including Literature in English. (ii) NCE credit or merit in two(2)relevant subjects.', 'Five (5) \'O\' Level credit passes to include English Language and Literature in English plus three (3) other Arts or Social Science subjects.', 'Literature in English and one (1) Art and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21070, 'tansian', 'political-science', 1, 'Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Government or History plus two (2) other Social Science/Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21071, 'tansian', 'education-and-christian-religious-studies', 1, 'Education and Christian Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit in Religious Studies and one (1) other Arts subject.', 'Five (5) \'O\' Level credit passes or TC II merit in five (5) subjects including English Language, Religious Studies and three (3) other Arts subjects.', 'Two (2) Arts subject including Religious studies and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21072, 'tansian', 'biology', 1, 'Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Two (2) \'A\' Level passes from Chemistry, Biology, Botany/Zoology. (ii) NCE merit accepted.', 'Five (5) SSC credit passes to include English Language, Biology, Chemistry and Mathematics/Physics.', 'Biology, Chemistry and Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21073, 'tansian', 'international-relations', 1, 'International Relations', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Social Science subject from Government/History, Economics, Sociology and Business Management.', 'Five (5) SSC credit passes to include English Language, Government or History and three (3) relevant subjects.', 'Economics, Literature in English and Geography/Government/History.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21074, 'tansian', 'architecture', 1, 'Architecture', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes chosen from Mathematics or Physics and Chemistry, Geography or Fine Arts. ND/HND upper credits in relevant field.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any of Fine Art, Geography or Wood Work, Biology, Economics, Technical Drawing, Further. Mathematics., Introduction to Building Construction, Bricklaying/Block laying, Concreting, Wall, Floors and Ceiling Finishing, Joinery, Carpentary, Decorative Painting, Lining, Sign and Design, Wall Hanging, Colour Mixing/Matching and Glazing, Ceramics, Graphics Design, Graphic Printing, Basic Electricity.', 'Physics, Mathematics, and any of Chemistry, Geography, Art, Biology and Economics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21075, 'tansian', 'educational-management', 1, 'Educational Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Same as in Educational Psychology, Guidance and Counseling.', 'Same as in Educational Psychology, Guidance and Counseling.', 'Economics, Mathematics and one (1) other Social Science/Arts subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21076, 'tansian', 'primary-education', 1, 'Primary Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes chosen from relevant subjects.', 'Five (5) \'O\' Level credit passes including English Language.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21077, 'tansian', 'guidance-and-counselling', 1, 'Guidance and Counselling', NULL, NULL, 1, NULL, NULL, NULL, NULL, '\'A\' Level passes or NCE in two (2) subjects plus the UTME requirements.', 'Five (5) \'O\' Level NTC/NBC credit passes or TC II merit including English Language with \'O\' Level pass in Mathematics.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21078, 'tansian', 'education-and-political-science', 1, 'Education and Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant subjects chosen from Government or History, Economics and Geography/Physics.(ii) NCE merit in Government/History, Economics and Geography/Physics.', 'Five (5) \'O\' Level credit passes or equivalent to include English Language, Government/History and three (3) other subjects.', 'Government or History plus two (2) other Arts or Social Sciences subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21079, 'tansian', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Economics and one (1) other relevant subject.(ii) NCE merit/credit in Economics and one (1) other subject.', 'Five (5) \'O\' Level credit passes to include English Language, Economics and Mathematics.', 'Economics, Mathematics and one (1) other subject from Geography/Physics, History, Government and Literature in English.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21080, 'tansian', 'business-education', 1, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes or NCE merit in two (2) relevant subjects.(ii) NCE merit in Business Education Double Major.', 'Five (5) TC II merit, \'O\' Level or NTC/NBC credit passes including English Language, Mathematics, Economics and two (2) other subjects in the Social Sciences or Arts. For NBC, the other subjects could be from any of the following: Commerce, Office Practice, Principles of Accounts, Secretarial Duties, Typewriting and Shorthand.', 'Mathematics, Economics plus one (1) of Literature in English, History, Government, Geography, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21084, 'tarpoly', 'science-laboratory-technology', 2, 'Science Laboratory Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and two (2) of Physics, Biology/Agricultural Science/Health Science, Chemistry, and two (2) other subjects from Technical Drawing, Metal or Wood Work, Basic Electricity, Geography, Further Mathematics, and Fine Arts. \'O\' Level credit pass in each of the three (3) Basic Science subjects - Biology, Chemistry, Physics and a \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Mathematics, Biology/Agricultural Science or Physics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21085, 'tarpoly', 'office-technology-and-management', 2, 'Office Technology and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language (not Literature in English) and Mathematics and any three (3) of the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English, Geography, Office Practice, Biology/Agricultural Science, Chemistry, Physics, History/Government, Typewriting, Shorthand', 'Any three (3) of: 1. Mathematics 2. Economics 3. Commerce 4. History/Govt. 5. Geography 6. CRS/IS 7. Principles of Accounts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21086, 'tarpoly', 'statistics', 2, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Basic Science and any three (3) of the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics are compulsory.', 'Any of the three (3): 1. Economics/ Commerce 2. History/Government 3. CRS/IS 4. Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21087, 'tarpoly', 'computer-science', 2, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, a basic science and three (3) other subjects chosen from the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics is compulsory.', 'Mathematics and any two (2) of Geography, Physics, Economics or Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21088, 'tarpoly', 'electrical-electronics-engineering-technology', 2, 'Electrical / Electronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21094, 'tasued', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two \'A\' level passes, JUPEB, IJMB,/NCE Merits in Economics and any one of Mathematics, Statistics, Geography, Government, Social Studies, Accounting and Computer Science. Bachelor Degree/HND in Mathematics, Statistics, Physics and Accounting.', 'Five \'O\' level credits at one or two sittings including English Language Mathematics, Economics and any two/three Social Science or the following Science subjects Agricultural Science, Further Mathematics, Physics and Computer science.', 'Economics, Mathematics and any of Government, History, Geography, Commerce, Accounting and Further Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21095, 'tasued', 'secretarial-administration-and-education', 1, 'Secretarial Administration and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. At least two \'A\' level passes /NCE Merit passes from Economics, Accounting & Business Management. ii. OND/HND in Secretarial Administration with minimum of Lower Credit. JUPEB/IJMB.', 'Five \'O\' level credits at one sitting or two sittings in English, Mathematics, Economics and other two subjects either from Social Science or Arts or commercial. (i) For NBC holders, three other subjects could be from any of the following: office practice, Secretarial duties, Principle of Account, Shorthand 80 WPM and Typewriting 35 WPM.', 'Economics and any two other Social Science/Arts subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21096, 'tasued', 'education-and-accounting', 1, 'Education and Accounting', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Business Method and one (1) Social Science subject.', 'Five (5) SSCE credit passes at 1 or 2 sittings including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Mathematics, Economics and any other Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21097, 'tasued', 'vocational-and-technical-education', 1, 'Vocational and Technical Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE merit in Technical Education. (ii) ND in Mechanical/Electrical or Electronics Engineering.', 'Five (5) SSC credit passes in NTC, City and Guilds Part I or WAEC Technical and Federal Craft Training Certificate including English Language, Mathematics, Technical Drawing, Physics, subject of specialization.', 'Subjects of specialization and Mathematics or Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21098, 'tasued', 'education-and-chemistry', 1, 'Education and Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i.) Nigeria Certificate in Education (NCE) from any accredited institution in Nigeria with credits in teaching subjects including Chemistry. ii.) G.C.E. A\' Level with at least credits in two (2) science subjects which one must be Chemistry. iii) OND/HND with Lower Credit in the following areas: Chemistry, Science Laboratory Technology, Medical Laboratory Technology, Pharmaceutical Technology from accredited institutions in Nigeria. v. JUPEB/ IJMB.', '1) A minimum of five (5) credits at one sitting in five (5) major O\' level Science subjects: English, Mathematics, Chemistry, Physics and Biology. 2.) A minimum of five (5) credits at two sittings in five (5) major O\' level Science subjects: English, Mathematics, Chemistry, Physics, Biology and Geography/Agricultural Science.', 'Chemistry, Biology/Agric Physics, Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21099, 'tasued', 'computer-science-education', 1, 'Computer Science /  Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes, JUPEB, IJMB. NCE Merit in Chemistry, Mathematics, Physics and Computer Science. i. OND (Lower Credit) HND (Lower Credit) in Computer Engineering, Information Science or information Technology', 'Five \'O\' level credits at one sitting or six \'O\' level credits at two sittings to include English Language, Mathematics, Physics, and any two/three other subjects.', 'Mathematics, Physics, Chemistry and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21100, 'tasued', 'geography-and-environmental-management', 1, 'Geography and Environmental Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '1. N.C.E. with distinction or Credit or Merit in Geography and any other Social Science or Science subject. 2. Candidate must have passed at least two Social Science subjects (H.S.C or G.C.E., JUPEB, IJMB.) \'A\' level in either Geography or Economics, OND in Town Planning, Estate Management, Surveying, Diploma in Transport Studies or Diploma in G.I.S or related subjects acceptable to the Department, Cambridge Advanced level with at least two (2) papers related to the course of study.', 'Five (5) \'O\' level credits at one or two sittings including English Language, Mathematics and at least any other three Social Science or Science or Commercial subjects (with or without Geography)', 'English Language and any three subjects from Science, Social Science and Commercial', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21101, 'tasued', 'education-and-integrated-science', 1, 'Education and Integrated Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE Integrated Science (ii) NCE Science Education (iii) \'A\' Level passes in two (2)Science subjects', 'Five (5) SSC credit passes including Biology, Chemistry, English Language and Mathematics', 'Any three (3) of Mathematics, Chemistry, Physics, Biology and Agricultural Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21102, 'tasued', 'education-and-yoruba', 1, 'Education and Yoruba', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes, JUPEB, IJMB./NCE Merit pass in Yoruba and any other subject in Arts and Social Science subjects or the equivalent of \'A\' level Diploma certificate in Yoruba.', 'Five \'O\' level credits at one or two sittings to include English Language and two other Arts or social science subjects.', 'Any three subjects from Arts/Social Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21103, 'tasued', 'education-and-biology', 1, 'Education and Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. At least two \'A\' level passes, JUPEB, IJMB. /NCE Science subjects to include Biology. ii. OND/HND with Lower Credit in the following specialization: a) Science Laboratory Technology-option in Biology, Chemistry & Microbiology. b) Anatomy, Physiology and Biochemistry c) Food Technology', 'Five \'O\' level credits at one sitting or six \'O\' level credits at two sittings to include English Language, Mathematics, Chemistry, Biology Physics or Geography.', 'Biology, Chemistry and one other Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21104, 'tasued', 'fine-and-applied-arts', 1, 'Fine and Applied Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE with at least a Merit pass in Fine and Applied Arts (Double Major), Music or related discipline will be an added advantage. ii. At least \'A\' level passes in Fine Art and Music and any other subject will be an added advantage. iii. OND/HND (Lower Credit). JUPEB/ IJMB', 'G.C.E. \'O\' level or NTC, NBC Credit/Merit in five/six subjects at one/ two sittings including English Language', 'Any three subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21105, 'tasued', 'education-and-mathematics', 1, 'Education and Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two \'A\' level subjects including Mathematics and any Science sub-ject. Or NCE with at least merit in Mathematics, and one other approved Science or Social Science subject. Mathematics/Statistics, Statistics, Mechanical, Computer and Electrical Engineering. *OND/HND Lower Credit in Mathematics/Statistics, Statistics, Mechanical, Computer and Electrical Engineering. JUPEB / IJMB.', 'Five \'O\' level credits at one or two sittings to include English Language, Mathematics, and at least two subjects from Biology, Physics, Statistics, Chemistry, Further Maths, Economics & Geography', 'Mathematics, and two other subjects from Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21106, 'tasued', 'physics', 1, 'Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two \'A\' level passes in Physics and one of Mathematics, Chemistry and Biology. NCE merit in two core subjects including Physics and one of Mathematics, Chemistry and Biology. *OND/HND with Lower Credit in Physics or Physics with Electronics or Electronics. JUPEB/ IJMB.', 'Five \'O\' level credits at one or two sittings to include English Language, Mathematics, Physics and any other 2/3 subjects from Biology, Chemistry, Geography, Additional (Further) Mathematics, Agricultural Science and Computer Science.', 'Physics, Mathematics / Chemistry plus one (1) other subject from Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21107, 'tasued', 'islamic-studies-education', 1, 'Islamic Studies / Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes, JUPEB, IJMB,/NCE Merit in ISS and other Arts or Social Science subjects.', 'Five \'O\' level credits at one or two sittings to include English Language and other subjects in Arts/ Social Sciences.', 'Any three subjects from Arts/Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21108, 'tasued', 'english-language', 1, 'English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes to include Literature in English. ii) NCE with a minimum of merit pass in English & other related subject. iii) OND/HND with minimum of Lower Credit in Mass Communication. v. JUPEB/ IJMB.', 'Five \'O\' level credits at one or two sittings to include Literature in English, English Language and at least one other Arts subject.', 'Literature in English, one arts subject and one other subject in Arts/Social Science.', 1, NULL, 0, NULL, NULL, NULL, NULL);
INSERT INTO `institution_program` (`id`, `institution_id`, `program_id`, `level_id`, `name`, `description`, `remarks`, `program_mode_id`, `duration`, `tuition_fee`, `utme_cutoff`, `requirements`, `direct_entry`, `o_level`, `utme_subjects`, `accreditation_body_id`, `accreditation_status_id`, `is_distinguished`, `accreditation_grant_date`, `accreditation_expiry_date`, `created_at`, `updated_at`) VALUES
(21109, 'tasued', 'education-and-french', 1, 'Education and French', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes, JUPEB, IJMB./NCE merit in French and any other subject in Arts and Social Science subjects or the equivalent of \'A\' level Diploma certificate in French.', 'Five (5) \'O\' level credits at one or two sittings to include English Language. ii.at least a fairly good pass (Assezbien) in French BACCALAUREAT for francophone applicants in lieu of Nigeria SSCE', 'Any three subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21110, 'tasued', 'french', 1, 'French', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes, JUPEB, IJMB./NCE merit in French and any other subject in Arts and Social Science subjects or the equivalent of \'A\' level Diploma certificate in French.', 'Five (5) \'O\' level credits at one or two sittings to include English Language. ii.at least a fairly good pass (Assezbien) in French BACCALAUREAT for francophone applicants in lieu of Nigeria SSCE', 'Any three subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21111, 'tasued', 'education-and-geography', 1, 'Education and Geography', NULL, NULL, 1, NULL, NULL, NULL, NULL, '1. N.C.E. with distinction or Credit or Merit in Geography and any other Social Science or Science subject. 2. Candidate must have passed at least two Social Science subjects (H.S.C or G.C.E., JUPEB, IJMB.) \'A\' level in either Geography or Economics, OND in Town Planning, Estate Management, Surveying, Diploma in Transport Studies or Diploma in G.I.S or related subjects acceptable to the Department, Cambridge Advanced level with at least two (2) papers related to the course of study.', 'Five (5) \'O\' level credits at one or two sittings including English Language, Mathematics and at least any other three Social Science or Science or Commercial subjects (with or without Geography)', 'English Language and any three subjects from Science, Social Science and Commercial', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21112, 'tasued', 'agricultural-production-and-management-science-and-education', 1, 'Agricultural Production and Management Science and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. At least two \'A\' level passes, JUPEB, IJMB./NCE Merit passes in History, Political Science, Social Studies and Christian/ Islamic Religious Studies and any other related subjects. ii) OND/HND with Lower Credit in Mass Communication/ Journalism, Public Administration, Public Relations, Business Studies and Business Administration. iii University Diploma in Tourism (Upper Credit). i. University Diploma with Upper Credit in Mass Communication', 'Five (5) \'O\' level credits at one sitting or six (6)\'O\' level credits at two sittings to include English Language, History/ Government (where a candidate posses the two (2) they are to be counted separately) and any other subject from Arts, Social Sciences and Civic Education.', 'History/Government or both and other related subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21113, 'tasued', 'physics-education', 1, 'Physics / Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two \'A\' level passes in Physics and one of Mathematics, Chemistry and Biology. NCE merit in two core subjects including Physics and one of Mathematics, Chemistry and Biology. *OND/HND with Lower Credit in Physics or Physics with Electronics or Electronics. JUPEB/ IJMB.', 'Five \'O\' level credits at one or two sittings to include English Language, Mathematics, Physics and any other 2/3 subjects from Biology, Chemistry, Geography, Additional (Further) Mathematics, Agricultural Science and Computer Science.', 'Physics, Mathematics / Chemistry plus one (1) other subject from Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21114, 'tasued', 'chemistry', 1, 'Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i.) Nigeria Certificate in Education (NCE) from any accredited institution in Nigeria with credits in teaching subjects including Chemistry. ii.) G.C.E. A\' Level with at least credits in two (2) science subjects which one must be Chemistry. iii) OND/HND with Lower Credit in the following areas: Chemistry, Science Laboratory Technology, Medical Laboratory Technology, Pharmaceutical Technology from accredited institutions in Nigeria. v. JUPEB/ IJMB.', '1) A minimum of five (5) credits at one sitting in five (5) major O\' level Science subjects: English, Mathematics, Chemistry, Physics and Biology. 2.) A minimum of five (5) credits at two sittings in five (5) major O\' level Science subjects: English, Mathematics, Chemistry, Physics, Biology and Geography/Agricultural Science.', 'Chemistry, Biology/Agric Physics, Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21115, 'tasued', 'health-education', 1, 'Health Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE with at least Merit in related subjects – Physical Education, Health Education, Biology, plus UTME requirement. ii. Registered Nurse plus UTME requirement i. Two \'A\' level passes in Physical Education, Health Education, Biology, plus UTME requirement iv. OND/HND with a minimum of Lower Credit plus UTME requirement. Apart from Diploma in Education (Upper Credit), holder of Upper Diploma in Health related disciplines who fulfils UTME requirements be considered for Direct Entry admission. v. JUPEB, IJMB.', 'Five \'O\' level credits at one or two sittings to include English Language and at least one Science subject and Mathematics.', 'Any three relevant subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21116, 'tasued', 'history-and-diplomatic-studies', 1, 'History and Diplomatic Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. At least two \'A\' level passes, JUPEB, IJMB./NCE Merit passes in History, Political Science, Social Studies and Christian/ Islamic Religious Studies and any other related subjects. ii) OND/HND with Lower Credit in Mass Communication/ Journalism, Public Administration, Public Relations, Business Studies and Business Administration. iii University Diploma in Tourism (Upper Credit). i. University Diploma with Upper Credit in Mass Communication', 'Five (5) \'O\' level credits at one or two sittings to include English Language, History/ Government (where a candidate posses the two (2) they are to be counted separately) and any other subject from Arts, Social Sciences and Civic Education.', 'History/Government or both and other related subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21117, 'tasued', 'human-kinetics', 1, 'Human Kinetics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE with at least Merit in related subjects – Physical Education, Health Education, Biology, plus UTME requirement. ii. Registered Nurse plus UTME requirement i. Two \'A\' level passes in Physical Education, Health Education, Biology, plus UTME requirement iv. OND/HND with a minimum of Lower Credit plus UTME requirement. Apart from Diploma in Education (Upper Credit), holder of Upper Diploma in Health related disciplines who fulfils UTME requirements be considered for Direct Entry admission. v. JUPEB, IJMB.', 'Five \'O\' level credits at one or two sittings to include English Language and at least one Science subject and Mathematics.', 'Any three relevant subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21118, 'tasued', 'islamic-studies', 1, 'Islamic Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes, JUPEB, IJMB,/NCE Merit in ISS and other Arts or Social Science subjects.', 'Five \'O\' level credits at one or two sittings to include English Language and other subjects in Arts/ Social Sciences.', 'Any three subjects from Arts/Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21119, 'tasued', 'technical-education', 1, 'Technical Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE with at least merit in two relevant Technical Education courses/subjects plus UTME requirements. ii.NCE Technical Education iii. OND/HND with at least Lower Credit in Civil Engineering, Mechanical/ Production Engineering, Electrical/Electronics Engineering and Building/Wood Technology and any other related Engineering discipline. iv. City and Guilds Final or Engineering Technicians Part II Certificate v. JUPEB/ IJMB', 'i. NCE with at least merit in two relevant Technical Education courses/subjects plus UTME requirements. ii.NCE Technical Education iii. OND/HND with at least Lower Credit in Civil Engineering, Mechanical/ Production Engineering, Electrical/Electronics Engineering and Building/Wood Technology and any other related Engineering discipline. iv. City and Guilds Final or Engineering Technicians Part II Certificate v. JUPEB/ IJMB', 'English language, Mathematics or Physics and any two from Science or Technical or Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21120, 'tasued', 'mathematics', 1, 'Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two \'A\' level subjects including Mathematics and any Science sub-ject. Or NCE with at least merit in Mathematics, and one other approved Science or Social Science subject. Mathematics/Statistics, Statistics, Mechanical, Computer and Electrical Engineering. *OND/HND Lower Credit in Mathematics/Statistics, Statistics, Mechanical, Computer and Electrical Engineering. JUPEB / IJMB.', 'Five \'O\' level credits at one or two sittings to include English Language, Mathematics, and at least two subjects from Biology, Physics, Statistics, Chemistry, Further Maths, Economics & Geography', 'Mathematics, and two other subjects from Science', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21121, 'tasued', 'educational-technology', 1, 'Educational Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i)At least two \'A\' level passes, JUPEB, IJMB,/NCE Merit in relevant teaching subjects. ii) OND/HND with minimum of Lower Credit', 'Five \'O\' level credits at one sitting or six \'O\' level credits at two sittings to include English Language, Mathematics and other subjects from Arts, Social Science or science.', 'Subjects of specialization and one each from Arts and Social Sciences or Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21122, 'tasued', 'educational-management', 1, 'Educational Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) NCE merit in Home Economics (ii) \'A\' Level passes in two (2) of Chemistry or any Biology, Botany and Agricultural Science. (iii) ND/HND credit in Home Economics or Food Science or Hotel and Catering Management or any other related programme.', 'Five (5) \'O\' Level NTC/NBC credit passes or TC II merit including English Language, Mathematics, Home Economics, Biology and Chemistry.', 'Chemistry, Biology or Agricultural Science and one (1) other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21123, 'tasued', 'home-economics-and-hotel-management-and-education', 1, 'Home Economics and Hotel Management and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE in Home Economics with a minimum of Merit Pass. ii. At least two (2) \'A\' level passes in two (2) of Chemistry, Biology and Agric Science. iii. OND/HND with minimum of Lower Credit in Home Economics or Food Science or Hotel and Catering Management and any other related courses. iv. NABTEB (NBC/NTC) certificate in Food and Nutrition and Home Management is acceptable. v. JUPEB/ IJMB.', 'Five GCE \'O\' level or NT/NBC credits at one or two sittings including English Language, Mathematics and any other subject (s) from the following: Food & Nutrition, Home Management, Clothing & Textile, Agric, Science, Biology, Economics, Health Education, Physics and Chemistry.', 'Chemistry and any two (2) Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21124, 'tasued', 'computer-science', 1, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes, JUPEB, IJMB. NCE Merit in Chemistry, Mathematics, Physics and Computer Science. i. OND (Lower Credit) HND (Lower Credit) in Computer Engineering, Information Science or information Technology', 'Five \'O\' level credits at one or two sittings to include English Language, Mathematics, Physics, and any two/three other subjects.', 'Mathematics, Physics and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21125, 'tasued', 'teacher-education-science', 1, 'Teacher Education Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant teaching subjects including Literature in English. (ii) NCE credit or merit in two(2)relevant subjects.', 'Five (5) \'O\' Level credit passes at one or two sittings to include English Language and Literature in English plus three (3) other Arts or Social Science subjects.', 'Literature in English and one (1) Art and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21126, 'tasued', 'education-and-english-language', 1, 'Education and English Language', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes to include Literature in English. ii) NCE with a minimum of merit pass in English & other related subject. iii) OND/HND with minimum of Lower Credit in Mass Communication. v. JUPEB/ IJMB.', 'Five \'O\' level credits at one or two sittings to include Literature in English, English Language and at least one other Arts subject.', 'Literature in English, one arts subject and one other subject in Arts/Social Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21127, 'tasued', 'political-science', 1, 'Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Three \'A\' level passes,NCE Credit/Merit to include Government or History. *OND/HND with Lower Credit in Public Administration or Local Government. JUPEB/ IJMB', 'Five \'O\' level credits at one or two sittings in English, Mathematics, Government or History or Civic Education and other related subjects.', 'Government or History, plus any other Social Science/Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21128, 'tasued', 'fine-arts-education', 1, 'Fine Arts / Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE with at least a Merit pass in Fine and Applied Arts (Double Major), Music or related discipline will be an added advantage. ii. At least \'A\' level passes in Fine Art and Music and any other subject will be an added advantage. iii. OND/HND (Lower Credit). JUPEB/ IJMB', 'G.C.E. \'O\' level or NTC, NBC Credit/Merit in five subjects at one or two sittings including English Language', 'Any three subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21129, 'tasued', 'education-and-christian-religious-studies', 1, 'Education and Christian Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes, JUPEB, IJMB,l/ NCE Merit passes to include CRS and one other subject in Arts/ Social Sciences', 'Five \'O\' level credits at one or two sittings to include English Language and other subjects in Arts or Social Sciences', 'Any three subjects in Arts or Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21130, 'tasued', 'biology', 1, 'Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. At least two \'A\' level passes, JUPEB, IJMB. /NCE Science subjects to include Biology. ii. OND/HND with Lower Credit in the following specialization: a) Science Laboratory Technology-option in Biology, Chemistry & Microbiology. b) Anatomy, Physiology and Biochemistry c) Food Technology', 'Five \'O\' level credits at one or two sittings to include English Language, Mathematics, Chemistry, Biology Physics or Geography.', 'Biology, Chemistry and one other Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21132, 'tasued', 'library-and-information-science', 1, 'Library and Information Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) Diploma in Library and Information Science, Librarianship from recognized Universities. ii) At least two \"A\" level passes, JUPEB, IJMB,/NCE (merit) HND with Merit in Library and Information Science, Computer Science, Information Technology and other related areas.', 'Five \'O\' level credits at one or two sittings to include English Language, Mathematics and three other relevant Arts/ Science/Social Science subjects', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21133, 'tasued', 'early-childhood-education', 1, 'Early Childhood Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two \'A\' level passes, JUPEB, IJMB,/NCE Merit in Primary Education Studies plus one approved teaching subject', 'Five \'O\' level credits at one or two sittings to include English Language, Mathematics and other Subjects from Arts, Social Sciences or Sciences..', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21134, 'tasued', 'counselling-psychology', 1, 'Counselling Psychology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Nigeria Certificate in Education (NCE) with at least Merit in a core subject, JUPEB, IJMB,GCE \'A\' level with at least two (2) passes, OND/HND (for some courses) in relevant areas with at least Lower Credit, Cambridge (A level) certificate, Academic Diploma from recognized Universities (for some courses) (in relevant areas) are required in addition to one (1) for Direct Entry.', 'Five \'O\' level credits at one or two sittings to include English Language and other Subjects.', 'Any three (3) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21135, 'tasued', 'agricultural-science-and-education', 1, 'Agricultural Science and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) At least two \'A\' level passes, JUPEB, IJMB in Chemistry and one from Biology, Botany, Agric. Science, Economics, and Geology/Mathematics (Pure and Applied).ii) NCE Merit in Agricultural Science.iii) OND/HND with at least Lower Credit in Agriculture or Animal Health from recognized Polytechnic or College of Agriculture.', 'Five \'O\' level credits at one or two(2) sittings to include English Language, Chemistry, Biology, Agric. Science, Mathematics, and any one of Geography, Physics, Economics, Animal Nutrition, Animal Husbandry and Fishery.', 'Any three (3) Chemistry, Biology, Agricultural Science, Physics, Geography, Economics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21136, 'tasued', 'adult-education', 1, 'Adult Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i) At least two \'A\' level passes, JUPEB, IJMB,/NCE Merit ii)OND/HND with Lower Credit iii) Diploma in Adult Education, Social Work, Social Development from recognized institution with at least Lower Credit', 'Five \'O\' level credits at one or two sittings to include English Language, and other Subjects from Arts, Social Sciences or Sciences.', 'Any three subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21137, 'tasued', 'education-and-social-studies', 1, 'Education and Social Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two \'A\' level passes, JUPEB, IJMB, NCE (Merit) in Economics, Government/Political Science, Religious Studies, History, Geography and Social Studies. (ii) National Diploma (OND) (Lower Credit) relevant and recognized University Diploma (Upper Credit). TASUED Degree Foundation may be accepted. Bachelor Degree holders in History, Geography, Economics, Political Science, Public Administration, Business Administration, international Relations, Mass Communication and any other related discipline. (iii) OND/HND with Lower Credit in Public Administration, local Government Administration', 'Five (5) \'O\' level credits at one or two sittings to include English, Mathematics and Social Science/Arts/Commercial Subject', 'Any Social Science/Arts/Commercial and any other subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21138, 'tasued', 'education-and-political-science', 1, 'Education and Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Three \'A\' level passes,NCE Credit/Merit to include Government or History. *OND/HND with Lower Credit in Public Administration or Local Government. JUPEB/ IJMB', 'Five \'O\' level credits at one or two sittings in English, Mathematics, Government or History or Civic Education and other related subjects.', 'Government or History, plus any other Social Science/Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21139, 'tasued', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two \'A\' level passes, JUPEB, IJMB,/NCE Merits in Economics and any one of Mathematics, Statistics, Geography, Government, Social Studies, Accounting and Computer Science. Bachelor Degree/HND in Mathematics, Statistics, Physics and Accounting.', 'Five \'O\' level credits at one or two sittings including English Language Mathematics, Economics and any two/three Social Science or the following Science subjects Agricultural Science, Further Mathematics, Physics and Computer science.', 'Economics, Mathematics and any of Government, History, Geography, Commerce, Accounting and Further Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21140, 'tasued', 'education-and-sociology', 1, 'Education and Sociology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes/NCE merit/credit in Economics, Government/Political Science, Religious Studies, History, Geography/ and Social Studies', 'Five (5) \'O\' Level credit passes at one (1) or two (2) sittings to include English Language, Mathematics, two (2) Arts subjects and any other from Social Science', 'Two (2) Arts subjects and any other.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21141, 'tasued', 'business-education', 1, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'i. NCE with at least merit pass in teaching subject. ii. OND/HND with minimum of Lower Credit in Business Education, Commerce, Accounting and any other related discipline. iii. JUPEB/ IJMB.', 'Five \'O\' level credits at one or two sittings in English, Mathematics and any other three subjects in Social Science or Arts which must include Economics. ii. NTC/NBC certificate.', 'Mathematics, Economics and other Social Science/Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21142, 'tasued', 'transport-planning-and-management-and-education', 1, 'Transport Planning and Management and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '1. N.C.E. with distinction, credit or merit in either Geography or any of the Social Sciences or Science subjects. 2. Candidates must have passed at least two Social Science subjects, in the H.S.C. or G.C.E, JUPEB, IJMB, \'A\' level or OND in Town Planning, Estate Management, Surveying, Diploma in Transport Studies or Diploma in G. I. S. or related subjects acceptable to the Department, Cambridge Advanced level with at least two papers related to the course of study.', 'Five (5) \'O\' level credits at one or two sittings including English Language, Mathematics, and at least any other two Social Science, Science or Commercial subjects.', 'English Language and three (3) subjects from Science, Social Science and Commercial', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21157, 'techuni', 'agricultural-engineering', 1, 'Agricultural Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'a. \'A\' Level passes or equivalent in Physics and Mathematics.b. JUPEB, IJMB', 'a. Five (5) O/L credit passes in English Language, Mathematics, Physics, Chemistry and any from Introduction to Agricultural Science, Materials and Workshop Process and Machining, Tractor Layout Power Unit Under Carriage and Auto Electricity; Transmission System; Implement and Machine; Principles of Crop Husbandry and Land Use, Materials and Workshop Processes; Construction and Maintenance of Agricultural Machines; general Metal Work; General Wood Work and Building/Engineering Drawing.b. NABTEB', 'Mathematics, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21158, 'techuni', 'biomedical-engineering', 1, 'Biomedical Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'a. Two (2) \'A\' Level passes in Chemistry and any one of Physics, Biology/ Zoology/Botany and Mathematics.b. JUPEB, IJMB', 'a. Five (5) O/L credit passes in English Language, Mathematics, Physics, Chemistry and Biology.b. NABTEB', 'Physics, Chemistry and Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21159, 'techuni', 'physics-with-electronics', 1, 'Physics with Electronics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'a. NCE/Two (2) \'A\' Level passes in Physics and Mathematics or Chemistry.b.ND in Science Technology or ND in relevant programmes.c. JUPEB and IJMB', 'a. Five (5) SSC credit passes in English Language, Physics, Chemistry, Mathematics and any other Science subject from Further Mathematics and Biology or Agricultural Science.b. NABTEB', 'Physics, Mathematics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21160, 'techuni', 'industrial-chemistry', 1, 'Industrial Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Chemistry and Mathematics (ii) ND in Science Technology or ND in relevant programmes with the UTME requirements.(iii) NCE credit in relevant subjects(vi) JUPEB, IJMB', 'a.Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Physics and Biology/Agricultural Science.b. NABTEB', 'Chemistry, Mathematics and any of Physics/Biology/ Agricultural Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21161, 'techuni', 'statistics', 1, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'a. Two (2) \'A\' Level passes to include Mathematics or Statistics. b. NCE credit in relevant subjects.c. ND (Upper Credit) from a reputable Polytechnic or equivalent d. JUPEB AND IJMB', 'a. Five (5) SSC credit passes to include English Language, Mathematics and at least three (3) subjects from Physics, Statistics, Chemistry, Further Mathematics, Economics and Geography.b. NABTEB', 'Mathematics and any two (2) of Physics, Chemistry, Economics or Geography', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21162, 'techuni', 'mathematics', 1, 'Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'a. Two (2) \'A\' Level passes in Mathematics and any other science subject.b. NCE merit in Mathematics and one (1) of Physics, Chemistry or Economicsc. JUPEB and IJMB', 'a. Five (5) SSC credit passes including English Language, Mathematics and Physics or Chemistry.b. NABTEB', 'Mathematics and any two (2) of Physics, Chemistry and Economics or Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21163, 'techuni', 'microbiology', 1, 'Microbiology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'a.Two (2) \'A\' Level passes in Chemistry and any one (1) from Biology, Zoology or Botany.b. JUPEB and IJMB', 'a. Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology and Physics.b. NABTEB', 'Biology, Chemistry and either Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21164, 'techuni', 'computer-science', 1, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'a. Two (2) \'A\' Level passes in science subjects including Mathematics b. NCE merit in Mathematics and one (1) other Science or Social Science subject.c. ND (Upper Credit) from a reputable Polytechnic or equivalentd. JUPEB and IJMB', 'a. Five (5) SSC credit passes to include English Language, Mathematics, Physics plus two (2) other Science subjects.b. NABTEB', 'Mathematics, Physics and one (1) of Biology, Chemistry, Agric Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21165, 'techuni', 'software-engineering', 1, 'Software Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'a. Two (2) \'A\' Level passes in science subjects including Mathematics b. NCE merit in Mathematics and one (1) other Science or Social Science subject.c. ND (Upper Credit) from a reputable Polytechnic or equivalentd. JUPEB and IJMB', 'a. Five (5) SSC credit passes to include English Language, Mathematics, Physics plus two (2) other Science subjects.b. NABTEB', 'Mathematics, Physics and one (1) of Biology, Chemistry, Agric Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21166, 'techuni', 'cyber-security-science', 1, 'Cyber Security Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'a. Two (2) \'A\' Level passes to include Mathematics or Statistics.b. NCE credit in relevant subjects.c. ND (Upper Credit) from a reputable Polytechnic or equivalent d. JUPEB AND IJMB', 'a. Five (5) SSC credit passes to include English Language, Mathematics, Physics plus two (2) other Science subjects.b. NABTEB', 'Mathematics, Physics and one (1) of Biology, Chemistry, Agric Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21167, 'techuni', 'food-science-and-technology', 1, 'Food Science and Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes Physics Chemistry, and Mathematics. (ii) ND/HND upper credit in relevant programmes.', 'a. Five (5) O/L credit passes to include Physics, Chemistry, Mathematics, English Language and any other Science subject.b. NABTEB', 'Mathematics, Chemistry and Physics or Biology.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21168, 'techuni', 'petroleum-engineering', 1, 'Petroleum Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '1. \'A\' Level passes to include Physics, Chemistry and Mathematics.2. JUPEB, IJMB', 'a. Five (5) O/L credits to include Physics, Chemistry, Mathematics, English Language and any one Science subject.b. NABTEB', 'Chemistry, Mathematics and Physics', 1, NULL, 0, NULL, NULL, NULL, NULL),
