(21346, 'tsuj', 'political-science-and-international-relations', 1, 'Political Science and International Relations', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Government and one other Social Science subject', 'Five (5) SSC credit passes including English Language Government or History and at least a pass in Mathematics', 'Three (3) Arts or Social Science subjects', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21347, 'tsuj', 'sociology', 1, 'Sociology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Three (3) Social Science or Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21348, 'tsuj', 'electrical-electronics-engineering', 1, 'Electrical / Electronics Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Mathematics, Physics or Chemistry', 'Five (5) SSC credit passes to include Mathematics, Physics, Chemistry, English Language and any other Science subject.', 'Mathematics, Physics and Chemistry', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21349, 'tsuj', 'mechanical-engineering', 1, 'Mechanical Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes from Chemistry, Physics and Mathematics. (ii) ND upper credit, NCE technical and HND in Mech. Engineering.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics, English Language and any other Science subject.', 'Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21350, 'tsuj', 'education-arts', 1, 'Education Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in relevant subject/NCE merit', 'Five (5) \'O\' Level credit passes in relevant subjects including English Language, Mathematics and subject of specialization.', 'Subject of specialization and any two (2) Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21351, 'tsuj', 'education-and-political-science', 1, 'Education and Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in relevant subjects chosen from Government or History, Economics and Geography/Physics.(ii) NCE merit in Government/History, Economics and Geography/Physics.', 'Five (5) \'O\' Level credit passes or equivalent to include English Language, Government/History and three (3) other subjects.', 'Government or History plus two (2) other Arts or Social Sciences subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21352, 'tsuj', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Economics and one (1) other relevant subject.(ii) NCE merit/credit in Economics and one (1) other subject.', 'Five (5) \'O\' Level credit passes to include English Language, Economics and Mathematics.', 'Economics, Mathematics and one (1) other subject from Geography/Physics, History, Government and Literature in English.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21371, 'trinity', 'religious-studies', 1, 'Religious Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level subjects to include Religious Studies (CRS/IRS).', 'Five (5) SSC credit passes to include English Language and CRS/IRS.', 'CRS/IRS and any other two (2) subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21375, 'uaspoly', 'local-government-studies', 2, 'Local Government Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand.', 'Government or History and any two (2) of Economics, Commerce, Geography and Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21376, 'uaspoly', 'social-development', 2, 'Social Development', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand.', 'Government or History and any two (2) of Economics, Commerce, Geography and Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21377, 'uaspoly', 'mass-communication', 2, 'Mass Communication', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language and Mathematics and any three (3) other subjects from: History, Literature in English, Economics/Commerce, Fine Arts, Government, Biology Physics, Chemistry Basic Electricity Geography, Typewriting, Commerce/Principles of Accounting.', 'Any three (3) subjects from Arts/Social Science/Physical Science.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21378, 'uaspoly', 'mechanical-engineering-technology', 2, 'Mechanical Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any one (1) subject from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required.', 'Mathematics, Chemistry and Physics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21379, 'uaspoly', 'agricultural-technology', 2, 'Agricultural Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. At least \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science, Chemistry and any other Science subject', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21380, 'uaspoly', 'animal-health-and-production-technology', 2, 'Animal Health and Production Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics.', 'Biology/Agricultural Science, Chemistry and any other Science subject', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21381, 'uaspoly', 'production-technology', 2, 'Production Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Biology/Agricultural Science, Mathematics and any three (3) of the following: Geography, Food and Nutrition, Economics, Technical Drawing, English Language, Physics, Chemistry, Nigerian Language, Home Economics. At least \'O\' Level credit passes in English Language and Chemistry are compulsory.', 'Biology/Agricultural Science, Chemistry and any other Science subject', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21382, 'uaspoly', 'building-technology', 2, 'Building Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any three (3) of the following: Economics/Commerce, Technical Drawing/Fine Art, Chemistry, Geography, Further Mathematics Woodwork, Biology, Religious Knowledge, Metal Work, And at least a credit pass in English Language is Compulsory. A pass in Art or Technical Drawing will be an advantage.', 'Mathematics, Physics and Chemistry or Fine Arts.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21383, 'uaspoly', 'public-administration', 2, 'Public Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in English Language not Literature in English and Mathematics and any three (3) subjects of the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography, Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Government, History and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(21384, 'uaspoly', 'business-administration-and-management', 2, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL);
