(21411, 'udu', 'agriculture', 1, 'Agriculture', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Chemistry and one from Biology/Botany/Zoology/Agricultural Science, Economics, Physics, Geography and Geology/Mathematics (Pure & Applied).', 'Five (5) SSC credit passes to include English Language, Biology/Agricultural Science, Chemistry and any one of Mathematics, Physics, Geography and Economics.', 'Chemistry, Biology/Agriculture and any one of Physics or Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21412, 'udu', 'civil-engineering', 1, 'Civil Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) \'A\' Level passes in Physics and Mathematics. (ii) ND/HND upper credit at appropriate levels.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics, English Language and one Science subject', 'Physics, Chemistry and Mathematics', 1, NULL, 0, NULL, NULL, NULL, NULL),
