(21939, 'unizik', 'physical-and-health-education', 1, 'Physical and Health Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in any of Biology, Chemistry, Physics and Mathematics. (ii) NCE merit in Physical Education and credit in Arithmetical process or Mathematics. (iii) Diploma in Health Education, Environmental Sanitation, Physical Education, Social work, Health Administration with overall grades of merit plus three (3) \'O\' Level credit passes/TC II merit which should include English Language. (iv) NCE in Biology, Health Education, and Integrated Science with a pass grade plus two (2) \'O\' Level credit passes/TC II merit passes. (v) Registered Nurse plus five (5) \'O\' Level credit passes to include English Language.', 'i) Five (5) SSC credit passes/TC II merit passes including English Language, Biology or its equivalent. ii) Five (5) SSC credit passes/TC II merit passes to include English Language and Mathematics.', 'Biology and any two (2) relevant subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(21940, 'unizik', 'history', 1, 'History', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in History and any other related subjects.', '5 O\' level credits to include English Language, History/ Government/ Social Studies and any other 3 subjects.', 'History/Government and any other two (2) subjects from Arts and Social Sciences.', 1, NULL, 0, NULL, NULL, NULL, NULL),
