(22261, 'uyo', 'quantity-surveying', 1, 'Quantity Surveying', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes chosen from Mathematics or Physics and Chemistry, Geography or Fine Arts. ND/HND upper credits in relevant field.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any of Fine Art, Geography or Wood Work, Biology, Economics, Technical Drawing, Further. Mathematics., Introduction to Building Construction, Bricklaying/Block laying, Concreting, Wall, Floors and Ceiling Finishing, Joinery, Carpentary, Decorative Painting, Lining, Sign and Design, Wall Hanging, Colour Mixing/Matching and Glazing, Ceramics, Graphics Design, Graphic Printing, Basic Electricity.', 'Physics, Mathematics, and any of Chemistry, Geography, Art, Biology and Economics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22262, 'uyo', 'land-surveying-and-geoinformatics', 1, 'Land Surveying and Geoinformatics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes chosen from Mathematics or Physics and Chemistry, Geography or Fine Arts. ND/HND upper credits in relevant field', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any of Fine Art, Geography or Wood Work, Biology, Economics, Technical Drawing, Further. Mathematics., Introduction to Building Construction, Bricklaying/Block laying, Concreting, Wall, Floors and Ceiling Finishing, Joinery, Carpentary, Decorative Painting, Lining, Sign and Design, Wall Hanging, Colour Mixing/Matching and Glazing, Ceramics, Graphics Design, Graphic Printing, Basic Electricity.', 'Physics, Mathematics, and any of Chemistry, Geography, Art, Biology and Economics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22263, 'uyo', 'computer-engineering', 1, 'Computer Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Three (3) \'A\' Level passes in Pure Mathematics or Pure and Applied Mathematics, Chemistry and Physics.', 'Five (5) SSC credit passes to include Mathematics, Further Mathematics, Chemistry, Physics and English Language.', 'Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22264, 'uyo', 'urban-and-regional-planning', 1, 'Urban and Regional Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) A\' LEVEL passes in Geography and Mathematics ND/HND upper credit in Town Planning or related programmes plus UTME requirements are accepted', 'Five (5) SSC credit passes in English Language, Mathematics, Geography, and any two (2) of Physics, Chemistry, Economics, Government, Biology, Art, History, IRK/CRK, Social Studies and Tech Drawing.', 'Mathematics, Geography and one of Economics, Physics, Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
