(22268, 'uyo', 'estate-management', 1, 'Estate Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in Mathematics, Economics, Geography, Biology and Physics.', 'Five (5) SSCE credit passes including Chemistry, Mathematics and English Language.', 'Mathematics, Economics and one other subject', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22269, 'uyo', 'mechanical-engineering', 1, 'Mechanical Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes from Chemistry, Physics and Mathematics. (ii) ND upper credit, NCE technical and HND in Mech. Engineering.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics, English Language and any other Science subject.', 'Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22270, 'uyo', 'education-arts', 1, 'Education Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in relevant subject/NCE merit', 'Five (5) \'O\' Level credit passes in relevant subjects including English Language, Mathematics and subject of specialization.', 'Subject of specialization and any two (2) Arts subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22271, 'uyo', 'curriculum-studies', 1, 'Curriculum Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes or Nce merit including the relevant subjects', 'Five (5) SSC credit passes including English Language.', 'Any three (3) subjects chosen from Arts/Science.', 1, NULL, 0, NULL, NULL, NULL, NULL),
