(22275, 'uyo', 'special-education', 1, 'Special Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two (2) \'A\' level passes in relevant subjects at GCE/NABTEB/IJMB/JUPEB. At least Lower Credit Pass at ND in any discipline. At least Merit grade at NCE in relevant subjects. In addition to UTME requirements', 'Five \'O\' level credit passes to include English Language, Mathematics and three (3) other subjects.', 'Any three (3) Subjects', 1, NULL, 0, NULL, NULL, NULL, NULL);
INSERT INTO `institution_program` (`id`, `institution_id`, `program_id`, `level_id`, `name`, `description`, `remarks`, `program_mode_id`, `duration`, `tuition_fee`, `utme_cutoff`, `requirements`, `direct_entry`, `o_level`, `utme_subjects`, `accreditation_body_id`, `accreditation_status_id`, `is_distinguished`, `accreditation_grant_date`, `accreditation_expiry_date`, `created_at`, `updated_at`) VALUES
(22276, 'uyo', 'agricultural-science-and-education', 1, 'Agricultural Science and Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least Merit grade at NCE in Agricultural Education. At least two (2) \'A\' level passes at GCE/NABTEB/IJMB/JUPEB or equivalent in Biology/Agricultural Science, and any one (1) of Chemistry, Geography, Economics, Physics, Animal Husbandry and Fisheries. At least Lower Credit Pass at ND in areas related to Agricultural Education. In addition to UTME requirements', 'Five \'O\' level credit passes to include English Language, Mathematics, Biology/Agricultural Science, Chemistry and any one (1) of Geography, Economics, Physics, Animal Husbandry or Fisheries.', 'Any three (3) subjects from Chemistry, Biology, Agriculture, Physics, Economics, Geography and Mathematics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22277, 'uyo', 'education-and-social-studies', 1, 'Education and Social Studies', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two (2) \'A\' level passes at GCE/IJMB/JUPEB or equivalent in Government/History and one (1) other Social Science subject. At least Lower Credit Pass at ND in any Social Science discipline. At least Merit grade at NCE in Social Studies and one (1) other Arts and Social Science discipline. In addition to UTME requirements', 'Five \'O\' level credit passes to include English Language, Mathematics, Government or History or Civic Education, and two (2) other subjects.', 'Any three (3) of Christian Religious Studies, Economics, Geography/Physics, Government, History and Islamic Studies.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22278, 'uyo', 'education-and-social-science', 1, 'Education and Social Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) NCE in two (2) relevant subjects. (ii)Two (2) \'A\' Level passes in relevant subjects.', 'Five (5) \'O\' Level credit passes or equivalent to include English Language and Mathematics.', 'Any three (3) Social Science subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22279, 'uyo', 'education-and-political-science', 1, 'Education and Political Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two (2) \'A\' level passes at GCE/NABTEB/IJMB/JUPEB or equivalent in Government or History and one (1) other Social Science subject. At least Lower Credit Pass at ND in Government/History. At least NCE Merit grade in Political Science and one (1) other Social Science subject. In addition to UTME requirements', 'Five \'O\' level credit passes to include English Language, Mathematics, Government or History or Civic Education, and two (2) other subjects.', 'Government or History plus two (2) other Arts or Social Sciences subjects.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22280, 'uyo', 'education-and-economics', 1, 'Education and Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least two (2) \'A\' level passes at GCE/NABTEB/IJMB/JUPEB or equivalent in Economics and one (1) Social Science subject. At least Lower Credit Pass at ND in any Economics. At least Merit grade at NCE in Economics and one (1) other Social Science subject. In addition to UTME requirements', 'Five (5) \'O\' Level credit passes to include English Language, Economics and Mathematics.', 'Economics, Mathematics and one (1) other subject from Geography/Physics, History, Government and Literature in English.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22281, 'uyo', 'business-education', 1, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'At least Merit grade at NCE in Business Education At least two (2) \'A\' level passes at GCE/NABTEB/IJMB/JUPEB or equivalent in relevant Business/Social Science subjects.At least Lower Credit Pass at ND in areas related to Business.In addition to UTME requirements', 'Five \'O\' level credit passes to include English Language, Mathematics, Economics and any other two (2) subjects from either Business/Social Science/Science.', 'Mathematics, Economics plus one (1) of Literature in English, History, Government, Geography, Chemistry and Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(22318, 'uyocitypoly', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22319, 'uyocitypoly', 'business-administration-and-management', 2, 'Business Administration and Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, not Literature in English and Mathematics and any three (3) subjects from the following: Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22320, 'uyocitypoly', 'statistics', 2, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Basic Science and any three (3) of the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics are compulsory.', 'Any of the three (3): 1. Economics/ Commerce 2. History/Government 3. CRS/IS 4. Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22321, 'uyocitypoly', 'computer-science', 2, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, a basic science and three (3) other subjects chosen from the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics is compulsory.', 'Mathematics and any two (2) of Geography, Physics, Economics or Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22322, 'uyocitypoly', 'computer-engineering-technology', 2, 'Computer Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering a pass in Biology is required. \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics and Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22323, 'uyocitypoly', 'electrical-electronics-engineering-technology', 2, 'Electrical / Electronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22332, 'valleyview', 'accountancy', 2, 'Accountancy', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language not Literature in English and Mathematics and any three (3) subjects from the following Economics/Commerce, Business Methods, Principles of Accounts, Literature in English Geography Office Practice Government, Biology/Agricultural Science, Chemistry, Physics, History/Government Typewriting Shorthand', 'Mathematics and two (2) of Geography, Commerce, Government, Principles of Accounts and Economics.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22333, 'valleyview', 'statistics', 2, 'Statistics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Basic Science and any three (3) of the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics are compulsory.', 'Any of the three (3): 1. Economics/ Commerce 2. History/Government 3. CRS/IS 4. Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
