(22772, 'wufpobk', 'urban-and-regional-planning', 2, 'Urban and Regional Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Geography and three (3) other subjects from: English Language, Economics/Commerce, Fine Art/Technical Drawing, Further Mathematics, Chemistry, Physics, Biology/Agricultural Science, History/Government Business Methods/Bookkeeping and Principles of Accounting One of the three (3) subjects must be a basic science subject. At least a credit pass in English Language is compulsory.', 'Geography and two (2) other subjects from course requirement.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22773, 'wufpobk', 'surveying-and-geoinformatics', 2, 'Surveying and Geoinformatics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics and Physics and any other three (3) subjects from the following: Further Mathematics, Chemistry; Technical Drawing/Fine Art, Geography, Economics/Commerce, Biology/Agricultural Science, English Language, Basic Electricity At least \'O\' Level credit pass in English Language is compulsory.', 'Any three (3) of Chemistry/Agricultural Science, Biology, Economics and Mathematics', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22774, 'wufpobk', 'civil-engineering-technology', 2, 'Civil Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork for Civil Engineering Technology, Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering a pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics and Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22775, 'wufpobk', 'computer-science', 2, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in Mathematics, a basic science and three (3) other subjects chosen from the following: Economics, Geography, Government/History, Further Mathematics, Physics, Chemistry, Biology/Agricultural Science. English Language, Typewriting, \'O\' Level credit passes in English Language and Physics is compulsory.', 'Mathematics and any two (2) of Geography, Physics, Economics or Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22776, 'wufpobk', 'electrical-electronics-engineering-technology', 2, 'Electrical / Electronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22777, 'wufpobk', 'estate-management-and-valuation', 2, 'Estate Management and Valuation', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) \'O\' Level credit passes in Mathematics, English Language, a basic science subject and any two (2) from the following: Geography, Economics/Commerce, Physics, Biology, Chemistry, Technical Drawing, Fine Art, Woodwork, Literature, Metal Work, Principles of Accounts and Book Keeping Government', 'Mathematics and any two (2) of Economics, Arts, Physics, Chemistry, Biology', 2, NULL, 0, NULL, NULL, NULL, NULL),
(22789, 'wufpobked', 'integrated-science-chemistry', 3, 'Integrated Science / Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology and any other Science subject.', 'Any three (3) of Chemistry, Biology, Physics, General Science/Mathematics.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(22790, 'wufpobked', 'mathematics-chemistry', 3, 'Mathematics / Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry and any other two (2) Science subjects.', 'Mathematics, Chemistry and Biology/Physics.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(22791, 'wufpobked', 'business-education', 3, 'Business Education', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'SSC credit passes or TC II merits in English Language and any three (3) of: 1. Economics 2. Accounts 3. Government 4. Geography 5. History 6. Business Method 7. Statistics 8. Commerce 9. Any Science subjects NB: GROUP A: Commercial Arithmetic Costing, Principles of Accounts, Book Keeping Mathematics, Statistics. GROUP B: Office Practice, Business Method, Commerce, Economics.', 'Mathematics, Economics and any of Geography, Commerce and Principles of Accounts.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(22792, 'wufpobked', 'integrated-science-mathematics', 3, 'Integrated Science / Mathematics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics and any three (3) of the following 1. Biology/Agricultural Science 2. Chemistry 3. Physics and 4. General Science', 'Mathematics and any two (2) of: Biology, Physics and Chemistry.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(22793, 'wufpobked', 'integrated-science-physics', 3, 'Integrated Science / Physics', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics Physics and any two (2) Science subjects', 'Physics and any other two (2) Science subjects.', 3, NULL, 0, NULL, NULL, NULL, NULL),
(22794, 'wufpobked', 'computer-education-chemistry', 3, 'Computer Education / Chemistry', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Physics and any other Science subject.', 'Mathematics, Chemistry/Physics and any other Science subject', 3, NULL, 0, NULL, NULL, NULL, NULL),
(22795, 'wufpobked', 'computer-education-biology', 3, 'Computer Education / Biology', NULL, NULL, 1, NULL, NULL, NULL, NULL, '', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Biology/Integrated Science and any other Science subject.', 'Biology and any two (2) of Chemistry, Mathematics and Physics', 3, NULL, 0, NULL, NULL, NULL, NULL),
