(23783, 'mti', 'welding-and-fabrication-technology', 2, 'Welding and Fabrication Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NIL', 'Five (5) SSC credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from Biology/ Agricultural Science, Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Technology), Further Mathematics, English Language, Geography, Economics/ Commerce. At least a credit pass in English Language is required.', 'Mathematics, Physics and Chemistry', 2, NULL, 0, NULL, NULL, NULL, NULL),
(23784, 'mti', 'electrical-electronics-engineering-technology', 2, 'Electrical / Electronics Engineering Technology', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'NIL', 'Five (5) \'O\' Level credit passes in Mathematics, Physics and Chemistry and any two (2) subjects from: Biology/Agricultural Science Technical Drawing, Basic Electronics/Basic Electricity, Auto Mechanics, Metal Work, Woodwork (for Civil Engineering Tech.), Further Mathematics English Language, Geography, Economics/Commerce. For Marine Engineering and Industrial Safety & Environmental Engineering. \'O\' Level pass in Biology is required. At least \'O\' Level credit pass in English Language is required.', 'Mathematics, Physics, Chemistry.', 2, NULL, 0, NULL, NULL, NULL, NULL),
