(25540, 'uda', 'mechanical-engineering', 1, 'Mechanical Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes from Chemistry, Physics and Mathematics. (ii) ND upper credit, NCE technical and HND in Mech. Engineering.', 'Five (5) SSC credit passes to include Physics, Chemistry, Mathematics, English Language and any other Science subject.', 'Mathematics, Physics and Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(25541, 'uda', 'fine-and-applied-arts', 1, 'Fine and Applied Arts', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) \'A\' Level passes in Fine Arts/Technical Drawing and any one of Mathematics, Economics, Geography., Biology, Physics and Chemistry. (ii) ND/HND credit in Fine Arts.', 'Five (5) SSC passes to include English Language, Mathematics, Fine Arts and two (2) other from social science subject. Mathematics, Arts and one Social Science subject. For NTC the other two (2) relevant subjects could be from any of the following: Decorative Painting; Spray Painting, Lining, Sign and Design; Wall Handling, Colour Mixing/ For NTC the other two (2) relevant subjects could be from any of the following: Decorative Painting; Spray Painting, Lining, Sign and Design; Wall Handling, Colour Mixing/Matching and Glazing; Graphic Painting; Ceramics; Basic Electricity; Building/Engineering Drawing.', 'Chemistry, Mathematics and Fine Arts/Physics.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(25542, 'uda', 'urban-and-regional-planning', 1, 'Urban and Regional Planning', NULL, NULL, 1, NULL, NULL, NULL, NULL, '(i) Two (2) A\' LEVEL passes in Geography and Mathematics (ii) ND/HND upper credit in Town Planning or related programmes plus UTME requirements are accepted.', 'Five (5) SSC credit passes in English Language, Mathematics, Geography, and any two (2) of Physics, Chemistry, Economics, Government, Biology, Art, History, IRK/CRK, Social Studies and Tech Drawing.', 'Mathematics, Geography and one of Economics, Physics, Chemistry.', 1, NULL, 0, NULL, NULL, NULL, NULL),
