(26149, 'basu', 'environmental-health', 1, 'Environmental Health', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level IJMB passes in Physics, Chemistry, Biology and Zoology or NCE/ND/HND in relevant discipline with at least lower credit in addition to five \'O\' credit passes.', 'Five \'O\' level credit passes which must include English Language, Mathematics, Physics, Chemistry and Biology.', 'English Language, Mathematics, Chemistry and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
(26150, 'basu', 'nursing-nursing-science', 1, 'Nursing / Nursing Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' level IJMB passes in Biology Chemistry and Physics or NCE/ND/HND/First Degree in any relevant discipline and registered members of any recognized council or relevant body.', 'Five \'O\' level credit passes in English, Mathematics, Biology, Physics and Chemistry.', 'English Language, Mathematics, Physics, Chemistry and Biology', 1, NULL, 0, NULL, NULL, NULL, NULL),
