(28694, 'miva', 'cyber-security', 1, 'Cyber Security', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in sciences subjects, including Mathematics. HND/ND/NCE at Credit/Merit level in relevant programmes/subjects.', 'Five (5) SSC credit passes including English Language, Mathematics, Physics and two (2) other Science subjects.', 'Use of English, Mathematics, Physics and one (1) of Biology, Chemistry, Agricultural Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(28695, 'miva', 'software-engineering', 1, 'Software Engineering', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in sciences subjects, including Mathematics. HND/ND/NCE at Credit/Merit level in relevant programmes/subjects.', 'Five (5) SSC credit passes including English Language, Mathematics, Physics and two (2) other Science subjects.', 'Use of English, Mathematics, Physics and one (1) of Biology, Chemistry, Agricultural Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(28696, 'miva', 'computer-science', 1, 'Computer Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes in sciences subjects, including Mathematics. HND/ND/NCE at Credit/Merit level in relevant programmes/subjects.', 'Five (5) SSC credit passes including English Language, Mathematics, Physics and two (2) other Science subjects.', 'Use of English, Mathematics, Physics and one (1) of Biology, Chemistry, Agricultural Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(28697, 'miva', 'data-science', 1, 'Data Science', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics and one of Accounting, Mathematics, Statistics, Business Management. HND/ND/NCE at Credit/Merit level in relevant programmes/subjects.', 'Five (5) SSC credit passes including English Language, Mathematics, Physics and two (2) other Science subjects.', 'Use of English, Mathematics, Physics and one (1) of Biology, Chemistry, Agricultural Science, Economics and Geography.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(28698, 'miva', 'business-management', 1, 'Business Management', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics and one of Accounting, Mathematics, Statistics, Business Management. HND/ND/NCE at Credit/Merit level in relevant programmes/subjects.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) Art, Commercial or Social Science subjects.', 'Use of English, Mathematics, Economics and any other Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(28699, 'miva', 'economics', 1, 'Economics', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics and one of Accounting, Mathematics, Statistics, Business Management, Geography, History, Government. HND/ND/NCE at Credit/Merit level in relevant programmes/subjects.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) Art, Commercial or Social Science subjects.', 'Use of English, Mathematics, Economics and any other Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(28700, 'miva', 'accounting', 1, 'Accounting', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) \'A\' Level passes including Economics and one of Accounting, Mathematics, Statistics, Business Management. HND/ND/NCE at Credit/Merit level in relevant programmes/subjects.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics and two (2) other relevant subjects.', 'Use of English, Mathematics, Economics and any other Social Science subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
(28701, 'miva', 'public-policy-and-administration', 1, 'Public Policy and Administration', NULL, NULL, 1, NULL, NULL, NULL, NULL, 'Two (2) A\' level/IJMB/JUPEB passes in Economics and Government/History/Social Studies/Sociology.HND/ND/NCE at Credit/Merit level in relevant programmes/subjects.', 'Five (5) SSC O\'Level credit passes to include English Language, Economics or Government or History or Civic Education. Candidates must obtain at least a pass in Mathematics.', 'Use of English, Government, Economics and any other subject.', 1, NULL, 0, NULL, NULL, NULL, NULL),
